// ==================== KUTLAMA OVERLAY ====================
// KutlamaOverlay — ödül/seviye/başarım kutlama animasyonları (Veridian teması)
// Backend kutlama kuyruğundan gelen olayları sırayla, ekranı karartarak oynatır.
// tur: 'seviye' (ışık sütunu + rozet) | 'odul' (altın patlama) | 'basarim' (konfeti kart)

function KutlamaOverlay({ kutlamalar, onKapat }) {
  const [idx, setIdx] = React.useState(0);
  if (!kutlamalar || !kutlamalar.length) return null;
  const k = kutlamalar[idx];
  if (!k) return null;

  const ileri = () => {
    if (idx < kutlamalar.length - 1) setIdx(idx + 1);
    else onKapat(kutlamalar.map((x) => x.id));
  };

  return (
    <div onClick={ileri} style={{
      position: "fixed", inset: 0, zIndex: 9999, cursor: "pointer",
      background: "rgba(10,20,15,0.93)", backdropFilter: "blur(8px)",
      display: "flex", alignItems: "center", justifyContent: "center",
      animation: "kutlamaGir 0.4s ease",
    }}>
      <style>{`
        @keyframes kutlamaGir { from { opacity: 0 } to { opacity: 1 } }
        @keyframes rayDon { from { transform: translate(-50%,-50%) rotate(0deg) } to { transform: translate(-50%,-50%) rotate(360deg) } }
        @keyframes madalyaGir { 0% { transform: translate(-50%,-50%) scale(0) rotate(-180deg); opacity: 0 } 60% { transform: translate(-50%,-50%) scale(1.15) rotate(10deg) } 100% { transform: translate(-50%,-50%) scale(1) rotate(0deg); opacity: 1 } }
        @keyframes parcaUc { 0% { transform: scale(0); opacity: 1 } 100% { transform: scale(1) translate(var(--dx),var(--dy)); opacity: 0 } }
        @keyframes rozetYuksel { 0% { transform: translate(-50%,20px) scale(0.6); opacity: 0 } 100% { transform: translate(-50%,-50%) scale(1); opacity: 1 } }
        @keyframes yaziGir { 0% { transform: translateY(20px); opacity: 0 } 100% { transform: translateY(0); opacity: 1 } }
        @keyframes konfetiDus { 0% { transform: translateY(-20px) rotate(0deg); opacity: 1 } 100% { transform: translateY(120vh) rotate(720deg); opacity: 0.3 } }
        @keyframes kartZipla { 0% { transform: scale(0.5); opacity: 0 } 60% { transform: scale(1.08) } 100% { transform: scale(1); opacity: 1 } }
        @keyframes kivilcim { 0%,100% { opacity: 0.2 } 50% { opacity: 1 } }
      `}</style>

      {k.tur === "odul" && <OdulKutlama k={k} />}
      {k.tur === "seviye" && <SeviyeKutlama k={k} />}
      {k.tur === "basarim" && <BasarimKutlama k={k} />}

      <div style={{ position: "absolute", bottom: 40, left: 0, right: 0, textAlign: "center", color: "rgba(255,255,255,0.5)", fontSize: 15, letterSpacing: 1 }}>
        {kutlamalar.length > 1 ? `${idx + 1} / ${kutlamalar.length} · devam için dokun` : "Kapatmak için dokun"}
      </div>
    </div>
  );
}

// ---- ÖDÜL: altın patlama ----
function OdulKutlama({ k }) {
  const raylar = Array.from({ length: 16 });
  const parcalar = Array.from({ length: 24 });
  return (
    <div style={{ position: "relative", width: "100%", maxWidth: 420, height: 500 }}>
      <div style={{ position: "absolute", top: "38%", left: "50%", width: 340, height: 340, transform: "translate(-50%,-50%)", animation: "rayDon 8s linear infinite" }}>
        {raylar.map((_, i) => (
          <div key={i} style={{ position: "absolute", top: "50%", left: "50%", width: 170, height: 3, transformOrigin: "left center", transform: `rotate(${i * 22.5}deg)`, background: "linear-gradient(90deg,rgba(201,162,75,0.9),transparent)" }} />
        ))}
      </div>
      {parcalar.map((_, i) => {
        const a = (i / parcalar.length) * Math.PI * 2, dist = 90 + (i % 5) * 30;
        return <div key={i} style={{ position: "absolute", top: "38%", left: "50%", width: 8, height: 8, borderRadius: "50%", background: "#F5D76E", boxShadow: "0 0 8px #C9A24B", "--dx": `${Math.cos(a) * dist}px`, "--dy": `${Math.sin(a) * dist}px`, animation: `parcaUc 1.2s ease-out ${i * 0.02}s forwards` }} />;
      })}
      <div style={{ position: "absolute", top: "38%", left: "50%", width: 150, height: 150, borderRadius: "50%", background: "radial-gradient(circle at 35% 30%,#F5D76E,#C9A24B 55%,#9a7d1a)", boxShadow: "0 0 60px rgba(201,162,75,0.7),inset 0 -8px 20px rgba(0,0,0,0.3)", border: "4px solid rgba(255,255,255,0.25)", display: "flex", alignItems: "center", justifyContent: "center", animation: "madalyaGir 0.7s ease-out", fontSize: 66 }}>{k.gorsel || "🏅"}</div>
      <div style={{ position: "absolute", top: "62%", left: 0, right: 0, textAlign: "center", animation: "yaziGir 0.5s ease-out 0.3s both" }}>
        <div style={{ fontFamily: "'Cormorant Garamond',serif", fontSize: 15, letterSpacing: 3, color: "#C9A24B", textTransform: "uppercase", marginBottom: 10 }}>✦ Tebrikler ✦</div>
        <div style={{ fontFamily: "'Cormorant Garamond',serif", fontSize: 30, fontWeight: 700, color: "#fff", marginBottom: 8 }}>{k.baslik}</div>
        <div style={{ fontSize: 14, color: "rgba(255,255,255,0.7)" }}>{k.alt_metin}</div>
      </div>
    </div>
  );
}

// ---- SEVİYE: ışık sütunu + rozet yükselir ----
