// ==================== KARİYER & GÖREVLER ====================
// ==================== AI KOÇ KARTI (Hamle 1: AI Kişiselleştirme) ====================
// ============ Okunmamış duyuru katmanı ============
// Yayınevinden gelen duyuru (genel ya da kişiye özel) uygulama açılır açılmaz
// karşıya çıkar. Okunanlar cihazda işaretlenir, bir daha gösterilmez.
function OkunmamisDuyurular({ duyurular, yazarId, token }) {
  // GERÇEK HATA (5 Ağu 2026, kullanıcı raporu — "40 kez ANLADIM'a tıklamama
  // rağmen çıkıyor, bazen takılıp kalıyor"): bu bileşen backend'e bildirmek
  // için localStorage.getItem("mst_token") kullanıyordu ama bu anahtar
  // UYGULAMANIN HİÇBİR YERİNDE YAZILMIYORDU — her zaman null, backend'e
  // "okundu" isteği HİÇ GİTMEMİŞTİ. Farklı cihaz/tarayıcı/PWA örneğinden
  // girildiğinde her biri kendi localStorage'ında "okunmadı" görüyordu,
  // birbirleriyle hiç senkronize olamıyorlardı. Artık gerçek session
  // token'ı prop olarak geçiliyor (session.token) — backend GERÇEK ortak
  // kaynak oluyor, localStorage yalnız hızlı önbellek.
  const [okunanlar, setOkunanlar] = useState(() => {
    try { return JSON.parse(localStorage.getItem(`mst_okunan_${yazarId || "genel"}`) || "[]"); } catch { return []; }
  });
  const [sira, setSira] = useState(0);

  // yazarId geç gelirse (account henüz yüklenmeden ilk render) — doğru
  // anahtardan yeniden yükle. Eskiden bu hiç yapılmıyordu, "genel"
  // anahtarında takılı kalabiliyordu.
  React.useEffect(() => {
    if (!yazarId) return;
    try {
      const v = JSON.parse(localStorage.getItem(`mst_okunan_${yazarId}`) || "[]");
      setOkunanlar(v);
    } catch {}
  }, [yazarId]);

  const bekleyen = (duyurular || []).filter((d) => d && d.id != null && !okunanlar.includes(String(d.id)));
  if (!bekleyen.length) return null;

  // Index güvenliği: sira, bekleyen.length'i aşarsa (liste küçüldüğünde)
  // "bazen takılıp kalıyor" sorununun bir sebebi buydu — artık her zaman
  // geçerli bir aralığa sıkıştırılıyor.
  const guvenliSira = Math.min(sira, bekleyen.length - 1);
  const d = bekleyen[guvenliSira];
  const sonuncu = guvenliSira >= bekleyen.length - 1;

  const okundu = () => {
    if (!d) return; // güvenlik — hiçbir zaman undefined'a işlem yapılmaz
    const mevcutId = String(d.id);
    const yeni = [...okunanlar, mevcutId].filter(Boolean);
    setOkunanlar(yeni);
    try { localStorage.setItem(`mst_okunan_${yazarId || "genel"}`, JSON.stringify(yeni.slice(-100))); } catch {}
    // Backend'e bildir — artık GERÇEKTEN gidiyor (token doğru kaynaktan).
    if (token) {
      fetch(`${BACKEND_URL}/api/author/duyuru-okundu`, {
        method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({ duyuruIds: [mevcutId] }),
      }).catch(() => {});
    }
    if (!sonuncu) setSira(s => s + 1);
  };

  return (
    <div style={{
      position: "fixed", inset: 0, zIndex: 90, background: "rgba(4,8,18,.86)",
      display: "flex", alignItems: "center", justifyContent: "center", padding: 20,
    }}>
      <div style={{
        width: "100%", maxWidth: 460,
        background: "linear-gradient(160deg, rgba(201,162,75,.07), rgba(10,20,40,.72))",
        border: "1px solid rgba(201,162,75,.38)", padding: "30px 28px 26px",
        backdropFilter: "blur(2px)",
      }}>
        <div style={{ fontSize: 10.5, letterSpacing: "0.28em", color: "rgba(201,162,75,.82)", fontWeight: 600, marginBottom: 14 }}>
          MST YAYINCILIK{bekleyen.length > 1 ? ` · ${sira + 1}/${bekleyen.length}` : ""}
        </div>

        <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 26, color: "#fff", fontWeight: 600, lineHeight: 1.25, marginBottom: 14 }}>
          {d.title}
        </div>

        <div style={{ fontSize: 14.5, color: "rgba(245,240,228,.82)", lineHeight: 1.8, fontWeight: 300, whiteSpace: "pre-wrap", maxHeight: "46vh", overflowY: "auto" }}>
          {d.body}
        </div>

        {d.date && (
          <div style={{ fontSize: 11.5, color: "rgba(245,240,228,.45)", marginTop: 16 }}>{d.date}</div>
        )}

        <div style={{ marginTop: 22, display: "flex", alignItems: "center", justifyContent: "center", gap: 14 }}>
          <span style={{ height: 1, flex: 1, background: "linear-gradient(90deg,transparent,rgba(201,162,75,.6))" }} />
          <span style={{ width: 6, height: 6, background: "#C9A24B", transform: "rotate(45deg)" }} />
          <span style={{ height: 1, flex: 1, background: "linear-gradient(90deg,rgba(201,162,75,.6),transparent)" }} />
        </div>

        <Dugme tur="asil" onClick={okundu}>{sonuncu ? "ANLADIM" : "SONRAKİ"}</Dugme>
      </div>
    </div>
  );
}

function AICocKarti({ token, onAc }) {
  const [karsilama, setKarsilama] = useState(null);
  const [durum, setDurum] = useState(null);
  const [bildirim, setBildirim] = useState(null);
  const [hedef, setHedef] = useState(null);

  const cekAi = React.useCallback(async (yol) => {
    try { const r = await fetch(`${BACKEND_URL}/api/author/ai/${yol}`, { headers: { Authorization: `Bearer ${token}` } }); return await r.json(); }
    catch { return null; }
  }, [token]);
  const cekMenajer = React.useCallback(async (yol) => {
    try { const r = await fetch(`${BACKEND_URL}/api/author/menajer/${yol}`, { headers: { Authorization: `Bearer ${token}` } }); return await r.json(); }
    catch { return null; }
  }, [token]);

  React.useEffect(() => {
    cekMenajer("karsilama").then((d) => { if (d) { setKarsilama(d.mesaj); setDurum(d.durum); } });
    cekAi("bildirim").then((d) => d && setBildirim(d.bildirim));
    cekAi("hedef").then((d) => d && setHedef(d.oneri));
  }, [cekAi, cekMenajer]);

  return (
    <div
      onClick={() => onAc && onAc()}
      style={{ background: THEME.yuzey, border: "1px solid rgba(201,162,75,.30)", borderRadius: 0, padding: "20px 22px", marginBottom: 24, cursor: "pointer", position: "relative", overflow: "hidden" }}>
      <style>{`
        @keyframes mgrAura { 0%,100% { opacity:.5; transform: scale(1);} 50% { opacity:.9; transform: scale(1.06);} }
        .mgr-card-arrow { transition: transform .2s ease; }
        .mgr-card:hover .mgr-card-arrow { transform: translateX(3px); }
      `}</style>

      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: karsilama || hedef ? 12 : 0 }}>
        <div style={{ position: "relative", width: 38, height: 38, flexShrink: 0 }}>
          <div style={{ position: "absolute", inset: -3, borderRadius: "50%", background: "radial-gradient(circle, rgba(201,162,75,.4), transparent 70%)", animation: "mgrAura 3s ease-in-out infinite" }} />
          <div style={{ position: "relative", width: 38, height: 38, borderRadius: "50%", background: "radial-gradient(circle at 40% 35%,#C9A24B,#0C1730)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 19 }}>🤝</div>
        </div>
        <div style={{ flex: 1 }}>
          <div style={{ fontSize: 14.5, fontWeight: 700, color: THEME.textLight, fontFamily: "'Cormorant Garamond',serif" }}>Menajerim</div>
          <div style={{ fontSize: 12.5, color: "rgba(245,240,228,.62)", fontWeight: 300 }}>Yazarlık danışmanınız · abonelik</div>
        </div>
        <span className="mgr-card-arrow" style={{ fontSize: 18, color: THEME.cyan }}>→</span>
      </div>

      {/* Tek mesaj — karşılama varsa o, yoksa sıradaki adım.
          Üçü birden gösterilince kart şişiyor ve aynı şey tekrarlanıyordu. */}
      {(karsilama || hedef) && (
        <div style={{ background: "rgba(255,255,255,.015)", border: "1px solid rgba(201,162,75,.24)", padding: "16px 18px", fontSize: 14.5, color: THEME.textLight, lineHeight: 1.75, fontWeight: 300 }}>
          {karsilama || hedef}
        </div>
      )}

      {/* Sıradaki adım — karşılamadan farklıysa ve kısa bir satır olarak */}
      {karsilama && hedef && (
        <div style={{ marginTop: 10, paddingTop: 12, borderTop: "1px solid rgba(201,162,75,.16)" }}>
          <div style={{ fontSize: 10.5, letterSpacing: "0.28em", color: "rgba(201,162,75,.82)", marginBottom: 7 }}>SIRADAKİ ADIM</div>
          <div style={{ fontSize: 14, color: "rgba(245,240,228,.80)", lineHeight: 1.7, fontWeight: 300 }}>{hedef}</div>
        </div>
      )}

      {/* Sohbete davet */}
      <div style={{ marginTop: 12, display: "flex", alignItems: "center", justifyContent: "center", gap: 6, fontSize: 15, fontWeight: 600, color: THEME.cyan }}>
        <span style={{ fontSize: 10.5, letterSpacing: "0.28em", textTransform: "uppercase" }}>Menajerimle konuşmak için dokun</span>
      </div>
    </div>
  );
}

// ==================== SERİ & GÜNLÜK HEDEF KARTI (Hamle 4) ====================
function SeriKarti({ katman }) {
  const seri = katman.seri || 0;
  const freeze = katman.freeze || 0;
  const enUzun = katman.enUzunSeri || 0;
  const hedef = katman.gunlukHedef;
  return (
    <div style={{ display: "flex", gap: 10, marginBottom: 16, flexWrap: "wrap" }}>
      {/* Seri sayacı */}
      <div style={{ flex: "1 1 140px", background: THEME.yuzey, border: `1px solid ${seri > 0 ? THEME.gold : THEME.border}`, borderRadius: 0, padding: "14px 16px", display: "flex", alignItems: "center", gap: 12 }}>
        <div style={{ fontSize: 32 }}>🔥</div>
        <div>
          <div style={{ fontSize: 22, fontWeight: 700, color: THEME.gold, fontFamily: "'Cormorant Garamond',serif", lineHeight: 1 }}>{seri}</div>
          <div style={{ fontSize: 14, color: THEME.textMuted, marginTop: 2 }}>günlük seri</div>
          <div style={{ fontSize: 14.5, color: THEME.textFaint, marginTop: 3 }}>
            {freeze > 0 ? `❄️ ${freeze} dondurma hakkı` : "❄️ dondurma yok"} · rekor {enUzun}
          </div>
        </div>
      </div>
      {/* Günlük hedef */}
      {hedef && (
        <div style={{ flex: "2 1 200px", background: hedef.tamamlandi ? "rgba(45,106,79,.08)" : THEME.panelBg, border: `1px solid ${hedef.tamamlandi ? THEME.success : THEME.border}`, borderRadius: 0, padding: "12px 14px" }}>
          <div style={{ fontSize: 14.5, letterSpacing: "0.05em", color: THEME.cyan, marginBottom: 4 }}>BUGÜNKÜ HEDEFİN</div>
          <div style={{ fontSize: 14, color: THEME.textLight, lineHeight: 1.4 }}>{hedef.hedef_metin || hedef.hedefMetin}</div>
          {hedef.tamamlandi ? <div style={{ fontSize: 14, color: THEME.success, marginTop: 6, fontWeight: 600 }}>✓ Tamamlandı</div>
            : <div style={{ fontSize: 15, color: THEME.textMuted, marginTop: 6 }}>Tamamlayınca +{hedef.xp_odul || 50} XP</div>}
        </div>
      )}
    </div>
  );
}

// ==================== KARİYER & GÖREVLER (Oyunlaştırma) ====================
// oyun: backend /author/oyun yanıtı. token ile kanıt yükleme / dükkan alımı yapılır.
function GameSection({ oyun, token, onRefresh, katman }) {
  const [altTab, setAltTab] = useState("gorevler"); // gorevler | kariyer | topluluk | dukkan | basarim
  if (!oyun) return <div style={{ color: THEME.textMuted, fontSize: 14.5, padding: 20, textAlign: "center" }}>Kariyer verileri yükleniyor…</div>;

  // Standart paket kilidi: 100 satışa kadar oyun kapalı
  if (oyun.kilitli) {
    return (
      <div style={{ textAlign: "center", padding: "40px 20px" }}>
        <div style={{ fontSize: 48, marginBottom: 18 }}>🔒</div>
        <div style={{ fontFamily: "'Cormorant Garamond',serif", fontSize: 20, fontWeight: 700, color: THEME.textLight, marginBottom: 10 }}>Kariyer Sistemi Kilitli</div>
        <div style={{ fontSize: 15, color: THEME.textMuted, lineHeight: 1.6, maxWidth: 320, margin: "0 auto 20px" }}>
          {oyun.mesaj || "Kariyer ve ödül sistemi, ilk 100 satışa ulaşınca açılır."}
        </div>
        <div style={{ background: THEME.yuzey, border: `1px solid ${THEME.gold}`, borderRadius: 0, padding: 16, maxWidth: 300, margin: "0 auto" }}>
          <div style={{ fontSize: 14, color: THEME.textMuted, marginBottom: 8 }}>İLERLEMEN</div>
          <div style={{ fontSize: 22, fontWeight: 700, color: THEME.gold, fontFamily: "monospace", marginBottom: 8 }}>{oyun.toplamSatis || 0} / 100</div>
          <div style={{ height: 8, background: THEME.divider, borderRadius: 0, overflow: "hidden" }}>
            <div style={{ height: "100%", width: `${Math.min(100, (oyun.toplamSatis || 0))}%`, background: `linear-gradient(90deg,${THEME.cyan},${THEME.gold})`, borderRadius: 0 }} />
          </div>
          <div style={{ fontSize: 14.5, color: THEME.textMuted, marginTop: 8 }}>{oyun.kalanSatis || 100} satış kaldı</div>
        </div>
      </div>
    );
  }

  const seviye = oyun.seviye || { no: 1, unvan: "Yeni Yazar", rozet: "Tomurcuk", gorsel: "◈", xp: 0 };
  const sonraki = oyun.sonrakiSeviye;
  const xp = oyun.xp || 0;
  const ilerlemePct = sonraki ? Math.min(100, Math.round(((xp - seviye.xp) / (sonraki.xp - seviye.xp)) * 100)) : 100;

  return (
    <div>
      {/* Seri + günlük hedef (Hamle 4: Katmanlı Mimari) */}
      {katman && <SeriKarti katman={katman} />}

      {/* Kariyer başlığı — her zaman üstte */}
      <div style={{ background: THEME.yuzey, border: `1px solid ${THEME.gold}`, borderRadius: 0, padding: 16, marginBottom: 18 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
          <div style={{ width: 60, height: 60, borderRadius: "50%", background: "radial-gradient(circle at 40% 35%,#C9A24B,#0C1730)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 30, flexShrink: 0, boxShadow: "0 4px 14px rgba(201,162,75,0.4)" }}>{seviye.gorsel}</div>
          <div style={{ flex: 1 }}>
            <div style={{ fontFamily: "'Cormorant Garamond',serif", fontSize: 19, fontWeight: 700, color: THEME.textLight }}>{seviye.unvan}</div>
            <div style={{ fontSize: 15, color: THEME.gold, marginBottom: 6 }}>{seviye.gorsel} {seviye.rozet} · {xp} XP</div>
            <div style={{ height: 7, background: THEME.divider, borderRadius: 0, overflow: "hidden" }}>
              <div style={{ height: "100%", width: `${ilerlemePct}%`, background: `linear-gradient(90deg,${THEME.cyan},${THEME.gold})`, borderRadius: 0, transition: "width .5s" }} />
            </div>
            <div style={{ fontSize: 15, color: THEME.textMuted, marginTop: 4 }}>
              {sonraki ? `Sonraki: ${sonraki.unvan} (${sonraki.xp - xp} XP kaldı)` : "En üst seviyedesin! 🏛️"}
            </div>
          </div>
        </div>
      </div>

      {/* Alt sekmeler */}
      <div style={{ display: "flex", gap: 6, marginBottom: 14, flexWrap: "wrap" }}>
        {[["gorevler", "Görevler"], ["kariyer", "Kariyer"], ["topluluk", "Topluluk"], ["dukkan", "Ödül Dükkanı"], ["basarim", "Başarımlar"]].map(([k, l]) => (
          <button key={k} onClick={() => setAltTab(k)} style={{
            flex: "1 1 auto", padding: "8px 6px", fontSize: 14, fontWeight: 600, borderRadius: 0, cursor: "pointer",
            border: `1px solid ${altTab === k ? THEME.gold : THEME.border}`,
            background: altTab === k ? THEME.gold : "transparent",
            color: altTab === k ? "#0C1730" : THEME.textMuted,
          }}>{l}</button>
        ))}
      </div>

      {altTab === "gorevler" && <GorevListesi oyun={oyun} token={token} onRefresh={onRefresh} />}
      {altTab === "kariyer" && <KariyerYolu oyun={oyun} />}
      {altTab === "topluluk" && <ToplulukBolumu token={token} />}
      {altTab === "dukkan" && <OdulDukkani oyun={oyun} token={token} onRefresh={onRefresh} />}
      {altTab === "basarim" && <BasarimVitrini oyun={oyun} />}
    </div>
  );
}

function GorevListesi({ oyun, token, onRefresh }) {
  const gorevler = oyun.gorevler || [];
  const periyotEtiket = { gunluk: "Günlük", haftalik: "Haftalık", aylik: "Aylık", sezonluk: "Sezonluk", tek_sefer: "Kilometre Taşları" };
  // Hizmet (kariyer-destek) görevlerini ayır
  const hizmetGorevler = gorevler.filter((g) => g.tip === "hizmet");
  const digerGorevler = gorevler.filter((g) => g.tip !== "hizmet");
  const gruplar = {};
  digerGorevler.forEach((g) => { (gruplar[g.periyot] = gruplar[g.periyot] || []).push(g); });
  const sira = ["gunluk", "haftalik", "aylik", "sezonluk", "tek_sefer"];

  if (!gorevler.length) return <div style={{ color: THEME.textMuted, fontSize: 14.5, padding: 16, textAlign: "center" }}>Şu an açık görev yok. Seviye atladıkça yeni görevler açılır.</div>;

  return (
    <div>
      {sira.filter((p) => gruplar[p]).map((p) => (
        <div key={p} style={{ marginBottom: 48 }}>
          {/* Sitedeki .grouptitle: serif başlık + sağa doğru sönen altın çizgi */}
          <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 16 }}>
            <span style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "clamp(18px, 5.2vw, 25px)", color: "#F0D68A", fontWeight: 600 }}>
              {periyotEtiket[p] || p}
            </span>
            <span style={{ flex: 1, height: 1, background: "linear-gradient(90deg,rgba(201,162,75,.45),transparent)" }} />
          </div>
          {/* Levha: kapsayıcı altın, hücreler arası 2px → saç teli çizgiler */}
          <div style={{ display: "grid", gap: 2, background: "rgba(201,162,75,.16)", border: "1px solid rgba(201,162,75,.24)" }}>
            {gruplar[p].map((g) => <GorevKart key={g.id} g={g} token={token} onRefresh={onRefresh} />)}
          </div>
        </div>
      ))}
      {hizmetGorevler.length > 0 && (
        <div style={{ marginBottom: 18 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 10 }}>
            <span style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "clamp(18px, 5.2vw, 25px)", color: "#F0D68A", fontWeight: 600 }}>Kariyer &amp; Gelişim Desteği</span>
            <span style={{ flex: 1, height: 1, background: "linear-gradient(90deg,rgba(201,162,75,.45),transparent)" }} />
          </div>
          <div style={{ fontSize: 14, color: THEME.textMuted, marginBottom: 10, lineHeight: 1.5 }}>MST''nin sunduğu gelişim fırsatları. Bu hizmetlerden yararlandığında ödülün otomatik tanımlanır.</div>
          <div style={{ display: "grid", gap: 2, background: "rgba(201,162,75,.16)", border: "1px solid rgba(201,162,75,.24)" }}>
            {hizmetGorevler.map((g) => <GorevKart key={g.id} g={g} token={token} onRefresh={onRefresh} />)}
          </div>
        </div>
      )}
    </div>
  );
}

function GorevKart({ g, token, onRefresh }) {
  const [kanitAcik, setKanitAcik] = useState(false);
  const [kanitUrl, setKanitUrl] = useState("");
  const [gonderiliyor, setGonderiliyor] = useState(false);
  const [msg, setMsg] = useState(null);
  const tamam = g.durum === "tamamlandi";
  const bekliyor = g.durum === "kanit_bekliyor";
  const pct = g.hedef_deger ? Math.min(100, Math.round((g.ilerleme / g.hedef_deger) * 100)) : 0;
  const kademeRenk = { kucuk: THEME.textMuted, orta: THEME.cyan, buyuk: THEME.gold, efsane: "#B45309" }[g.kademe] || THEME.textMuted;

  const kanitGonder = async () => {
    setGonderiliyor(true); setMsg(null);
    try {
      const res = await fetch(`${BACKEND_URL}/api/author/oyun/kanit`, {
        method: "POST", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
        body: JSON.stringify({ gorevId: g.id, kanitUrl }),
      });
      const data = await res.json();
      if (data.ok) { setMsg({ ok: true, text: data.mesaj }); setKanitAcik(false); onRefresh && onRefresh(); }
      else setMsg({ ok: false, text: data.error || "Gönderilemedi" });
    } catch { setMsg({ ok: false, text: "Bağlantı hatası" }); }
    finally { setGonderiliyor(false); }
  };

  return (
    <div style={{
      background: tamam ? "rgba(159,199,168,.05)" : "rgba(12,23,48,.55)",
      borderRadius: 0, padding: "clamp(16px, 4vw, 26px) clamp(14px, 3.5vw, 30px)", opacity: tamam ? 0.72 : 1,
    }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 10 }}>
        <div style={{ flex: 1 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 3 }}>
            <span style={{ fontSize: 15, fontWeight: 600, color: THEME.textLight }}>{g.baslik}</span>
            {g.kademe && g.kademe !== "kucuk" && <span style={{ fontSize: 15, color: kademeRenk, border: `1px solid ${kademeRenk}`, borderRadius: 0, padding: "1px 5px" }}>{g.kademe.toUpperCase()}</span>}
          </div>
          {g.aciklama && <div style={{ fontSize: 14.5, color: THEME.textMuted, marginBottom: 6 }}>{g.aciklama}</div>}
          <div style={{ display: "flex", gap: 10, fontSize: 14, color: THEME.textMuted }}>
            {g.xp_odul > 0 && <span style={{ color: THEME.cyan }}>+{g.xp_odul} XP</span>}
            {g.kredi_odul > 0 && <span style={{ color: THEME.gold }}>+{Number(g.kredi_odul)}₺ kredi</span>}
            {g.odul_aciklama && <span style={{ color: THEME.success }}>🎁 {g.odul_aciklama}</span>}
          </div>
        </div>
        <div style={{ textAlign: "right", flexShrink: 0 }}>
          {tamam ? <span style={{ fontSize: 15, color: THEME.success, fontWeight: 700 }}>✓ Tamam</span>
            : bekliyor ? <span style={{ fontSize: 14, color: THEME.gold }}>⏳ Onayda</span>
            : g.tip === "hizmet" ? <span style={{ fontSize: 15, color: THEME.cyan, textAlign: "right", lineHeight: 1.3 }}>MST ile<br/>gerçekleşir</span>
            : g.tip === "kanit" ? <button onClick={() => setKanitAcik((v) => !v)} style={{ fontSize: 14, background: THEME.gold, color: "#0C1730", border: "none", borderRadius: 0, padding: "5px 10px", cursor: "pointer", fontWeight: 600 }}>Kanıt Yükle</button>
            : <span style={{ fontSize: 14, color: THEME.textMuted, fontFamily: "monospace" }}>{g.ilerleme}/{g.hedef_deger}</span>}
        </div>
      </div>
      {/* Otomatik görevlerde ilerleme çubuğu */}
      {!tamam && !bekliyor && g.tip !== "kanit" && g.tip !== "hizmet" && g.hedef_deger > 1 && (
        <div style={{ height: 5, background: THEME.divider, borderRadius: 0, overflow: "hidden", marginTop: 8 }}>
          <div style={{ height: "100%", width: `${pct}%`, background: THEME.cyan, borderRadius: 0 }} />
        </div>
      )}
      {/* Kanıt yükleme formu */}
      {kanitAcik && (
        <div style={{ marginTop: 10, paddingTop: 10, borderTop: `1px solid ${THEME.divider}` }}>
          <div style={{ fontSize: 14, color: THEME.textMuted, marginBottom: 6 }}>Kanıt linki (ekran görüntüsü / gönderi bağlantısı):</div>
          <input value={kanitUrl} onChange={(e) => setKanitUrl(e.target.value)} placeholder="https://..." style={{ width: "100%", padding: "8px 10px", fontSize: 14, borderRadius: 0, border: `1px solid ${THEME.border}`, background: THEME.yuzeyDik, color: THEME.textLight, boxSizing: "border-box" }} />
          <div style={{ display: "flex", justifyContent: "flex-end", marginTop: 8 }}>
            <button disabled={gonderiliyor || !kanitUrl.trim()} onClick={kanitGonder} style={{ fontSize: 15, background: THEME.cyan, color: "#fff", border: "none", borderRadius: 0, padding: "6px 14px", cursor: "pointer", opacity: gonderiliyor || !kanitUrl.trim() ? 0.5 : 1 }}>{gonderiliyor ? "Gönderiliyor…" : "Gönder"}</button>
          </div>
          <div style={{ fontSize: 15, color: THEME.textMuted, marginTop: 6 }}>Kanıtın yayınevi tarafından onaylanınca ödülün verilir.</div>
        </div>
      )}
      {msg && <div style={{ fontSize: 14.5, color: msg.ok ? THEME.success : THEME.danger, marginTop: 8 }}>{msg.text}</div>}
    </div>
  );
}

function KariyerYolu({ oyun }) {
  const seviyeler = oyun.seviyeler || [];
  const mevcut = oyun.seviye?.no || 1;
  return (
    <div>
      <div style={{ fontSize: 15, color: THEME.textMuted, marginBottom: 14, lineHeight: 1.5 }}>
        Yazarlık kariyerinde yükseldikçe yeni ödüller ve ayrıcalıklar açılır. Her seviye kalıcıdır.
      </div>
      {seviyeler.map((s, i) => {
        const gecildi = s.no < mevcut;
        const aktif = s.no === mevcut;
        return (
          <div key={s.no} style={{ display: "flex", gap: 12, marginBottom: 4 }}>
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
              <div style={{ width: 44, height: 44, borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 22, flexShrink: 0,
                background: aktif ? "radial-gradient(circle at 40% 35%,#C9A24B,#0C1730)" : gecildi ? THEME.cyanDim : THEME.panelBgAlt,
                border: `2px solid ${aktif ? THEME.gold : gecildi ? THEME.cyan : THEME.border}`, opacity: gecildi || aktif ? 1 : 0.5 }}>{s.gorsel}</div>
              {i < seviyeler.length - 1 && <div style={{ width: 2, flex: 1, minHeight: 24, background: gecildi ? THEME.cyan : THEME.border }} />}
            </div>
            <div style={{ paddingBottom: 16, flex: 1 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <span style={{ fontSize: 14.5, fontWeight: 700, color: aktif ? THEME.gold : gecildi ? THEME.textLight : THEME.textMuted, fontFamily: "'Cormorant Garamond',serif" }}>{s.unvan}</span>
                {aktif && <span style={{ fontSize: 14, background: THEME.gold, color: "#0C1730", borderRadius: 0, padding: "1px 6px", fontWeight: 700 }}>ŞU AN</span>}
              </div>
              <div style={{ fontSize: 14.5, color: THEME.textMuted, marginTop: 2 }}>{s.gorsel} {s.rozet} · {s.xp} XP</div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

function OdulDukkani({ oyun, token, onRefresh }) {
  const dukkan = oyun.dukkan || [];
  const [aliniyor, setAliniyor] = useState(null);
  const [msg, setMsg] = useState(null);
  const kademeRenk = { kucuk: THEME.textMuted, orta: THEME.cyan, buyuk: THEME.gold, efsane: "#B45309" };

  const satinAl = async (odulId) => {
    setAliniyor(odulId); setMsg(null);
    try {
      const res = await fetch(`${BACKEND_URL}/api/author/oyun/dukkan-al`, {
        method: "POST", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
        body: JSON.stringify({ odulId }),
      });
      const data = await res.json();
      setMsg({ ok: !!data.ok, text: data.mesaj || data.error });
      if (data.ok) onRefresh && onRefresh();
    } catch { setMsg({ ok: false, text: "Bağlantı hatası" }); }
    finally { setAliniyor(null); }
  };

  if (!dukkan.length) return <div style={{ color: THEME.textMuted, fontSize: 14.5, padding: 16, textAlign: "center" }}>Dükkanda ürün yok. Seviye atladıkça yeni ödüller açılır.</div>;

  return (
    <div>
      <div style={{ fontSize: 15, color: THEME.textMuted, marginBottom: 12 }}>Kazandığın kredilerle ödül al. Krediler MST hizmetlerinde harcanır.</div>
      {msg && <div style={{ fontSize: 15, color: msg.ok ? THEME.success : THEME.danger, marginBottom: 10, padding: "8px 12px", background: msg.ok ? "rgba(45,106,79,.08)" : "rgba(180,60,60,.08)", borderRadius: 0 }}>{msg.text}</div>}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
        {dukkan.map((o) => (
          <div key={o.id} style={{ background: THEME.yuzey, border: `1px solid ${THEME.border}`, borderRadius: 0, padding: 12, display: "flex", flexDirection: "column" }}>
            <div style={{ fontSize: 28, marginBottom: 6 }}>{o.gorsel}</div>
            <div style={{ fontSize: 14.5, fontWeight: 600, color: THEME.textLight, marginBottom: 3 }}>{o.baslik}</div>
            <div style={{ fontSize: 14, color: THEME.textMuted, marginBottom: 10, flex: 1, lineHeight: 1.4 }}>{o.aciklama}</div>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span style={{ fontSize: 14.5, fontWeight: 700, color: THEME.gold, fontFamily: "monospace" }}>{Number(o.kredi_fiyat)}₺</span>
              <button disabled={aliniyor === o.id} onClick={() => satinAl(o.id)} style={{ fontSize: 14, background: THEME.cyan, color: "#fff", border: "none", borderRadius: 0, padding: "5px 12px", cursor: "pointer", opacity: aliniyor === o.id ? 0.5 : 1 }}>{aliniyor === o.id ? "…" : "Al"}</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function BasarimVitrini({ oyun }) {
  const basarimlar = oyun.basarimlar || [];
  if (!basarimlar.length) return <div style={{ color: THEME.textMuted, fontSize: 14.5, padding: 16, textAlign: "center" }}>Henüz başarım kazanmadın. Görevleri tamamla, rozetleri topla!</div>;
  return (
    <div>
      <div style={{ fontSize: 15, color: THEME.textMuted, marginBottom: 14 }}>Kazandığın rozetler ve kilometre taşları.</div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 10 }}>
        {basarimlar.map((b, i) => (
          <div key={i} style={{ background: THEME.yuzey, border: `1px solid ${THEME.gold}`, borderRadius: 0, padding: "14px 8px", textAlign: "center" }}>
            <div style={{ fontSize: 32, marginBottom: 6 }}>{b.gorsel}</div>
            <div style={{ fontSize: 14, fontWeight: 600, color: THEME.textLight, lineHeight: 1.3 }}>{b.baslik}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

// ==================== TOPLULUK (Hamle 2: Sosyal Boyut) ====================
function ToplulukBolumu({ token }) {
  const [lig, setLig] = useState(null);
  const [hedef, setHedef] = useState(null);
  const [gizlilik, setGizlilik] = useState(null);
  const [takmaAd, setTakmaAd] = useState("");
  const [kayitMsg, setKayitMsg] = useState(null);

  const cek = React.useCallback(async (yol) => {
    try { const r = await fetch(`${BACKEND_URL}/api/author/sosyal/${yol}`, { headers: { Authorization: `Bearer ${token}` } }); return await r.json(); }
    catch { return null; }
  }, [token]);

  React.useEffect(() => {
    cek("lig").then((d) => d && setLig(d));
    cek("topluluk-hedefi").then((d) => d && setHedef(d.hedef));
    cek("gizlilik").then((d) => { if (d) { setGizlilik(d.ligGorunur); setTakmaAd(d.takmaAd || ""); } });
  }, [cek]);

  const gizlilikKaydet = async (yeniGorunur) => {
    setGizlilik(yeniGorunur);
    try {
      await fetch(`${BACKEND_URL}/api/author/sosyal/gizlilik`, {
        method: "POST", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
        body: JSON.stringify({ ligGorunur: yeniGorunur, takmaAd }),
      });
      setKayitMsg("Kaydedildi"); setTimeout(() => setKayitMsg(null), 2000);
      cek("lig").then((d) => d && setLig(d));
    } catch { /* sessiz */ }
  };

  return (
    <div>
      {/* Topluluk hedefi */}
      {hedef && (
        <div style={{ background: "linear-gradient(135deg, rgba(45,106,79,.08), rgba(201,162,75,.08))", border: `1px solid ${THEME.gold}`, borderRadius: 0, padding: 16, marginBottom: 18 }}>
          <div style={{ fontSize: 15, letterSpacing: "0.05em", color: THEME.gold, marginBottom: 6 }}>🌍 TOPLULUK HEDEFİ</div>
          <div style={{ fontSize: 15, fontWeight: 700, color: THEME.textLight, fontFamily: "'Cormorant Garamond',serif", marginBottom: 4 }}>{hedef.baslik}</div>
          {hedef.aciklama && <div style={{ fontSize: 15, color: THEME.textMuted, marginBottom: 10 }}>{hedef.aciklama}</div>}
          <div style={{ height: 10, background: THEME.divider, borderRadius: 0, overflow: "hidden", marginBottom: 6 }}>
            <div style={{ height: "100%", width: `${hedef.yuzde}%`, background: `linear-gradient(90deg,${THEME.cyan},${THEME.gold})`, borderRadius: 0, transition: "width .6s" }} />
          </div>
          <div style={{ display: "flex", justifyContent: "space-between", fontSize: 14.5, color: THEME.textMuted }}>
            <span style={{ fontFamily: "monospace", color: THEME.cyan }}>{hedef.guncel.toLocaleString("tr-TR")} / {hedef.hedefDeger.toLocaleString("tr-TR")}</span>
            <span>%{hedef.yuzde}</span>
          </div>
          {hedef.odul && <div style={{ fontSize: 14.5, color: THEME.success, marginTop: 8 }}>Ulaşınca herkese: {hedef.odul}</div>}
        </div>
      )}

      {/* Yazar Ligi */}
      {lig && lig.siralama && lig.siralama.length > 0 && (
        <div style={{ marginBottom: 18 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
            <div style={{ fontSize: 14, letterSpacing: "0.05em", color: THEME.textMuted }}>🏆 {lig.ligAdi?.toUpperCase()}</div>
            {lig.benimSiram && <div style={{ fontSize: 14, color: THEME.gold, fontWeight: 700 }}>Sıran: #{lig.benimSiram.sira}</div>}
          </div>
          <div style={{ background: THEME.yuzey, border: `1px solid ${THEME.border}`, borderRadius: 0, padding: "4px 0" }}>
            {lig.siralama.slice(0, 10).map((s, i) => (
              <div key={i} style={{ display: "flex", alignItems: "center", gap: 10, padding: "9px 14px", borderBottom: i < Math.min(9, lig.siralama.length - 1) ? `1px solid ${THEME.divider}` : "none",
                background: s.ben ? "rgba(201,162,75,.08)" : "transparent" }}>
                <span style={{ fontSize: 14.5, fontWeight: 700, color: s.sira <= 3 ? THEME.gold : THEME.textMuted, width: 24, fontFamily: "monospace" }}>{s.sira}</span>
                <span style={{ fontSize: 18 }}>{s.rozet}</span>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 14.5, fontWeight: s.ben ? 700 : 500, color: THEME.textLight }}>{s.ad} {s.ben && <span style={{ fontSize: 14.5, color: THEME.gold }}>(sen)</span>}</div>
                  <div style={{ fontSize: 15, color: THEME.textMuted }}>{s.seviye}</div>
                </div>
                <span style={{ fontSize: 14, fontWeight: 700, color: THEME.cyan, fontFamily: "monospace" }}>{s.donemXp} XP</span>
              </div>
            ))}
          </div>
          <div style={{ fontSize: 15, color: THEME.textMuted, marginTop: 8, lineHeight: 1.5 }}>
            Lig, aylık kazandığın XP'ye göre sıralanır. Satış rakamların asla görünmez — sadece XP ve seviye.
          </div>
        </div>
      )}

      {/* Gizlilik ayarı */}
      <div style={{ background: THEME.yuzey, border: `1px solid ${THEME.border}`, borderRadius: 0, padding: 14 }}>
        <div style={{ fontSize: 15, fontWeight: 600, color: THEME.textLight, marginBottom: 10 }}>Gizlilik</div>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
          <span style={{ fontSize: 14, color: THEME.textMuted, flex: 1 }}>Ligde ve toplulukta görün</span>
          <button onClick={() => gizlilikKaydet(!gizlilik)} style={{
            width: 46, height: 26, borderRadius: 0, border: "none", cursor: "pointer", position: "relative",
            background: gizlilik ? THEME.cyan : THEME.divider, transition: "background .2s",
          }}>
            <span style={{ position: "absolute", top: 3, left: gizlilik ? 23 : 3, width: 20, height: 20, borderRadius: "50%", background: "#fff", transition: "left .2s" }} />
          </button>
        </div>
        <div>
          <div style={{ fontSize: 15, color: THEME.textMuted, marginBottom: 4 }}>Takma ad (ligde gerçek isim yerine)</div>
          <div style={{ display: "flex", gap: 8 }}>
            <input value={takmaAd} onChange={(e) => setTakmaAd(e.target.value)} placeholder="örn. Gizemli Kalem" style={{ flex: 1, padding: "8px 10px", fontSize: 14, borderRadius: 0, border: `1px solid ${THEME.border}`, background: THEME.yuzeyDik, color: THEME.textLight, boxSizing: "border-box" }} />
            <button onClick={() => gizlilikKaydet(gizlilik)} style={{ fontSize: 15, background: THEME.cyan, color: "#fff", border: "none", borderRadius: 0, padding: "0 14px", cursor: "pointer" }}>Kaydet</button>
          </div>
        </div>
        {kayitMsg && <div style={{ fontSize: 14.5, color: THEME.success, marginTop: 8 }}>✓ {kayitMsg}</div>}
      </div>
    </div>
  );
}


// ==================== REKLAM GRAFİKLERİ ====================

// Yazar (Veridian açık tema) reklam grafik paleti
const RG_YAZAR = {
  text: THEME.textLight, muted: THEME.textMuted, faint: THEME.textFaint,
  grid: THEME.divider, panel: THEME.panelBgAlt,
  spend: THEME.cyan, imp: THEME.gold, click: THEME.warn, sale: THEME.success, accent: THEME.gold,
};

// ReklamGrafikleri — bağımlılıksız saf SVG reklam grafikleri.
// Hem admin (koyu) hem yazar (Veridian açık) panelinde kullanılır.
// Renkler C (palet) prop'undan gelir: { text, muted, faint, grid, panel,
//   spend, imp, click, sale, accent }.

// ---- yardımcılar ----
const fmt = (n) => Number(n || 0).toLocaleString("tr-TR");
const fmtK = (n) => {
  n = Number(n || 0);
  if (n >= 1e6) return (n / 1e6).toFixed(1).replace(".0", "") + "M";
  if (n >= 1e3) return (n / 1e3).toFixed(1).replace(".0", "") + "B";
  return String(Math.round(n));
};
const kisaTarih = (t) => { // "2026-06-14" -> "14/06"
  if (!t) return "";
  const p = String(t).split("-");
  return p.length === 3 ? `${p[2]}/${p[1]}` : t;
};

// ============ ÇizgiTrend: zaman içinde bir metrik ============
function CizgiTrend({ gunluk = [], metrik = "spend", renk, etiket, C, yukseklik = 150 }) {
  const veri = gunluk.filter((g) => g && g.tarih);
  if (veri.length < 2) return <BosGrafik C={C} not="Trend için en az 2 günlük veri gerekli." h={yukseklik} />;
  const W = 640, H = yukseklik, padL = 44, padR = 12, padT = 12, padB = 24;
  const iw = W - padL - padR, ih = H - padT - padB;
  const vals = veri.map((g) => Number(g[metrik] || 0));
  const max = Math.max(...vals, 1);
  const x = (i) => padL + (veri.length === 1 ? iw / 2 : (i / (veri.length - 1)) * iw);
  const y = (v) => padT + ih - (v / max) * ih;
  const cizgi = veri.map((g, i) => `${i === 0 ? "M" : "L"}${x(i).toFixed(1)},${y(vals[i]).toFixed(1)}`).join(" ");
  const alan = `${cizgi} L${x(veri.length - 1).toFixed(1)},${(padT + ih).toFixed(1)} L${x(0).toFixed(1)},${(padT + ih).toFixed(1)} Z`;
  const gid = `grad_${metrik}_${Math.random().toString(36).slice(2, 7)}`;
  const etiketAdim = Math.ceil(veri.length / 6);
  const yTicks = [0, 0.5, 1];
  return (
    <div>
      <div style={{ fontSize: 15, color: C.muted, marginBottom: 4, fontWeight: 600 }}>{etiket}</div>
      <svg viewBox={`0 0 ${W} ${H}`} width="100%" style={{ display: "block" }}>
        <defs>
          <linearGradient id={gid} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={renk} stopOpacity="0.28" />
            <stop offset="100%" stopColor={renk} stopOpacity="0" />
          </linearGradient>
        </defs>
        {yTicks.map((t, i) => {
          const yy = padT + ih - t * ih;
          return (
            <g key={i}>
              <line x1={padL} y1={yy} x2={W - padR} y2={yy} stroke={C.grid} strokeWidth="1" />
              <text x={padL - 6} y={yy + 3} textAnchor="end" fontSize="9" fill={C.faint} fontFamily="monospace">{fmtK(max * t)}</text>
            </g>
          );
        })}
        <path d={alan} fill={`url(#${gid})`} />
        <path d={cizgi} fill="none" stroke={renk} strokeWidth="2" strokeLinejoin="round" strokeLinecap="round" />
        {veri.map((g, i) => (
          <circle key={i} cx={x(i)} cy={y(vals[i])} r="2.4" fill={renk} />
        ))}
        {veri.map((g, i) => (i % etiketAdim === 0 || i === veri.length - 1) ? (
          <text key={"t" + i} x={x(i)} y={H - 8} textAnchor="middle" fontSize="9" fill={C.faint} fontFamily="monospace">{kisaTarih(g.tarih)}</text>
        ) : null)}
      </svg>
    </div>
  );
}

// ============ Huni: Gösterim -> Tıklama -> Satış ============
function Huni({ impressions = 0, clicks = 0, conversions = 0, C }) {
  const asamalar = [
    { ad: "Gösterim", v: Number(impressions || 0), renk: C.imp },
    { ad: "Tıklama", v: Number(clicks || 0), renk: C.click },
    { ad: "Satış", v: Number(conversions || 0), renk: C.sale },
  ];
  const max = Math.max(...asamalar.map((a) => a.v), 1);
  const W = 640, barH = 34, gap = 16, padT = 6;
  const H = padT + asamalar.length * (barH + gap);
  const minW = 40;
  return (
    <svg viewBox={`0 0 ${W} ${H}`} width="100%" style={{ display: "block" }}>
      {asamalar.map((a, i) => {
        const w = minW + (a.v / max) * (W - minW - 4);
        const yy = padT + i * (barH + gap);
        const x0 = (W - w) / 2;
        const oncekiV = i > 0 ? asamalar[i - 1].v : null;
        const oran = oncekiV && oncekiV > 0 ? ((a.v / oncekiV) * 100).toFixed(1) : null;
        return (
          <g key={i}>
            <rect x={x0} y={yy} width={w} height={barH} rx="6" fill={a.renk} fillOpacity="0.9" />
            <text x={W / 2} y={yy + barH / 2 - 2} textAnchor="middle" fontSize="12" fontWeight="700" fill="#fff">{a.ad}</text>
            <text x={W / 2} y={yy + barH / 2 + 11} textAnchor="middle" fontSize="10" fill="#fff" fillOpacity="0.9" fontFamily="monospace">{fmt(a.v)}</text>
            {oran != null && (
              <text x={W - 4} y={yy - 4} textAnchor="end" fontSize="9.5" fill={C.muted} fontFamily="monospace">↓ %{oran}</text>
            )}
          </g>
        );
      })}
    </svg>
  );
}

// ============ Bar: kampanyaları karşılaştır ============
function KarsilastirmaBar({ kampanyalar = [], metrik = "spend", etiket, renk, C }) {
  const veri = kampanyalar.map((k) => ({ ad: k.name || k.kampanya || "—", v: Number(k[metrik] || 0) }))
    .filter((d) => d.v > 0).sort((a, b) => b.v - a.v).slice(0, 8);
  if (!veri.length) return <BosGrafik C={C} not="Karşılaştırma için veri yok." h={120} />;
  const max = Math.max(...veri.map((d) => d.v), 1);
  const satirH = 30, padT = 6;
  const W = 640, H = padT + veri.length * satirH;
  const etiketW = 150, barX = etiketW + 8, barMaxW = W - barX - 60;
  return (
    <div>
      <div style={{ fontSize: 15, color: C.muted, marginBottom: 4, fontWeight: 600 }}>{etiket}</div>
      <svg viewBox={`0 0 ${W} ${H}`} width="100%" style={{ display: "block" }}>
        {veri.map((d, i) => {
          const yy = padT + i * satirH;
          const w = (d.v / max) * barMaxW;
          const kisaAd = d.ad.length > 22 ? d.ad.slice(0, 21) + "…" : d.ad;
          return (
            <g key={i}>
              <text x={etiketW} y={yy + satirH / 2 + 3} textAnchor="end" fontSize="10.5" fill={C.text}>{kisaAd}</text>
              <rect x={barX} y={yy + 5} width={Math.max(w, 2)} height={satirH - 12} rx="4" fill={renk} fillOpacity="0.85" />
              <text x={barX + Math.max(w, 2) + 6} y={yy + satirH / 2 + 3} fontSize="10" fill={C.muted} fontFamily="monospace">{fmtK(d.v)}</text>
            </g>
          );
        })}
      </svg>
    </div>
  );
}

// ============ Özet kartlar: ROAS, tık maliyeti vb. ============
function OzetKartlar({ spend = 0, impressions = 0, clicks = 0, conversions = 0, C }) {
  const s = Number(spend || 0), imp = Number(impressions || 0), cl = Number(clicks || 0), cv = Number(conversions || 0);
  const roas = s > 0 ? (cv / s) : 0;           // satış / harcama (adet bazlı)
  const cpc = cl > 0 ? (s / cl) : 0;            // tıklama başına maliyet
  const cpa = cv > 0 ? (s / cv) : 0;            // satış başına maliyet
  const ctr = imp > 0 ? (cl / imp) * 100 : 0;   // tıklama oranı
  const kartlar = [
    { etiket: "ROAS (satış/harcama)", deger: roas.toFixed(3), alt: "1₺ başına satış", renk: C.sale },
    { etiket: "Tık. Başına Maliyet", deger: cpc.toFixed(2) + "₺", alt: "CPC", renk: C.click },
    { etiket: "Satış Başına Maliyet", deger: cv > 0 ? cpa.toFixed(2) + "₺" : "—", alt: "CPA", renk: C.spend },
    { etiket: "Tıklama Oranı", deger: "%" + ctr.toFixed(2), alt: "CTR", renk: C.imp },
  ];
  return (
    <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(130px,1fr))", gap: 10 }}>
      {kartlar.map((k, i) => (
        <div key={i} style={{ background: C.panel, border: `1px solid ${C.grid}`, borderRadius: 0, padding: "12px 14px" }}>
          <div style={{ fontSize: 15, color: C.muted, marginBottom: 6, textTransform: "uppercase", letterSpacing: 0.4 }}>{k.etiket}</div>
          <div style={{ fontSize: 20, fontWeight: 800, color: k.renk, fontFamily: "monospace", lineHeight: 1 }}>{k.deger}</div>
          <div style={{ fontSize: 14.5, color: C.faint, marginTop: 4 }}>{k.alt}</div>
        </div>
      ))}
    </div>
  );
}

function BosGrafik({ C, not, h = 120 }) {
  return (
    <div style={{ height: h, display: "flex", alignItems: "center", justifyContent: "center", color: C.faint, fontSize: 15, background: C.panel, border: `1px dashed ${C.grid}`, borderRadius: 0 }}>{not}</div>
  );
}

// ============ Tüm dashboard: kampanya toplamı + günlük seri ============
// Birden çok kampanyanın gunluk serilerini birleştirir (tarih bazında toplar).
function birlestirGunluk(kampanyalar = []) {
  const harita = {};
  kampanyalar.forEach((k) => (k.gunluk || []).forEach((g) => {
    if (!g || !g.tarih) return;
    if (!harita[g.tarih]) harita[g.tarih] = { tarih: g.tarih, spend: 0, impressions: 0, clicks: 0, conversions: 0 };
    harita[g.tarih].spend += Number(g.spend || 0);
    harita[g.tarih].impressions += Number(g.impressions || 0);
    harita[g.tarih].clicks += Number(g.clicks || 0);
    harita[g.tarih].conversions += Number(g.conversions || 0);
  }));
  return Object.values(harita).sort((a, b) => a.tarih.localeCompare(b.tarih));
}

function ReklamDashboard({ kampanyalar = [], C, baslik = "Reklam Performansı" }) {
  const toplam = kampanyalar.reduce((a, k) => ({
    spend: a.spend + Number(k.spend || 0),
    impressions: a.impressions + Number(k.impressions || 0),
    clicks: a.clicks + Number(k.clicks || 0),
    conversions: a.conversions + Number(k.conversions || 0),
  }), { spend: 0, impressions: 0, clicks: 0, conversions: 0 });
  const gunluk = birlestirGunluk(kampanyalar);
  const cokKampanya = kampanyalar.filter((k) => Number(k.spend || 0) > 0).length > 1;

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 22 }}>
      <OzetKartlar {...toplam} C={C} />
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 22 }}>
        <div style={{ background: C.panel, border: `1px solid ${C.grid}`, borderRadius: 0, padding: 16 }}>
          <CizgiTrend gunluk={gunluk} metrik="spend" renk={C.spend} etiket="Harcama Trendi (son 30 gün)" C={C} />
        </div>
        <div style={{ background: C.panel, border: `1px solid ${C.grid}`, borderRadius: 0, padding: 16 }}>
          <CizgiTrend gunluk={gunluk} metrik="conversions" renk={C.sale} etiket="Satış Trendi (son 30 gün)" C={C} />
        </div>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: cokKampanya ? "1fr 1fr" : "1fr", gap: 22 }}>
        <div style={{ background: C.panel, border: `1px solid ${C.grid}`, borderRadius: 0, padding: 16 }}>
          <div style={{ fontSize: 15, color: C.muted, marginBottom: 8, fontWeight: 600 }}>Dönüşüm Hunisi</div>
          <Huni {...toplam} C={C} />
        </div>
        {cokKampanya && (
          <div style={{ background: C.panel, border: `1px solid ${C.grid}`, borderRadius: 0, padding: 16 }}>
            <KarsilastirmaBar kampanyalar={kampanyalar} metrik="spend" etiket="Kampanya Karşılaştırma (harcama)" renk={C.spend} C={C} />
          </div>
        )}
      </div>
    </div>
  );
}


// ---- Shared design tokens ----
// ═══════════════════════════════════════════════════════════════════
// ANA BUTON — 09 numaralı tasarım (Mustafa'nın seçimi, 29 Tem 2026)
// Dolgu yok: versal metin + ok + altın çizgi. Tüm uygulamada tek dil.
// tur="asil"  → altın metin, kalın çizgi (ekranın ana eylemi)
// tur="orta"  → fildişi metin, ince çizgi
// tur="sessiz"→ soluk metin, oksuz (vazgeç, kapat)
// ═══════════════════════════════════════════════════════════════════
// ═══════════════════════════════════════════════════════════════════
// GİRİŞ ANİMASYONU — F tasarımı (Mustafa'nın seçimi, 29 Tem 2026)
// Harf harf yanan MST + altın ilerleme çubuğu.
// Giriş yanıtı ~550 ms sürüyor; animasyon yarım kalmasın diye en az
// 1,2 saniye ekranda tutuluyor.
// ═══════════════════════════════════════════════════════════════════
function GirisAnimasyonu({ gorunur, metin = "GİRİŞ YAPILIYOR" }) {
  if (!gorunur) return null;
  return (
    <div style={{
      position: "fixed", inset: 0, zIndex: 200,
      background: `radial-gradient(420px 240px at 50% 45%, rgba(201,162,75,.12), transparent 70%), #070D1B`,
      display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 22,
    }}>
      <style>{`
        @keyframes gaHarf  { 0%,100% { opacity:.22 } 50% { opacity:1 } }
        @keyframes gaCubuk { 0% { width:0 } 100% { width:100% } }
        .ga-harf { animation: gaHarf 1.5s ease-in-out infinite }
      `}</style>

      <div style={{ display: "flex", gap: 12, fontFamily: "'Cormorant Garamond', serif", fontSize: 40, letterSpacing: "0.12em", color: "#F0D68A" }}>
        <span className="ga-harf">M</span>
        <span className="ga-harf" style={{ animationDelay: ".25s" }}>S</span>
        <span className="ga-harf" style={{ animationDelay: ".5s" }}>T</span>
      </div>

      <div style={{ width: 150, height: 1, background: "rgba(201,162,75,.20)", overflow: "hidden" }}>
        <div style={{ height: "100%", background: "linear-gradient(90deg,#8C6A22,#F0D68A)", animation: "gaCubuk 1.8s ease-in-out infinite" }} />
      </div>

      <div style={{ fontSize: 10, letterSpacing: "0.3em", color: "rgba(201,162,75,.7)", fontFamily: "'Jost', sans-serif" }}>
        {metin}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// DEMO DENEYİMİ — yazar adayı yolculuk provası
//
// Bu bir tanıtım turu değil, bir PROVA. Aday kendini altı ay sonraki
// hâlinde görüyor: kendi adıyla, kendi kitabının adıyla.
// Sekiz adım, sonunda form.
//
// Rakamlar örnek ve HER ADIMDA işaretli. Gerçek sanılan demo, ilk gerçek
// raporda güveni yıkar.
// ═══════════════════════════════════════════════════════════════════
// ═══════════════════════════════════════════════════════════════════
// DEMO SİMÜLASYONU — yazar adayı için
//
// Bu bir slayt gösterisi DEĞİL. Aday burada bir şeyler YAPAR:
// kitabının adını yazar, satış kaydırıcısını oynatır, paketleri
// karşılaştırır, uygulamanın içinde gezer.
//
// Tasarım ilkesi: anlatma, YAŞAT. Aday kendini altı ay sonraki hâlinde
// görmeli — kendi kitabının kapağıyla, kendi rakamlarıyla.
//
// Rakamlar örnek ve her ekranda işaretli (Kural: gerçek sanılan demo,
// ilk gerçek raporda güveni yıkar).
// ═══════════════════════════════════════════════════════════════════

// Sayı sayacı — hedefe doğru animasyonla çıkar
function Sayac({ hedef, sure = 1200, sonEk = "", basEk = "", stil }) {
  const [deger, setDeger] = useState(0);
  useEffect(() => {
    let iptal = false;
    const bas = performance.now();
    const adim = (t) => {
      if (iptal) return;
      const o = Math.min(1, (t - bas) / sure);
      const yumusak = 1 - Math.pow(1 - o, 3);
      setDeger(Math.round(hedef * yumusak));
      if (o < 1) requestAnimationFrame(adim);
    };
    requestAnimationFrame(adim);
    return () => { iptal = true; };
  }, [hedef, sure]);
  return <span style={stil}>{basEk}{deger.toLocaleString("tr-TR")}{sonEk}</span>;
}

// Kitap kapağı maketi — adayın kendi kitap adıyla
function KapakMaketi({ baslik, yazar, boyut = 1 }) {
  const g = 150 * boyut, y = 225 * boyut;
  return (
    <div style={{
      width: g, height: y, flexShrink: 0, position: "relative",
      background: "linear-gradient(145deg,#1A2F58,#0C1730)",
      border: "1px solid rgba(201,162,75,.4)",
      boxShadow: "6px 8px 26px rgba(0,0,0,.5)",
      display: "flex", flexDirection: "column", justifyContent: "space-between",
      padding: 14 * boyut, boxSizing: "border-box",
    }}>
      <div style={{ position: "absolute", left: 6 * boyut, top: 0, bottom: 0, width: 2, background: "rgba(201,162,75,.35)" }} />
      <div style={{ fontSize: 8 * boyut, letterSpacing: "0.24em", color: "rgba(201,162,75,.8)" }}>MST</div>
      <div style={{
        fontFamily: "'Cormorant Garamond',serif", fontSize: 19 * boyut, lineHeight: 1.2,
        color: "#F0D68A", fontWeight: 600, textAlign: "center",
      }}>{baslik}</div>
      <div style={{ fontSize: 9 * boyut, color: "rgba(245,240,228,.6)", textAlign: "center", letterSpacing: "0.1em" }}>{yazar}</div>
    </div>
  );
}

function DemoDeneyimi({ kod }) {
  const [veri, setVeri] = useState(null);
  const [hata, setHata] = useState("");
  const [adim, setAdim] = useState(0);
  const [form, setForm] = useState({ paket: "" });
  const [gonderiliyor, setGonderiliyor] = useState(false);
  const [tamamlandi, setTamamlandi] = useState(false);

  // Etkileşim durumları
  const [kitapAdi, setKitapAdi] = useState("");
  const [satisTahmin, setSatisTahmin] = useState(500);
  const [seciliPaket, setSeciliPaket] = useState("profesyonel");
  const [uygulamaSekme, setUygulamaSekme] = useState("pano");
  const [surecAdim, setSurecAdim] = useState(0);

  useEffect(() => {
    fetch(`${BACKEND_URL}/api/demo/${kod}`)
      .then((r) => r.json())
      .then((d) => {
        if (!d.ok) { setHata(d.error || "Demo açılamadı."); return; }
        setVeri(d);
        setKitapAdi(d.demo.kitapAdi && d.demo.kitapAdi !== "Kitabınız" ? d.demo.kitapAdi : "");
        setSatisTahmin(d.senaryo.tahminiSatis || 500);
        setSeciliPaket(d.demo.hedefPaket || "profesyonel");
        setForm((f) => ({
          ...f, adSoyad: d.demo.adayAd || "",
          kitapAdi: d.demo.kitapAdi === "Kitabınız" ? "" : d.demo.kitapAdi || "",
          kitapTuru: d.demo.kitapTuru || "", paket: d.demo.hedefPaket || "profesyonel",
        }));
      })
      .catch(() => setHata("Bağlantı kurulamadı."));
  }, [kod]);

  useEffect(() => {
    if (!veri || adim === 0) return;
    fetch(`${BACKEND_URL}/api/demo/${kod}/adim`, {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ adim }),
    }).catch(() => {});
  }, [adim, veri, kod]);

  // Yayın süreci animasyonu — 2. adımda otomatik ilerler
  useEffect(() => {
    if (adim !== 2) { setSurecAdim(0); return; }
    if (surecAdim >= 7) return;
    const z = setTimeout(() => setSurecAdim(surecAdim + 1), 620);
    return () => clearTimeout(z);
  }, [adim, surecAdim]);

  if (hata) return (
    <div style={{ minHeight: "100vh", background: "#070D1B", display: "flex", alignItems: "center", justifyContent: "center", padding: 24 }}>
      <div style={{ textAlign: "center", color: "rgba(245,240,228,.7)", fontFamily: "'Jost',sans-serif", fontSize: 15, lineHeight: 1.7 }}>{hata}</div>
    </div>
  );
  if (!veri) return (
    <div style={{ minHeight: "100vh", background: "#070D1B", display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div style={{ fontFamily: "'Cormorant Garamond',serif", fontSize: 32, color: "#F0D68A", letterSpacing: ".12em" }}>MST</div>
    </div>
  );

  const d = veri.demo;
  const ilkAd = String(d.adayAd).split(" ")[0];
  const eserAdi = kitapAdi.trim() || d.kitapAdi || "Kitabınız";
  const t = (x) => Number(x || 0).toLocaleString("tr-TR");
  const fiyat = veri.senaryo.kitapFiyati || 250;

  // Canlı telif hesabı — kaydırıcı oynadıkça değişir
  const telifHesapla = (paketKod, satis) => {
    const p = veri.paketler.find((x) => x.kod === paketKod) || veri.paketler[1];
    return Math.round((satis / 2) * fiyat * (p.mstYuzde / 100) + (satis / 2) * fiyat * (p.digerYuzde / 100));
  };
  const secili = veri.paketler.find((p) => p.kod === seciliPaket) || veri.paketler[1];
  const seciliTelif = telifHesapla(seciliPaket, satisTahmin);
  const baslangicTelif = telifHesapla("standart", satisTahmin);
  const fark = seciliTelif - baslangicTelif;

  const platformDagilim = [
    { ad: "MST Yayıncılık", oran: 0.34 }, { ad: "Trendyol", oran: 0.24 },
    { ad: "Hepsiburada", oran: 0.16 }, { ad: "N11", oran: 0.11 },
    { ad: "İdefix", oran: 0.09 }, { ad: "Pazarama", oran: 0.06 },
  ].map((p) => ({ ...p, satis: Math.round(satisTahmin * p.oran) }));

  const etiket = { fontSize: 10, letterSpacing: "0.3em", color: "rgba(201,162,75,.85)", fontWeight: 600 };
  const baslik = { fontFamily: "'Cormorant Garamond', serif", fontSize: 29, fontWeight: 600, lineHeight: 1.2, color: "#fff", marginTop: 12 };
  const govde = { fontSize: 15, color: "rgba(245,240,228,.82)", lineHeight: 1.85, fontWeight: 300, marginTop: 14 };
  const inputStyle = {
    padding: "13px 15px", border: "1px solid rgba(201,162,75,.32)", borderRadius: 0, fontSize: 15,
    boxSizing: "border-box", background: "rgba(255,255,255,.03)", color: "#F5F0E4",
    fontFamily: "'Jost', sans-serif", width: "100%",
  };
  const altinYazi = { background: THEME.altinMetin, WebkitBackgroundClip: "text", backgroundClip: "text", WebkitTextFillColor: "transparent" };
  const ornekRozet = (
    <span style={{ fontSize: 9, letterSpacing: "0.16em", color: "rgba(245,240,228,.5)", border: "1px solid rgba(245,240,228,.24)", padding: "3px 7px", whiteSpace: "nowrap" }}>ÖRNEK</span>
  );

  const gonder = async () => {
    if (gonderiliyor) return;
    setGonderiliyor(true);
    try {
      const r = await fetch(`${BACKEND_URL}/api/demo/${kod}/form`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...form, kitapAdi: eserAdi, paket: seciliPaket }),
      });
      const j = await r.json();
      if (j.ok) setTamamlandi(true); else setHata(j.error || "Gönderilemedi.");
    } catch { setHata("Bağlantı kurulamadı."); }
    finally { setGonderiliyor(false); }
  };

  const surecAdimlari = [
    ["Eser değerlendirme", "Editörümüz metninizi okur"],
    ["Redaksiyon", "Dil ve anlatım düzeltmeleri"],
    ["Mizanpaj", "Sayfa tasarımı ve dizgi"],
    ["Kapak tasarımı", "Türüne uygun özgün kapak"],
    ["ISBN & bandrol", "Yasal kayıt işlemleri"],
    ["Matbaa", "Baskı ve ciltleme"],
    ["Dağıtım", "Altı pazaryerinde listeleme"],
  ];

  const adimlar = [
    // ══ 0 · KARŞILAMA + KİŞİSELLEŞTİRME ══
    {
      icerik: (
        <div style={{ textAlign: "center" }}>
          <div style={etiket}>MST YAYINCILIK</div>
          <div style={{ ...baslik, fontSize: 33 }}>Merhaba {ilkAd}</div>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 14, margin: "20px auto", maxWidth: 190 }}>
            <span style={{ height: 1, flex: 1, background: "linear-gradient(90deg,transparent,rgba(201,162,75,.8))" }} />
            <span style={{ width: 6, height: 6, background: "#C9A24B", transform: "rotate(45deg)" }} />
            <span style={{ height: 1, flex: 1, background: "linear-gradient(90deg,rgba(201,162,75,.8),transparent)" }} />
          </div>
          <div style={{ ...govde, maxWidth: 430, margin: "0 auto 24px" }}>
            Size bir sunum yapmayacağız. Bunun yerine kitabınızı yayınlamış hâlinizi
            <b style={{ fontWeight: 500, color: "#F0D68A" }}> birlikte kullanacağız.</b>
          </div>

          <div style={{ maxWidth: 340, margin: "0 auto", textAlign: "left" }}>
            <div style={{ fontSize: 10, letterSpacing: "0.28em", color: "rgba(201,162,75,.85)", marginBottom: 8 }}>ESERİNİZİN ADI</div>
            <input style={inputStyle} value={kitapAdi} onChange={(e) => setKitapAdi(e.target.value)}
              placeholder="Kitabınızın adını yazın" />
            <div style={{ fontSize: 12.5, color: "rgba(245,240,228,.5)", marginTop: 8, lineHeight: 1.6 }}>
              Yazdığınız isim bundan sonraki her ekranda görünecek — kapakta, panonuzda, telif hesabınızda.
            </div>
          </div>

          {kitapAdi.trim() && (
            <div style={{ marginTop: 26, display: "flex", justifyContent: "center" }}>
              <KapakMaketi baslik={eserAdi} yazar={d.adayAd} boyut={0.85} />
            </div>
          )}
        </div>
      ),
    },

    // ══ 1 · PANO — animasyonlu, canlı ══
    {
      icerik: (
        <div>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 12 }}>
            <div><div style={etiket}>PANONUZ</div><div style={baslik}>Altı ay sonra<br />ekranınız</div></div>
            {ornekRozet}
          </div>

          <div style={{ marginTop: 20, background: "linear-gradient(160deg,rgba(201,162,75,.07),rgba(10,20,40,.5))", border: "1px solid rgba(201,162,75,.3)", padding: "22px 20px" }}>
            <div style={{ display: "flex", gap: 18, alignItems: "flex-start", flexWrap: "wrap" }}>
              <KapakMaketi baslik={eserAdi} yazar={d.adayAd} boyut={0.62} />
              <div style={{ flex: 1, minWidth: 150 }}>
                <Sayac hedef={satisTahmin} sonEk="" stil={{ fontFamily: "'Cormorant Garamond',serif", fontSize: 46, fontWeight: 600, lineHeight: 1, ...altinYazi }} />
                <div style={{ fontSize: 10, letterSpacing: "0.22em", color: "rgba(201,162,75,.8)", marginTop: 6 }}>TOPLAM SATIŞ</div>
                <div style={{ marginTop: 14 }}>
                  <Sayac hedef={seciliTelif} sonEk=" ₺" stil={{ fontFamily: "'Cormorant Garamond',serif", fontSize: 27, fontWeight: 600, ...altinYazi }} />
                  <div style={{ fontSize: 10, letterSpacing: "0.22em", color: "rgba(201,162,75,.8)", marginTop: 4 }}>TELİFİNİZ</div>
                </div>
              </div>
            </div>

            <div style={{ marginTop: 20, display: "grid", gap: 8 }}>
              {platformDagilim.map((p, i) => (
                <div key={p.ad}>
                  <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13.5, marginBottom: 4 }}>
                    <span style={{ color: "rgba(245,240,228,.82)", fontWeight: 300 }}>{p.ad}</span>
                    <span style={{ fontFamily: "'Cormorant Garamond',serif", fontSize: 17, color: "#F0D68A" }}>{t(p.satis)}</span>
                  </div>
                  <div style={{ height: 3, background: "rgba(245,240,228,.08)" }}>
                    <div style={{
                      height: "100%", width: `${p.oran * 100 / 0.34 * 100}%`, maxWidth: "100%",
                      background: "linear-gradient(90deg,#8C6A22,#F0D68A)",
                      transition: `width 900ms ease ${i * 110}ms`,
                    }} />
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div style={{ ...govde, fontSize: 14.5 }}>
            Her sabah açıp bakarsınız: hangi platform çalışıyor, hangisi durgun.
            Rakamlar pazaryerlerinden otomatik gelir — elle giriş yok.
          </div>
        </div>
      ),
    },

    // ══ 2 · YAYIN SÜRECİ — canlı ilerleyen ══
    {
      icerik: (
        <div>
          <div style={etiket}>YAYIN SÜRECİ</div>
          <div style={baslik}>"{eserAdi}"<br />yola çıkıyor</div>
          <div style={{ ...govde, fontSize: 14.5 }}>
            Her adımı uygulamadan izlersiniz. "Ne oldu acaba" diye telefon açmanıza gerek kalmaz.
          </div>

          <div style={{ marginTop: 20, display: "grid", gap: 1, background: "rgba(201,162,75,.14)", border: "1px solid rgba(201,162,75,.24)" }}>
            {surecAdimlari.map(([b, a], i) => {
              const tamam = i < surecAdim;
              const suanki = i === surecAdim;
              return (
                <div key={b} style={{
                  background: suanki ? "rgba(201,162,75,.10)" : "rgba(12,23,48,.55)",
                  padding: "13px 15px", display: "flex", alignItems: "center", gap: 13,
                  transition: "background 400ms ease",
                }}>
                  <span style={{
                    width: 24, height: 24, flexShrink: 0,
                    border: `1px solid ${tamam || suanki ? "#C9A24B" : "rgba(201,162,75,.25)"}`,
                    background: tamam ? "#C9A24B" : "transparent",
                    display: "flex", alignItems: "center", justifyContent: "center",
                    fontSize: 11, color: tamam ? "#0A1428" : "rgba(201,162,75,.7)",
                    fontFamily: "'Cormorant Garamond',serif", transition: "all 400ms ease",
                  }}>{tamam ? "✓" : i + 1}</span>
                  <div style={{ flex: 1, opacity: tamam || suanki ? 1 : 0.42, transition: "opacity 400ms" }}>
                    <div style={{ fontSize: 14, color: "#F5F0E4", fontWeight: 500 }}>{b}</div>
                    <div style={{ fontSize: 12.5, color: "rgba(245,240,228,.6)", fontWeight: 300, marginTop: 1 }}>{a}</div>
                  </div>
                  {suanki && <span style={{ fontSize: 10, letterSpacing: "0.14em", color: "#F0D68A" }}>ŞİMDİ</span>}
                </div>
              );
            })}
          </div>

          {surecAdim >= 7 && (
            <div style={{ marginTop: 16, textAlign: "center", fontSize: 14.5, color: "#9FC7A8", fontWeight: 300 }}>
              Kitabınız altı pazaryerinde yayında.
            </div>
          )}
        </div>
      ),
    },

    // ══ 3 · CANLI TELİF HESAPLAYICI — asıl etkileşim ══
    {
      icerik: (
        <div>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 12 }}>
            <div><div style={etiket}>TELİF HESABI</div><div style={baslik}>Kaydırın,<br />kendiniz görün</div></div>
            {ornekRozet}
          </div>
          <div style={{ ...govde, fontSize: 14.5 }}>
            Kaç adet satarsanız ne kazanırsınız? Kaydırıcıyı oynatın — rakam anında değişir.
          </div>

          <div style={{ marginTop: 22, background: "linear-gradient(160deg,rgba(201,162,75,.08),rgba(10,20,40,.55))", border: "1px solid rgba(201,162,75,.34)", padding: "24px 22px" }}>
            <div style={{ textAlign: "center" }}>
              <div style={{ fontFamily: "'Cormorant Garamond',serif", fontSize: 50, fontWeight: 600, lineHeight: 1, ...altinYazi }}>
                {t(seciliTelif)} ₺
              </div>
              <div style={{ fontSize: 10, letterSpacing: "0.24em", color: "rgba(201,162,75,.85)", marginTop: 8 }}>
                {secili.ad.toLocaleUpperCase("tr-TR")} PAKETİ · {t(satisTahmin)} SATIŞTA
              </div>
            </div>

            <div style={{ marginTop: 26 }}>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12, color: "rgba(245,240,228,.55)", marginBottom: 8 }}>
                <span>100 adet</span><span>2.000 adet</span>
              </div>
              <input type="range" min={100} max={2000} step={50} value={satisTahmin}
                onChange={(e) => setSatisTahmin(Number(e.target.value))}
                style={{ width: "100%", accentColor: "#C9A24B", height: 4, cursor: "pointer" }} />
              <div style={{ textAlign: "center", fontSize: 13.5, color: "rgba(245,240,228,.7)", marginTop: 10, fontWeight: 300 }}>
                <b style={{ color: "#F0D68A", fontWeight: 500 }}>{t(satisTahmin)}</b> adet satış varsayımı
              </div>
            </div>

            <div style={{ marginTop: 22, paddingTop: 18, borderTop: "1px solid rgba(201,162,75,.2)", display: "grid", gap: 9 }}>
              {veri.paketler.map((p) => {
                const tl = telifHesapla(p.kod, satisTahmin);
                const s = p.kod === seciliPaket;
                return (
                  <div key={p.kod} onClick={() => { setSeciliPaket(p.kod); setForm({ ...form, paket: p.kod }); }}
                    style={{
                      display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10,
                      padding: "12px 14px", cursor: "pointer",
                      background: s ? "rgba(201,162,75,.12)" : "rgba(255,255,255,.02)",
                      border: `1px solid ${s ? "rgba(201,162,75,.5)" : "rgba(201,162,75,.16)"}`,
                      transition: "all 200ms",
                    }}>
                    <div>
                      <div style={{ fontSize: 14.5, color: s ? "#F0D68A" : "#F5F0E4", fontWeight: 500 }}>{p.ad}</div>
                      <div style={{ fontSize: 11.5, color: "rgba(245,240,228,.55)", marginTop: 2 }}>MST %{p.mstYuzde} · diğer %{p.digerYuzde}</div>
                    </div>
                    <div style={{ fontFamily: "'Cormorant Garamond',serif", fontSize: 21, color: s ? "#F0D68A" : "rgba(245,240,228,.72)", fontWeight: 600 }}>
                      {t(tl)} ₺
                    </div>
                  </div>
                );
              })}
            </div>

            {fark > 0 && (
              <div style={{ marginTop: 16, fontSize: 14, color: "rgba(245,240,228,.84)", lineHeight: 1.8, fontWeight: 300, textAlign: "center" }}>
                <b style={{ color: "#F0D68A", fontWeight: 500 }}>{secili.ad}</b>, Başlangıç'a göre
                bu satışta <b style={{ color: "#F0D68A", fontWeight: 500 }}>{t(fark)} ₺</b> fazla getiriyor.
                <div style={{ fontSize: 12.5, color: "rgba(245,240,228,.5)", marginTop: 6 }}>
                  Fark tek seferlik ücretten değil, her satıştan geliyor.
                </div>
              </div>
            )}
          </div>
        </div>
      ),
    },

    // ══ 4 · UYGULAMA SİMÜLASYONU — dokunulabilir ══
    {
      icerik: (
        <div>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 12 }}>
            <div><div style={etiket}>UYGULAMANIZ</div><div style={baslik}>Dokunun,<br />gezinin</div></div>
            {ornekRozet}
          </div>
          <div style={{ ...govde, fontSize: 14.5 }}>
            Alt menüden bölümler arasında gezin — gerçek uygulamanız aynen böyle çalışıyor.
          </div>

          <div style={{ marginTop: 20, border: "1px solid rgba(201,162,75,.34)", background: "linear-gradient(172deg,#0C1730,#070D1B)", overflow: "hidden" }}>
            <div style={{ padding: "18px 18px 20px", minHeight: 250 }}>
              {uygulamaSekme === "pano" && (
                <div>
                  <div style={{ fontSize: 10, letterSpacing: "0.26em", color: "rgba(201,162,75,.8)" }}>PANO</div>
                  <div style={{ fontFamily: "'Cormorant Garamond',serif", fontSize: 40, fontWeight: 600, marginTop: 10, ...altinYazi }}>{t(satisTahmin)}</div>
                  <div style={{ fontSize: 10, letterSpacing: "0.2em", color: "rgba(201,162,75,.75)" }}>TOPLAM SATIŞ · 6 KANAL</div>
                  <div style={{ marginTop: 16, display: "grid", gap: 7 }}>
                    {platformDagilim.slice(0, 4).map((p) => (
                      <div key={p.ad} style={{ display: "flex", justifyContent: "space-between", fontSize: 13.5 }}>
                        <span style={{ color: "rgba(245,240,228,.78)", fontWeight: 300 }}>{p.ad}</span>
                        <span style={{ color: "#F0D68A", fontFamily: "'Cormorant Garamond',serif", fontSize: 16 }}>{t(p.satis)}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
              {uygulamaSekme === "kazanc" && (
                <div>
                  <div style={{ fontSize: 10, letterSpacing: "0.26em", color: "rgba(201,162,75,.8)" }}>KAZANÇ</div>
                  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 1, background: "rgba(201,162,75,.16)", marginTop: 14 }}>
                    {[["TOPLAM TELİF", t(seciliTelif) + " ₺"], ["ÇEKİLEBİLİR", t(Math.round(seciliTelif * 0.4)) + " ₺"],
                      ["KİLİTLİ", t(Math.round(seciliTelif * 0.6)) + " ₺"], ["BU AY", t(Math.round(seciliTelif / 6)) + " ₺"]].map(([e, v]) => (
                      <div key={e} style={{ background: "rgba(12,23,48,.6)", padding: "14px 12px" }}>
                        <div style={{ fontFamily: "'Cormorant Garamond',serif", fontSize: 20, fontWeight: 600, ...altinYazi }}>{v}</div>
                        <div style={{ fontSize: 9, letterSpacing: "0.18em", color: "rgba(201,162,75,.75)", marginTop: 3 }}>{e}</div>
                      </div>
                    ))}
                  </div>
                  <div style={{ fontSize: 12.5, color: "rgba(245,240,228,.6)", marginTop: 12, lineHeight: 1.6, fontWeight: 300 }}>
                    Kilitli telif, baskı stoğunuz tükendiğinde çekilebilir hale gelir. Gizli kesinti yok.
                  </div>
                </div>
              )}
              {uygulamaSekme === "reklam" && (
                <div>
                  <div style={{ fontSize: 10, letterSpacing: "0.26em", color: "rgba(201,162,75,.8)" }}>REKLAM</div>
                  <div style={{ fontSize: 14.5, color: "#F5F0E4", marginTop: 12, fontWeight: 500 }}>{eserAdi}</div>
                  <div style={{ fontSize: 12.5, color: "rgba(245,240,228,.6)", marginTop: 3, fontWeight: 300 }}>1.500 ₺ · 14 gün · yayında</div>
                  <div style={{ marginTop: 16, display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(72px,1fr))", gap: 12 }}>
                    {[["ULAŞILAN", "11.800"], ["TIKLAMA", "340"], ["SATIŞ", "+14"]].map(([e, v]) => (
                      <div key={e}>
                        <div style={{ fontFamily: "'Cormorant Garamond',serif", fontSize: 20, fontWeight: 600, ...altinYazi }}>{v}</div>
                        <div style={{ fontSize: 9, letterSpacing: "0.16em", color: "rgba(201,162,75,.75)", marginTop: 3 }}>{e}</div>
                      </div>
                    ))}
                  </div>
                  <div style={{ fontSize: 12, color: "rgba(245,240,228,.5)", marginTop: 14, lineHeight: 1.6, fontWeight: 300 }}>
                    Bu rakamlar doğrudan Meta'nın sisteminden gelir — biz hesaplamayız.
                  </div>
                </div>
              )}
              {uygulamaSekme === "ai" && (
                <div>
                  <div style={{ fontSize: 10, letterSpacing: "0.26em", color: "rgba(201,162,75,.8)" }}>A . I .  DANIŞMANINIZ</div>
                  <div style={{ marginTop: 14, background: "rgba(255,255,255,.02)", border: "1px solid rgba(201,162,75,.22)", padding: "14px 16px", fontSize: 14, color: "rgba(245,240,228,.86)", lineHeight: 1.8, fontWeight: 300 }}>
                    {ilkAd}, "{eserAdi}" en çok MST mağazasında satıyor ama Trendyol'da
                    ivme yakalamış. Bu ay Trendyol'a küçük bir tanıtım bütçesi ayırmanı öneririm —
                    orada ivme varken desteklemek, sıfırdan başlatmaktan ucuz.
                  </div>
                  <div style={{ fontSize: 12, color: "rgba(245,240,228,.5)", marginTop: 12, lineHeight: 1.6, fontWeight: 300 }}>
                    Danışmanınız sizin verinizi okur. Genel tavsiye vermez.
                  </div>
                </div>
              )}
            </div>

            <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", borderTop: "1px solid rgba(201,162,75,.28)", background: "rgba(7,13,27,.7)" }}>
              {[["pano", "PANO", "◉"], ["kazanc", "KAZANÇ", "₺"], ["reklam", "REKLAM", "◈"], ["ai", "A . I .", "✦"]].map(([k, ad, ik]) => (
                <div key={k} onClick={() => setUygulamaSekme(k)} style={{
                  padding: "12px 4px", textAlign: "center", cursor: "pointer",
                  borderTop: `2px solid ${uygulamaSekme === k ? "#C9A24B" : "transparent"}`,
                  background: uygulamaSekme === k ? "rgba(201,162,75,.07)" : "transparent",
                  transition: "all 200ms",
                }}>
                  <div style={{ fontSize: 15, color: uygulamaSekme === k ? "#F0D68A" : "rgba(201,162,75,.5)" }}>{ik}</div>
                  <div style={{ fontSize: 8.5, letterSpacing: "0.12em", color: uygulamaSekme === k ? "#F0D68A" : "rgba(245,240,228,.45)", marginTop: 3 }}>{ad}</div>
                </div>
              ))}
            </div>
          </div>
        </div>
      ),
    },

    // ══ 5 · KARŞILAŞTIRMA — kendi başına vs MST ══
    {
      icerik: (
        <div>
          <div style={etiket}>KARAR</div>
          <div style={baslik}>Kendi başınıza mı,<br />bizimle mi?</div>
          <div style={{ ...govde, fontSize: 14.5 }}>
            Dürüst olalım: kitabınızı kendiniz de bastırabilirsiniz. Farkı görün.
          </div>

          <div style={{ marginTop: 20, display: "grid", gap: 1, background: "rgba(201,162,75,.14)", border: "1px solid rgba(201,162,75,.24)" }}>
            {[
              ["Matbaa ve baskı", "Kendiniz bulursunuz", "Biz hallederiz"],
              ["ISBN & bandrol", "Kendiniz başvurursunuz", "Biz alırız"],
              ["Editör & redaksiyon", "Ayrıca ödersiniz", "Pakete dahil"],
              ["Kapak tasarımı", "Ayrıca ödersiniz", "Pakete dahil"],
              ["15 pazaryerinde satış", "Her biri ayrı başvuru", "Otomatik"],
              ["Satış takibi", "Excel tutarsınız", "Uygulamada canlı"],
              ["Tanıtım", "Kendiniz öğrenirsiniz", "Uzman ekip"],
            ].map(([konu, tek, biz]) => (
              <div key={konu} style={{ background: "rgba(12,23,48,.55)", padding: "12px 14px", display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                <div>
                  <div style={{ fontSize: 13.5, color: "#F5F0E4", fontWeight: 500 }}>{konu}</div>
                  <div style={{ fontSize: 12, color: "rgba(245,240,228,.5)", marginTop: 3, fontWeight: 300 }}>{tek}</div>
                </div>
                <div style={{ fontSize: 13, color: "#9FC7A8", fontWeight: 300, alignSelf: "center" }}>{biz}</div>
              </div>
            ))}
          </div>

          <div style={{ marginTop: 18, background: "rgba(201,162,75,.05)", border: "1px solid rgba(201,162,75,.28)", padding: "16px 18px", fontSize: 14, color: "rgba(245,240,228,.82)", lineHeight: 1.8, fontWeight: 300 }}>
            Kendi başınıza yayınlarsanız telifin tamamı sizde kalır — ama dağıtım, tanıtım
            ve takip de sizde kalır. Biz bu işleri üstlenip telifin
            <b style={{ color: "#F0D68A", fontWeight: 500 }}> %{secili.mstYuzde}'ini</b> size bırakıyoruz.
          </div>
        </div>
      ),
    },

    // ══ 6 · BAŞVURU ══
    {
      icerik: tamamlandi ? (
        <div style={{ textAlign: "center", paddingTop: 16 }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 14, marginBottom: 18 }}>
            <span style={{ height: 1, flex: 1, maxWidth: 70, background: "linear-gradient(90deg,transparent,rgba(201,162,75,.8))" }} />
            <span style={{ width: 8, height: 8, background: "#C9A24B", transform: "rotate(45deg)" }} />
            <span style={{ height: 1, flex: 1, maxWidth: 70, background: "linear-gradient(90deg,rgba(201,162,75,.8),transparent)" }} />
          </div>
          <div style={{ ...baslik, marginTop: 0 }}>Teşekkürler {ilkAd}</div>
          <div style={{ ...govde, maxWidth: 380, margin: "14px auto 0" }}>
            Bilgileriniz bize ulaştı. Ekibimiz kısa sürede sizinle iletişime geçip
            "{eserAdi}"i değerlendirecek ve süreci birlikte planlayacak.
          </div>
          <div style={{ marginTop: 26, display: "flex", justifyContent: "center" }}>
            <KapakMaketi baslik={eserAdi} yazar={d.adayAd} boyut={0.7} />
          </div>
        </div>
      ) : (
        <div>
          <div style={etiket}>BAŞVURU</div>
          <div style={baslik}>"{eserAdi}"i<br />değerlendirelim</div>
          <div style={{ ...govde, fontSize: 14.5 }}>
            Bu bir taahhüt değil — önce eserinizi okuyup birlikte konuşuyoruz.
          </div>
          <div style={{ display: "grid", gap: 10, marginTop: 20 }}>
            <input style={inputStyle} placeholder="Ad soyad" value={form.adSoyad || ""} onChange={(e) => setForm({ ...form, adSoyad: e.target.value })} />
            <input style={inputStyle} placeholder="Telefon" value={form.telefon || ""} onChange={(e) => setForm({ ...form, telefon: e.target.value })} />
            <input style={inputStyle} placeholder="E-posta (opsiyonel)" value={form.eposta || ""} onChange={(e) => setForm({ ...form, eposta: e.target.value })} />
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              <input style={inputStyle} placeholder="Türü" value={form.kitapTuru || ""} onChange={(e) => setForm({ ...form, kitapTuru: e.target.value })} />
              <input style={inputStyle} placeholder="Sayfa sayısı" value={form.sayfaSayisi || ""} onChange={(e) => setForm({ ...form, sayfaSayisi: e.target.value.replace(/[^0-9]/g, "") })} />
            </div>
            <select style={inputStyle} value={form.yazimDurumu || ""} onChange={(e) => setForm({ ...form, yazimDurumu: e.target.value })}>
              <option value="">Eseriniz hangi aşamada?</option>
              <option value="tamamlandi">Tamamlandı</option>
              <option value="yaziliyor">Yazımı devam ediyor</option>
              <option value="planlama">Henüz planlama aşamasında</option>
            </select>
            <div style={{ background: "rgba(201,162,75,.05)", border: "1px solid rgba(201,162,75,.24)", padding: "12px 14px", fontSize: 13.5, color: "rgba(245,240,228,.78)", lineHeight: 1.7, fontWeight: 300 }}>
              Seçtiğiniz paket: <b style={{ color: "#F0D68A", fontWeight: 500 }}>{secili.ad}</b>
              {" · "}{t(satisTahmin)} satışta tahmini telif <b style={{ color: "#F0D68A", fontWeight: 500 }}>{t(seciliTelif)} ₺</b>
            </div>
            <textarea style={{ ...inputStyle, resize: "vertical", lineHeight: 1.7 }} rows={3}
              placeholder="Eklemek istediğiniz bir şey var mı?" value={form.mesaj || ""}
              onChange={(e) => setForm({ ...form, mesaj: e.target.value })} />
          </div>
          <div style={{ marginTop: 18 }}>
            <Dugme tur="asil" disabled={gonderiliyor || !form.adSoyad || !form.telefon} onClick={gonder}>
              {gonderiliyor ? "GÖNDERİLİYOR" : "BİLGİLERİMİ GÖNDER"}
            </Dugme>
          </div>
        </div>
      ),
    },
  ];

  const son = adim >= adimlar.length - 1;
  const ilerleyebilir = adim !== 0 || kitapAdi.trim().length > 1;

  return (
    <div style={{
      minHeight: "100vh",
      background: `radial-gradient(700px 340px at 50% -8%, rgba(201,162,75,.13), transparent 68%), linear-gradient(172deg,#0C1730,#070D1B)`,
      fontFamily: "'Jost', sans-serif", padding: "0 0 40px",
    }}>
      <div style={{ position: "sticky", top: 0, zIndex: 10, background: "rgba(7,13,27,.94)", backdropFilter: "blur(8px)", borderBottom: "1px solid rgba(201,162,75,.2)", padding: "13px 20px" }}>
        <div style={{ maxWidth: 560, margin: "0 auto", display: "flex", alignItems: "center", gap: 12 }}>
          <span style={{ fontSize: 10, letterSpacing: "0.26em", color: "rgba(201,162,75,.85)", whiteSpace: "nowrap" }}>MST YAYINCILIK</span>
          <div style={{ flex: 1, height: 1, background: "rgba(201,162,75,.18)" }}>
            <div style={{ height: "100%", width: `${((adim + 1) / adimlar.length) * 100}%`, background: "linear-gradient(90deg,#8C6A22,#F0D68A)", transition: "width .45s ease" }} />
          </div>
          <span style={{ fontSize: 11, color: "rgba(245,240,228,.5)", whiteSpace: "nowrap" }}>{adim + 1}/{adimlar.length}</span>
        </div>
      </div>

      <div style={{ maxWidth: 560, margin: "0 auto", padding: "30px 22px 0" }}>
        {adimlar[adim].icerik}

        {!tamamlandi && (
          <div style={{ marginTop: 32, display: "flex", gap: 14, alignItems: "center" }}>
            {adim > 0 && (
              <div style={{ flex: "0 0 auto" }}>
                <Dugme tur="sessiz" tamGenislik={false} kucuk onClick={() => setAdim(adim - 1)}>GERİ</Dugme>
              </div>
            )}
            {!son && (
              <div style={{ flex: 1 }}>
                <Dugme tur="asil" disabled={!ilerleyebilir} onClick={() => setAdim(adim + 1)}>
                  {adim === 0 ? "BAŞLAYALIM" : "DEVAM"}
                </Dugme>
              </div>
            )}
          </div>
        )}

        {adim === 0 && !ilerleyebilir && (
          <div style={{ fontSize: 12.5, color: "rgba(245,240,228,.45)", textAlign: "center", marginTop: 10 }}>
            Devam etmek için eserinizin adını yazın
          </div>
        )}
      </div>
    </div>
  );
}

function Dugme({ children, onClick, disabled, tur = "asil", tamGenislik = true, kucuk = false, type }) {
  const [uzerinde, setUzerinde] = useState(false);
  const renk = disabled
    ? "rgba(245,240,228,.32)"
    : tur === "asil" ? "#F0D68A" : tur === "orta" ? "#F5F0E4" : "rgba(245,240,228,.62)";
  const cizgi = disabled
    ? "rgba(245,240,228,.14)"
    : tur === "sessiz"
      ? "rgba(201,162,75,.28)"
      : `linear-gradient(90deg,transparent,rgba(201,162,75,${uzerinde ? ".95" : tur === "asil" ? ".8" : ".5"}),transparent)`;

  // Zemin + çerçeve: butonun buton olduğu ilk bakışta anlaşılsın (sessiz varyant çıplak kalır)
  const zemin = disabled
    ? "rgba(245,240,228,.03)"
    : tur === "asil"
      ? `linear-gradient(180deg, rgba(201,162,75,${uzerinde ? ".22" : ".15"}), rgba(201,162,75,${uzerinde ? ".10" : ".05"}))`
      : tur === "orta" ? `rgba(245,240,228,${uzerinde ? ".08" : ".05"})` : "transparent";
  const cerceve = disabled
    ? "1px solid rgba(245,240,228,.12)"
    : tur === "asil" ? "1px solid rgba(201,162,75,.55)"
    : tur === "orta" ? "1px solid rgba(245,240,228,.22)"
    : "none";

  return (
    <div style={{ width: tamGenislik ? "100%" : "auto", display: tamGenislik ? "block" : "inline-block" }}>
      <div style={{ border: cerceve, background: zemin, transition: "background .2s" }}>
        <button
          type={type || "button"}
          onClick={disabled ? undefined : onClick}
          disabled={disabled}
          onMouseEnter={() => setUzerinde(true)}
          onMouseLeave={() => setUzerinde(false)}
          style={{
            width: "100%", background: "transparent", border: "none", borderRadius: 0,
            color: renk, padding: kucuk ? "10px 14px" : "14px 18px",
            fontSize: kucuk ? 12.5 : 14, fontWeight: 500,
            letterSpacing: kucuk ? "0.14em" : "0.2em",
            fontFamily: "'Jost', sans-serif",
            cursor: disabled ? "default" : "pointer",
            display: "flex", alignItems: "center", justifyContent: "center", gap: 12,
            transition: "color .2s",
          }}
        >
          {children}
          {tur !== "sessiz" && <span style={{ fontSize: kucuk ? 14 : 17, transform: uzerinde ? "translateX(3px)" : "none", transition: "transform .2s" }}>→</span>}
        </button>
        <div style={{ height: 1, background: cizgi }} />
      </div>
    </div>
  );
}

