const TR_MONTHS = ["Oca","Şub","Mar","Nis","May","Haz","Tem","Ağu","Eyl","Eki","Kas","Ara"];
function formatDate(iso) { if (!iso) return ""; const [y,m,d]=String(iso).slice(0,10).split("-").map(Number); if (!y||!m||!d) return ""; return `${d} ${TR_MONTHS[m-1]}`; }
function clonePipeline(stages) { return stages.map((s) => ({ ...s })); }
function tl(n) { return Number(n).toLocaleString("tr-TR") + " ₺"; }

