function getNotifications(account) {
  const items = [];
  account.books.forEach((b) => {
    const days = daysUntilStockout(b);
    if (days !== null && days <= 14) items.push({ id: `stok-${b.id}`, text: `${b.title}: tahmini ${days} gün içinde stoksuz kalabilir`, tone: "warn" });
    const kapak = b.pipeline.find((s) => s.key === "kapak");
    if (kapak && kapak.needsApproval && !kapak.approved && kapak.status !== "beklemede") items.push({ id: `kapak-${b.id}`, text: `${b.title}: kapak tasarımı onayınızı bekliyor`, tone: "info" });
  });
  if (account.nextPayoutDate) {
    const days = Math.round((new Date(account.nextPayoutDate) - new Date("2026-06-28")) / 86400000);
    if (days >= 0 && days <= 14) items.push({ id: "odeme", text: `Sonraki telif ödemeniz ${days} gün içinde yapılacak`, tone: "good" });
  }
  return items;
}

function NotificationBell({ account }) {
  const [open, setOpen] = useState(false);
  const items = getNotifications(account);
  const toneColor = { warn: THEME.danger, info: THEME.warn, good: THEME.success };
  // Bildirim yoksa açıldıktan 5 sn sonra otomatik kapan
  React.useEffect(() => {
    if (open && items.length === 0) {
      const t = setTimeout(() => setOpen(false), 5000);
      return () => clearTimeout(t);
    }
  }, [open, items.length]);
  return (
    <div style={{ position: "relative" }}>
      <button onClick={() => setOpen(!open)} style={{ background: "none", border: `1px solid ${THEME.border}`, color: THEME.cyan, borderRadius: 0, padding: "5px 9px", fontSize: 14.5, cursor: "pointer", position: "relative" }}>
        🔔
        {items.length > 0 && <span style={{ position: "absolute", top: -4, right: -4, background: THEME.danger, color: "#03040A", borderRadius: "50%", width: 15, height: 15, fontSize: 14, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 700 }}>{items.length}</span>}
      </button>
      {open && (
        <div style={{ position: "absolute", right: 0, top: 32, width: 260, background: THEME.yuzey, border: `1px solid ${THEME.border}`, borderRadius: 0, boxShadow: "0 8px 28px rgba(0,0,0,0.6)", zIndex: 20, padding: 8 }}>
          {items.length === 0 ? (
            <div style={{ fontSize: 14, color: THEME.textMuted, padding: "8px 6px" }}>Yeni bildiriminiz yok.</div>
          ) : items.map((n) => (
            <div key={n.id} style={{ fontSize: 14, color: toneColor[n.tone], padding: "8px 6px", borderBottom: `1px solid ${THEME.divider}` }}>{n.text}</div>
          ))}
        </div>
      )}
    </div>
  );
}

