          <div style={{ fontFamily: "'Cormorant Garamond',serif", fontSize: 24, fontWeight: 300, color: '#F0D68A', lineHeight: 1.25, marginBottom: 10, animation: 'mstFadeUp .8s both .3s' }}>{versiyon.bas}</div>
