function SupportSection({ requests, onSubmit }) {
  const [subject, setSubject] = useState(""); const [message, setMessage] = useState("");
  const submit = (e) => { e.preventDefault(); if (!subject.trim() || !message.trim()) return; onSubmit({ subject: subject.trim(), message: message.trim() }); setSubject(""); setMessage(""); };
  return (
    <div style={{ marginTop: 8 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 16, marginTop: 34 }}><span style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "clamp(18px, 5.2vw, 25px)", color: "#F0D68A", fontWeight: 600 }}>Destek talebi oluştur</span><span style={{ flex: 1, height: 1, background: "linear-gradient(90deg,rgba(201,162,75,.45),transparent)" }} /></div>
      <form onSubmit={submit} style={{ background: THEME.yuzey, border: `1px solid ${THEME.border}`, borderRadius: 0, padding: 14, display: "flex", flexDirection: "column", gap: 10, marginBottom: 18 }}>
        <input value={subject} onChange={(e) => setSubject(e.target.value)} placeholder="Konu" style={{ padding: "9px 11px", border: `1px solid ${THEME.border}`, borderRadius: 0, fontSize: 16, boxSizing: "border-box", background: THEME.yuzeyDik, color: THEME.textLight }} />
        <textarea value={message} onChange={(e) => setMessage(e.target.value)} placeholder="Mesajınız" rows={3} style={{ padding: "9px 11px", border: `1px solid ${THEME.border}`, borderRadius: 0, fontSize: 16, boxSizing: "border-box", resize: "vertical", fontFamily: "inherit", background: THEME.yuzeyDik, color: THEME.textLight }} />
        <Dugme type="submit" tur="asil">Gönder</Dugme>
      </form>
      {requests.length > 0 && (<>
        <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 16, marginTop: 34 }}><span style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "clamp(18px, 5.2vw, 25px)", color: "#F0D68A", fontWeight: 600 }}>Taleplerim</span><span style={{ flex: 1, height: 1, background: "linear-gradient(90deg,rgba(201,162,75,.45),transparent)" }} /></div>
        {requests.map((r) => (
          <div key={r.id} style={{ background: THEME.yuzey, border: `1px solid ${THEME.border}`, borderRadius: 0, padding: "12px 14px", marginBottom: 8 }}>
            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}><span style={{ fontSize: 15, color: THEME.textLight }}>{r.subject}</span><span style={{ fontSize: 14, color: r.status === "açık" ? THEME.danger : THEME.success }}>{r.status === "açık" ? "Bekliyor" : "Yanıtlandı"}</span></div>
            <div style={{ fontSize: 14.5, color: THEME.textMuted }}>{r.message}</div>
            {r.reply && <div style={{ fontSize: 14, color: THEME.textLight, background: THEME.headerBg, borderRadius: 0, padding: "8px 10px", marginTop: 8 }}><strong style={{ color: THEME.cyan }}>Yayınevi:</strong> {r.reply}</div>}
          </div>
        ))}
      </>)}
    </div>
  );
}

function PaymentNotice({ wallet, notices, onSubmit, label, token }) {
  const [yontem, setYontem] = useState("kart"); // kart | havale
  const [amount, setAmount] = useState(500);
  const [note, setNote] = useState("");
  const [file, setFile] = useState(null);
  const [kartYukleniyor, setKartYukleniyor] = useState(false);
  const [kartHata, setKartHata] = useState("");
  const handleFile = (e) => { const f = e.target.files[0]; if (!f) return; const reader = new FileReader(); reader.onload = () => setFile({ name: f.name, dataUrl: reader.result, isImage: f.type.startsWith("image/") }); reader.readAsDataURL(f); };
  const submit = (e) => { e.preventDefault(); onSubmit({ amount: Number(amount), note, file }); setNote(""); setFile(null); };
  const inputStyle = { padding: "9px 11px", border: `1px solid ${THEME.border}`, borderRadius: 0, fontSize: 16, boxSizing: "border-box", background: THEME.yuzeyDik, color: THEME.textLight };

  // Kartla öde — backend'de WooCommerce siparişi açar, ödeme sayfasına yönlendirir
  const kartlaOde = async () => {
    const tutar = Number(amount);
    if (!tutar || tutar < 1) { setKartHata("Geçerli bir tutar girin."); return; }
    setKartYukleniyor(true); setKartHata("");
    try {
      const r = await fetch(`${BACKEND_URL}/api/author/kart-odeme/baslat`, {
        method: "POST",
        headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
        body: JSON.stringify({ tutar }),
      });
      const data = await r.json();
      if (data.odemeUrl) window.location.href = data.odemeUrl;
      else setKartHata(data.error || "Ödeme başlatılamadı.");
    } catch { setKartHata("Bağlantı hatası. Tekrar deneyin."); }
    finally { setKartYukleniyor(false); }
  };

  // Sekmeler bir SEÇİMDİR, eylem butonu değil — dolgusuz, altın alt çizgili sekme dili
  const sekmeStil = (aktif) => ({
    flex: 1, padding: "11px 0", fontSize: 13.5, fontWeight: aktif ? 600 : 400, cursor: "pointer",
    background: aktif ? "rgba(201,162,75,.08)" : "transparent",
    color: aktif ? "#F0D68A" : THEME.textMuted,
    border: `1px solid ${aktif ? "rgba(201,162,75,.5)" : THEME.border}`,
    borderBottom: aktif ? "2px solid #C9A24B" : `1px solid ${THEME.border}`,
    borderRadius: 0, textAlign: "center", letterSpacing: "0.05em",
  });

  return (
    <div style={{ background: THEME.yuzey, border: `1px solid ${THEME.border}`, borderRadius: 0, padding: 14, marginBottom: 18 }}>
      <div style={{ marginBottom: 12 }}>
        <div style={{ fontSize: 14, letterSpacing: "0.05em", color: THEME.textMuted }}>{label || "HİZMET BAKİYESİ"}</div>
        <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 22, color: THEME.cyan, fontWeight: 600 }}>{tl(wallet.balance)}</div>
      </div>

      {/* Ödeme yöntemi sekmeleri */}
      <div style={{ fontSize: 11, letterSpacing: "0.22em", color: THEME.textMuted, marginBottom: 6 }}>ÖDEME YÖNTEMİ SEÇİN</div>
      <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
        <div onClick={() => setYontem("kart")} style={sekmeStil(yontem === "kart")}>▤ Kartla Öde</div>
        <div onClick={() => setYontem("havale")} style={sekmeStil(yontem === "havale")}>◫ Havale / EFT</div>
      </div>

      {yontem === "kart" ? (
        <>
          <div style={{ background: THEME.headerBg, borderRadius: 0, padding: "10px 12px", fontSize: 14, color: THEME.textLight, lineHeight: 1.7, marginBottom: 12, border: `1px solid ${THEME.border}` }}>
            Kredi/banka kartınızla güvenli ödeme yapın. Ödeme tamamlandığında bakiyeniz <strong style={{ color: THEME.success }}>anında</strong> yüklenir.
          </div>
          <label style={{ fontSize: 15, color: THEME.textMuted }}>Yüklenecek tutar (₺)
            <input type="number" min={50} step={50} value={amount} onChange={(e) => setAmount(e.target.value)} style={{ display: "block", width: "100%", marginTop: 4, ...inputStyle }} />
          </label>
          {kartHata && <div style={{ fontSize: 15, color: THEME.danger, marginTop: 8 }}>{kartHata}</div>}
          <Dugme tur="asil" onClick={kartlaOde} disabled={kartYukleniyor}>{kartYukleniyor ? "Ödeme sayfası açılıyor..." : `${tl(Number(amount) || 0)} Kartla Öde`}</Dugme>
          <div style={{ fontSize: 15, color: THEME.textFaint, textAlign: "center", marginTop: 8 }}>
            Güvenli ödeme · mstyayincilik.com üzerinden
          </div>
        </>
      ) : (
        <>
          <div style={{ background: THEME.headerBg, borderRadius: 0, padding: "10px 12px", fontSize: 14, color: THEME.textLight, lineHeight: 1.7, marginBottom: 12, border: `1px solid ${THEME.border}` }}>
            Havale/EFT yapıp dekontunuzu yükleyin. Yayınevi onayladığında bakiyeniz güncellenir.<br />
            <span style={{ color: THEME.textMuted, fontSize: 11.5 }}>Banka bilgileri için yayınevi ile iletişime geçin.</span>
          </div>
          <form onSubmit={submit} style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            <label style={{ fontSize: 15, color: THEME.textMuted }}>Gönderdiğiniz tutar (₺)
              <input type="number" min={50} step={50} value={amount} onChange={(e) => setAmount(e.target.value)} style={{ display: "block", width: "100%", marginTop: 4, ...inputStyle }} />
            </label>
            <label style={{ fontSize: 15, color: THEME.textMuted }}>Dekont
              <input type="file" accept="image/*,.pdf" onChange={handleFile} style={{ display: "block", width: "100%", marginTop: 4, fontSize: 16, color: THEME.textLight }} />
            </label>
            {file && <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 14, color: THEME.success }}>{file.isImage ? <img src={file.dataUrl} alt="" style={{ width: 40, height: 40, objectFit: "cover", borderRadius: 0, border: `1px solid ${THEME.border}` }} /> : <span>📄</span>}{file.name} eklendi</div>}
            <input value={note} onChange={(e) => setNote(e.target.value)} placeholder="Not (opsiyonel)" style={inputStyle} />
            <Dugme type="submit" tur="asil">Ödeme Bildirimini Gönder</Dugme>
          </form>
        </>
      )}

      {notices.length > 0 && (
        <div style={{ marginTop: 14 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 16, marginTop: 34 }}><span style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "clamp(18px, 5.2vw, 25px)", color: "#F0D68A", fontWeight: 600 }}>Ödeme bildirimlerim</span><span style={{ flex: 1, height: 1, background: "linear-gradient(90deg,rgba(201,162,75,.45),transparent)" }} /></div>
          {notices.map((n) => (
            <div key={n.id} style={{ display: "flex", justifyContent: "space-between", fontSize: 14.5, padding: "8px 0", borderBottom: `1px solid ${THEME.divider}` }}>
              <span>{tl(n.amount)} <span style={{ color: THEME.textMuted }}>· {n.date}</span></span>
              <span style={{ color: n.status === "Onay bekliyor" ? THEME.warn : THEME.success }}>{n.status}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function PerformanceChart({ daily }) {
  const vals = (daily || []).map((v) => Number(v) || 0);
  const max = Math.max(1, ...vals);
  const n = vals.length || 1;
  return (
    <div style={{ height: 70, marginTop: 8, display: "flex", alignItems: "flex-end", gap: 2 }}>
      {vals.map((v, i) => (
        <div
          key={i}
          title={`Gün ${i + 1}: ${v.toLocaleString("tr-TR")} kişi`}
          style={{
            flex: 1,
            height: `${Math.max(4, (v / max) * 100)}%`,
            background: THEME.cyan,
            borderRadius: "2px 2px 0 0",
            minWidth: 2,
            transition: "height .3s ease",
          }}
        />
      ))}
    </div>
  );
}

// Sitedeki .divider süsü — iki altın çizgi arasında döndürülmüş elmas
function Divider({ genislik = 92 }) {
  return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 14, margin: "0 auto" }}>
      <span style={{ height: 1, width: genislik, background: "linear-gradient(90deg,transparent,rgba(201,162,75,.85))" }} />
      <span style={{ width: 6, height: 6, background: "#C9A24B", transform: "rotate(45deg)", boxShadow: "0 0 10px rgba(201,162,75,.35)" }} />
      <span style={{ height: 1, width: genislik, background: "linear-gradient(90deg,rgba(201,162,75,.85),transparent)" }} />
    </div>
  );
}

// Sitedeki .sec-head: küçük altın etiket + büyük serif başlık + açıklama
function BolumBasligi({ etiket, baslik, aciklama, ortala = false }) {
  return (
    <div style={{ textAlign: ortala ? "center" : "left", marginBottom: 30 }}>
      {etiket && (
        <div style={{ fontSize: 11, letterSpacing: "0.4em", textTransform: "uppercase", color: "#C9A24B", fontWeight: 600, marginBottom: 14 }}>
          {etiket}
        </div>
      )}
      <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 34, color: "#fff", fontWeight: 500, lineHeight: 1.1 }}>
        {baslik}
      </div>
      {aciklama && (
        <div style={{ fontSize: 15, color: "rgba(245,240,228,.80)", fontWeight: 300, marginTop: 12, lineHeight: 1.7, maxWidth: 660 }}>
          {aciklama}
        </div>
      )}
      {ortala && <div style={{ marginTop: 18 }}><Divider /></div>}
    </div>
  );
}

// ============ Uygulamayı indir şeridi ============
// Sadece Android tarayıcıda görünür. Uygulamanın İÇİNDE açıldığında görünmez —
// bunu display-mode:standalone ile anlıyoruz (TWA ve kurulu PWA ikisi de bunu bildirir).
// Kapatan bir daha görmez (tercih cihazda saklanır).
const PLAY_STORE_LINKI = ""; // Play Store yayına girince buraya adres yazılacak

function uygulamaIcindeMi() {
  try {
    return window.matchMedia("(display-mode: standalone)").matches
      || window.navigator.standalone === true
      || document.referrer.startsWith("android-app://");
  } catch { return false; }
}

function UygulamaIndirSeridi() {
  const [gorunur, setGorunur] = useState(false);
  const [kurulumOlayi, setKurulumOlayi] = useState(null);

  useEffect(() => {
    const android = /Android/i.test(navigator.userAgent);
    let kapatilmis = false;
    try { kapatilmis = localStorage.getItem("mst_uygulama_seridi_kapali") === "1"; } catch {}
    if (android && !uygulamaIcindeMi() && !kapatilmis) setGorunur(true);

    // Tarayıcı "kurulabilir" derse, Play Store olmadan da ana ekrana eklenebilir
    const yakala = (e) => { e.preventDefault(); setKurulumOlayi(e); };
    window.addEventListener("beforeinstallprompt", yakala);
    return () => window.removeEventListener("beforeinstallprompt", yakala);
  }, []);

  if (!gorunur) return null;

  const kapat = () => {
    setGorunur(false);
    try { localStorage.setItem("mst_uygulama_seridi_kapali", "1"); } catch {}
  };

  const kur = async () => {
    if (PLAY_STORE_LINKI) { window.open(PLAY_STORE_LINKI, "_blank"); return; }
    if (kurulumOlayi) { kurulumOlayi.prompt(); await kurulumOlayi.userChoice; kapat(); }
  };

  // Play linki de kurulum imkânı da yoksa şeridi hiç gösterme
  if (!PLAY_STORE_LINKI && !kurulumOlayi) return null;

  return (
    <div style={{
      position: "fixed", left: 0, right: 0, bottom: 0, zIndex: 60,
      background: "linear-gradient(180deg,#0C1730,#050A16)",
      borderTop: "1px solid rgba(201,162,75,.32)",
      padding: "12px clamp(14px,4vw,20px)",
      display: "flex", alignItems: "center", gap: 12,
    }}>
      <img src={LOGO_GOLD} alt="" style={{ width: 30, height: "auto", flexShrink: 0 }} />
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontSize: 13.5, color: "#F5F0E4", fontWeight: 500 }}>MST Yazar uygulaması</div>
        <div style={{ fontSize: 11.5, color: "rgba(245,240,228,.62)" }}>Ana ekranından tek dokunuşla aç</div>
      </div>
      <Dugme tur="asil" onClick={kur}>KUR</Dugme>
      <button onClick={kapat} aria-label="Kapat" style={{
        background: "none", border: "none", color: "rgba(245,240,228,.5)", fontSize: 20, cursor: "pointer", padding: "0 4px",
      }}>×</button>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// REKLAM — yeni akış (29 Tem 2026)
// Eski ekran "Kampanya Başlat" diyordu ama hiçbir kampanya açılmıyordu.
// Yeni akış dürüst: yazar başvurur, MST kalem kalem teklif hazırlar,
// yazar onaylar, iş yürütülür, sonuç raporu gelir.
// Self-serve Meta kampanyaları (Hat 1) Meta altyapısı kurulunca eklenecek.
// ═══════════════════════════════════════════════════════════════════
// ═══════════════════════════════════════════════════════════════════
// REKLAM SİMÜLASYONU
// Yazar kampanya açmadan önce ne göreceğini yaşasın. Rakamlar örnek —
// bu ekranda "SİMÜLASYON" etiketi kalıcı olarak duruyor, gerçek sanılmasın.
// Kitap adı yazarın kendi kitabı, çünkü kendini o ekranda görmesi gerekiyor.
// Sadece hiç kampanyası olmayan yazara gösterilir.
// ═══════════════════════════════════════════════════════════════════
function ReklamSimulasyonu({ books }) {
  const [oynuyor, setOynuyor] = useState(false);
  const [ilerleme, setIlerleme] = useState(0);      // 0-1 arası
  const [analiz, setAnaliz] = useState("");
  const [bitti, setBitti] = useState(false);

  const kitap = (books && books[0]) || null;
  const kitapAdi = kitap?.title || "Kitabınız";
  const mevcutSatis = Number(kitap?.totalSold || 0);

  // Örnek senaryo: 1.500 ₺ · 14 gün
  const hedef = useMemo(() => ({
    butce: 1500, gun: 14,
    erisim: 11800, gosterim: 27400, tiklama: 340,
    harcanan: 1500, satisArtisi: 14,
  }), []);

  const analizMetni =
    `${hedef.gun} günde ${hedef.erisim.toLocaleString("tr-TR")} kişiye ulaştın ve ${hedef.tiklama} kişi ` +
    `kitabına baktı. Tıklama başına ${(hedef.harcanan / hedef.tiklama).toFixed(2)} ₺ ödedin — bu, kitap ` +
    `reklamlarında iyi bir seviye. Bu dönemde satışın ${hedef.satisArtisi} adet arttı. ` +
    `Bir sonraki kampanyada aynı kitleyle devam etmeni, bütçeyi biraz artırmanı öneriyorum.`;

  // Sayaçlar dolsun, sonra analiz yazılsın
  useEffect(() => {
    if (!oynuyor || ilerleme >= 1) return;
    const z = setTimeout(() => setIlerleme(Math.min(1, ilerleme + 0.02)), 26);
    return () => clearTimeout(z);
  }, [oynuyor, ilerleme]);

  useEffect(() => {
    if (ilerleme < 1 || bitti) return;
    if (analiz.length < analizMetni.length) {
      const z = setTimeout(() => setAnaliz(analizMetni.slice(0, analiz.length + 1)), 16);
      return () => clearTimeout(z);
    }
    setBitti(true);
  }, [ilerleme, analiz, bitti, analizMetni]);

  const p = ilerleme;
  const sayi = (x) => Math.round(x * p).toLocaleString("tr-TR");
  const t = (x) => Number(x).toLocaleString("tr-TR");

  const kutu = (etiket, deger) => (
    <div key={etiket}>
      <div style={{
        fontFamily: "'Cormorant Garamond', serif", fontSize: 23, fontWeight: 600, lineHeight: 1.1,
        background: THEME.altinMetin, WebkitBackgroundClip: "text", backgroundClip: "text", WebkitTextFillColor: "transparent",
      }}>{deger}</div>
      <div style={{ fontSize: 9.5, letterSpacing: "0.2em", color: "rgba(201,162,75,.75)", marginTop: 4 }}>{etiket}</div>
    </div>
  );

  return (
    <div style={{
      background: `radial-gradient(560px 260px at 50% 0%, rgba(201,162,75,.12), transparent 70%),
                   linear-gradient(172deg, #101E3A, #060B17)`,
      border: "1px solid rgba(201,162,75,.32)", padding: "24px 22px", marginBottom: 26,
    }}>
      <style>{`
        @keyframes rsImlec { 0%,49%{opacity:1} 50%,100%{opacity:0} }
        .rs-imlec { display:inline-block; width:2px; height:1em; background:#F0D68A; margin-left:3px; vertical-align:-2px; animation: rsImlec 1s step-end infinite }
        .rs-bar { transition: width .1s linear }
      `}</style>

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 12, marginBottom: 18 }}>
        <div>
          <div style={{ fontSize: 10, letterSpacing: "0.3em", color: "rgba(201,162,75,.85)", fontWeight: 600 }}>SİMÜLASYON</div>
          <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 25, color: "#fff", fontWeight: 600, marginTop: 8, lineHeight: 1.25 }}>
            Reklam verdiğinizde<br />bunları göreceksiniz
          </div>
        </div>
        <span style={{ fontSize: 9.5, letterSpacing: "0.14em", color: "rgba(245,240,228,.5)", border: "1px solid rgba(245,240,228,.22)", padding: "4px 8px", whiteSpace: "nowrap" }}>
          ÖRNEK VERİ
        </span>
      </div>

      {!oynuyor ? (
        <>
          <div style={{ fontSize: 14.5, color: "rgba(245,240,228,.80)", lineHeight: 1.8, fontWeight: 300, marginBottom: 18 }}>
            "{kitapAdi}" için 1.500 ₺ bütçeyle 14 günlük bir kampanya açtığınızı varsayalım.
            Ekranınız gün gün nasıl dolar, kampanya bitince danışmanınız ne söyler — izleyin.
          </div>
          <Dugme tur="asil" onClick={() => setOynuyor(true)}>▶ SİMÜLASYONU OYNAT</Dugme>
        </>
      ) : (
        <>
          {/* Kampanya kartı — sayaçlar doluyor */}
          <div style={{ background: "rgba(12,23,48,.6)", border: "1px solid rgba(201,162,75,.22)", padding: "18px 20px" }}>
            <div style={{ display: "flex", justifyContent: "space-between", gap: 10, flexWrap: "wrap" }}>
              <div>
                <div style={{ fontSize: 15, color: THEME.textLight, fontWeight: 500 }}>{kitapAdi}</div>
                <div style={{ fontSize: 12.5, color: "rgba(245,240,228,.6)", marginTop: 3, fontWeight: 300 }}>
                  Kitap okurları — geniş · {hedef.gun} gün · {t(hedef.butce)} ₺
                </div>
              </div>
              <span style={{ fontSize: 10, letterSpacing: "0.16em", color: p < 1 ? "#9FC7A8" : "rgba(245,240,228,.62)", border: `1px solid ${p < 1 ? "#9FC7A8" : "rgba(245,240,228,.3)"}`, padding: "4px 9px", height: "fit-content" }}>
                {p < 1 ? "YAYINDA" : "TAMAMLANDI"}
              </span>
            </div>

            {/* İlerleme çubuğu */}
            <div style={{ height: 3, background: "rgba(245,240,228,.10)", margin: "16px 0 18px" }}>
              <div className="rs-bar" style={{ height: "100%", width: `${p * 100}%`, background: "linear-gradient(90deg,#8C6A22,#F0D68A)" }} />
            </div>

            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(84px,1fr))", gap: 14 }}>
              {kutu("ULAŞILAN", sayi(hedef.erisim))}
              {kutu("TIKLAMA", sayi(hedef.tiklama))}
              {kutu("HARCANAN", sayi(hedef.harcanan) + " ₺")}
              {kutu("KALAN", t(Math.round(hedef.butce - hedef.harcanan * p)) + " ₺")}
            </div>

            {p > 0.35 && (
              <div style={{ fontSize: 14, color: "#9FC7A8", marginTop: 16, fontWeight: 300 }}>
                Kampanya başladığından beri satış: {t(mevcutSatis)} → {t(mevcutSatis + Math.round(hedef.satisArtisi * p))}
                {p > 0.4 ? ` (+${Math.round(hedef.satisArtisi * p)})` : ""}
              </div>
            )}
          </div>

          {/* Danışman analizi */}
          {p >= 1 && (
            <div style={{ marginTop: 18, background: "rgba(201,162,75,.05)", border: "1px solid rgba(201,162,75,.28)", padding: "18px 20px" }}>
              <div style={{ fontSize: 10, letterSpacing: "0.28em", color: "rgba(201,162,75,.82)", marginBottom: 10 }}>
                A . I .&nbsp;&nbsp;DANIŞMANINIZIN ANALİZİ
              </div>
              <div style={{ fontSize: 14.5, color: "rgba(245,240,228,.86)", lineHeight: 1.85, fontWeight: 300 }}>
                {analiz}{!bitti && <span className="rs-imlec" />}
              </div>
            </div>
          )}

          {bitti && (
            <div style={{ marginTop: 18, textAlign: "center" }}>
              <div style={{ fontSize: 13, color: "rgba(245,240,228,.55)", lineHeight: 1.7, fontWeight: 300, marginBottom: 14 }}>
                Yukarıdaki rakamlar örnektir. Gerçek sonuç kitabınıza, görselinize ve
                bütçenize göre değişir — ama ekranınız aynen böyle görünür.
              </div>
              <button onClick={() => { setOynuyor(false); setIlerleme(0); setAnaliz(""); setBitti(false); }} style={{
                background: "none", color: "rgba(245,240,228,.62)", border: "1px solid rgba(201,162,75,.28)",
                padding: "10px 18px", fontSize: 13, cursor: "pointer", fontFamily: "'Jost', sans-serif",
              }}>Tekrar oynat</button>
            </div>
          )}
        </>
      )}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// KENDİ KAMPANYAM — yazar kitabını doğrudan reklama açar
// Bütçe bloke edilir, harcanmaz. Onaydan sonra Meta'da gerçek kampanya
// kurulur. Kampanya bitince harcanmayan tutar iade edilir.
// ═══════════════════════════════════════════════════════════════════
const KAMPANYA_DURUM = {
  onay_bekliyor: { ad: "Onay bekliyor", renk: "#F0D68A", not: "Bütçeniz ayrıldı, henüz harcanmadı." },
  onaylandi:     { ad: "Onaylandı",     renk: "#9FC7A8", not: "Yayına alınıyor." },
  yayinda:       { ad: "Yayında",       renk: "#9FC7A8", not: "Reklamınız gösteriliyor." },
  bitti:         { ad: "Tamamlandı",    renk: "rgba(245,240,228,.62)", not: "" },
  reddedildi:    { ad: "Reddedildi",    renk: "#E09080", not: "" },
  iptal:         { ad: "İptal edildi",  renk: "rgba(245,240,228,.48)", not: "" },
};

// EKLENDİ (9 Ağu 2026, "sistem sizin için ne öğrendi" — kural motorunun
// yazara açılması): kampanya yayındayken, gerçek Meta verisine (frekans,
// kreatif yaşı) dayanan öneriler getirir ve "uygula" derse gerçekten
// backend'e (kitle-genislet) bağlanır — mockup değil.
function KampanyaOnerileri({ kampanyaId, token, onUygulandi }) {
  const [oneriler, setOneriler] = useState(null);
  const [uygulaniyor, setUygulaniyor] = useState("");
  const [mesaj, setMesaj] = useState("");

  const api = async (yol, ayar = {}) => {
    const r = await fetch(`${BACKEND_URL}${yol}`, {
      ...ayar,
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}`, ...(ayar.headers || {}) },
    });
    return r.json();
  };

  useEffect(() => {
    api(`/api/author/reklam/kampanya/${kampanyaId}/oneriler`)
      .then((d) => setOneriler(d.oneriler || []))
      .catch(() => setOneriler([]));
  }, [kampanyaId]);

  // GENİŞLETİLDİ (9 Ağu 2026, "eksiksiz denetim" — "metin yorulmuş" önerisi
  // gerçek bir uygulaması yoktu, "MST ekibiyle iletişime geçin" diyordu):
  // artık her iki öneri türü de gerçek backend uçlarına bağlı.
  const UC_ESLESME = { kitle_genislet: "kitle-genislet", metin_uret: "metin-yenile" };
  const uygula = async (oneri) => {
    const uc = UC_ESLESME[oneri.tur];
    if (!uc) { setMesaj("Bu öneriyi uygulamak için MST ekibiyle iletişime geçebilirsiniz."); return; }
    setUygulaniyor(oneri.tur); setMesaj("");
    try {
      const d = await api(`/api/author/reklam/kampanya/${kampanyaId}/${uc}`, { method: "POST", body: "{}" });
      setMesaj(d.ok ? d.mesaj : (d.error || "Uygulanamadı."));
      if (d.ok) { setOneriler((liste) => liste.filter((o) => o.tur !== oneri.tur)); onUygulandi?.(); }
    } catch { setMesaj("Sunucuya ulaşılamadı."); }
    finally { setUygulaniyor(""); }
  };

  if (!oneriler || !oneriler.length) return null;

  return (
    <div style={{ marginTop: 16, borderTop: "1px solid rgba(201,162,75,.20)", paddingTop: 14 }}>
      <div style={{ fontSize: 10.5, letterSpacing: "0.24em", color: "rgba(201,162,75,.82)", marginBottom: 10 }}>
        SİSTEM SİZİN İÇİN NE ÖĞRENDİ
      </div>
      <div style={{ display: "grid", gap: 8 }}>
        {oneriler.map((o) => (
          <div key={o.tur} style={{ background: "rgba(201,162,75,.05)", border: "1px solid rgba(201,162,75,.22)", borderLeft: "3px solid #C9A24B", padding: "10px 14px" }}>
            <div style={{ fontSize: 13, color: THEME.textLight, fontWeight: 500 }}>{o.baslik}</div>
            <div style={{ fontSize: 12, color: "rgba(245,240,228,.62)", marginTop: 4, lineHeight: 1.6, fontWeight: 300 }}>{o.aciklama}</div>
            <button onClick={() => uygula(o)} disabled={uygulaniyor === o.tur} style={{
              marginTop: 8, background: "none", color: "#F0D68A",
              border: "1px solid rgba(201,162,75,.4)", padding: "7px 14px", fontSize: 12,
              cursor: "pointer", fontFamily: "'Jost', sans-serif",
            }}>{uygulaniyor === o.tur ? "Uygulanıyor…" : "Uygula"}</button>
          </div>
        ))}
      </div>
      {mesaj && <div style={{ fontSize: 12.5, color: "#F0D68A", marginTop: 8 }}>{mesaj}</div>}
    </div>
  );
}

// EKLENDİ (9 Ağu 2026, "7. tasarım güzel ama yetersiz, veriyi işleyebildiğimizi
// göster" — genişletilmiş "reklam kokpiti"): mevcut, dört metrikli basit
// görünüm yerine, /rapor ucundan gelen TÜM Meta verisini (video izlenme,
// etkileşim, maliyet detayı, kalite sıralamaları, günlük trend, satış etkisi)
// gösteren zengin bir panel. Sistemin zaten topladığı ama önceden hiç
// gösterilmeyen verileri gün yüzüne çıkarır.
function KampanyaKokpit({ kampanyaId, token, yenilemeTetigi }) {
  const [rapor, setRapor] = useState(null);
  const [hata, setHata] = useState(false);

  useEffect(() => {
    fetch(`${BACKEND_URL}/api/author/reklam/kampanya/${kampanyaId}/rapor`, {
      headers: { Authorization: `Bearer ${token}` },
    }).then((r) => r.json()).then((d) => {
      if (d.ok && d.hazir) setRapor(d); else setHata(true);
    }).catch(() => setHata(true));
  }, [kampanyaId, yenilemeTetigi]);

  if (hata || !rapor) return null;
  const t = rapor.toplam || {};
  const gunluk = rapor.gunluk || [];
  const gold = "#F0D68A";
  const dim = "rgba(245,240,228,.58)";
  const border = "rgba(201,162,75,.20)";

  const stat = (l, v) => (
    <div>
      <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 18, fontWeight: 600, color: gold }}>{v}</div>
      <div style={{ fontSize: 9, letterSpacing: "0.14em", color: "rgba(201,162,75,.75)", marginTop: 2 }}>{l}</div>
    </div>
  );
  const sayi = (n) => (n == null ? "—" : Number(n).toLocaleString("tr-TR"));
  const para = (n) => (n == null ? "—" : Number(n).toLocaleString("tr-TR") + " ₺");

  const rankRenk = (v) => {
    if (!v) return dim;
    if (String(v).toLowerCase().includes("üstü") || String(v).toLowerCase().includes("above")) return "#9FC7A8";
    if (String(v).toLowerCase().includes("altı") || String(v).toLowerCase().includes("below")) return "#E09080";
    return gold;
  };

  // EKLENDİ (9 Ağu 2026, "10 versiyon" tartışmasında beğenilen 7. tasarımın
  // ("dairesel gösterge") ana unsuru — o zaman kullanıcı "güzel ama yetersiz"
  // demişti, zenginleştirilmiş veri seti eklenmişti ama dairesel gösterge
  // kendisi hiç gerçek koda işlenmemişti. Artık gerçek harcananOran'a bağlı
  // bir SVG halka — bütçenin ne kadarının kullanıldığını tek bakışta gösterir.
  const oran = Math.min(100, rapor.harcananOran ?? 0);
  const r = 42, cevre = 2 * Math.PI * r;
  const halkaRenk = rapor.butceUyariSeviyesi === "kritik" ? "#E09080" : rapor.butceUyariSeviyesi === "uyari" ? "#E0B060" : gold;

  return (
    <div style={{ marginTop: 16, borderTop: `1px solid ${border}`, paddingTop: 14 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 18, marginBottom: 14, flexWrap: "wrap" }}>
        <svg width="100" height="100" viewBox="0 0 100 100" style={{ flexShrink: 0 }}>
          <circle cx="50" cy="50" r={r} fill="none" stroke="rgba(201,162,75,.15)" strokeWidth="7" />
          <circle cx="50" cy="50" r={r} fill="none" stroke={halkaRenk} strokeWidth="7" strokeLinecap="round"
            strokeDasharray={cevre} strokeDashoffset={cevre * (1 - oran / 100)}
            transform="rotate(-90 50 50)" style={{ transition: "stroke-dashoffset .6s ease" }} />
          <text x="50" y="47" textAnchor="middle" fontSize="20" fontWeight="600" fill={gold} fontFamily="'Cormorant Garamond', serif">%{oran}</text>
          <text x="50" y="63" textAnchor="middle" fontSize="8" fill={dim} letterSpacing="0.05em">BÜTÇE</text>
        </svg>
        <div>
          <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 18, color: THEME.textLight, fontWeight: 500 }}>{rapor.kitap}</div>
          <div style={{ fontSize: 12, color: dim, marginTop: 3 }}>{para(t.harcama)} / {para(rapor.butce)} harcandı</div>
          {rapor.dogrulama?.sonGuncelleme && (
            <div style={{ fontSize: 10.5, color: "rgba(245,240,228,.42)", marginTop: 3 }}>
              Son güncelleme: {new Date(rapor.dogrulama.sonGuncelleme).toLocaleString("tr-TR")}
            </div>
          )}
        </div>
      </div>

      {/* EKLENDİ (9 Ağu 2026, "eksiksiz denetim" — bütçe uyarısı eksikti):
          önceden yazar bütçesi bitene kadar hiçbir işaret görmüyordu. */}
      {rapor.butceUyariSeviyesi && (
        <div style={{
          marginBottom: 12, fontSize: 12, lineHeight: 1.6, padding: "8px 12px",
          background: rapor.butceUyariSeviyesi === "kritik" ? "rgba(224,144,128,.10)" : "rgba(224,176,96,.10)",
          border: `1px solid ${rapor.butceUyariSeviyesi === "kritik" ? "rgba(224,144,128,.4)" : "rgba(224,176,96,.4)"}`,
          color: rapor.butceUyariSeviyesi === "kritik" ? "#E09080" : "#E0B060",
        }}>
          Bütçenizin %{rapor.harcananOran}'i kullanıldı{rapor.butceUyariSeviyesi === "kritik" ? " — kampanya yakında otomatik duracak." : "."}
        </div>
      )}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(90px,1fr))", gap: 12, marginBottom: 14 }}>
        {stat("GÖSTERİM", sayi(t.gosterim))}
        {stat("ULAŞILAN KİŞİ", sayi(t.erisim))}
        {stat("TIKLAMA", sayi(t.tiklama))}
        {stat("TIKLAMA ORANI", t.ctr != null ? `%${Number(t.ctr).toFixed(2)}` : "—")}
        {stat("HARCANAN", para(t.harcama))}
        {stat("TIKLAMA BAŞINA", t.cpc != null ? Number(t.cpc).toFixed(2) + " ₺" : "—")}
      </div>

      {(t.begeni || t.yorum || t.paylasim) ? (
        <div style={{ marginBottom: 14 }}>
          <div style={{ fontSize: 9.5, letterSpacing: "0.18em", color: "rgba(201,162,75,.75)", marginBottom: 8 }}>GÖNDERİ ETKİLEŞİMİ</div>
          <div style={{ display: "flex", gap: 20, fontSize: 12.5, color: dim, fontWeight: 300 }}>
            <span>{sayi(t.begeni)} beğeni</span><span>{sayi(t.yorum)} yorum</span><span>{sayi(t.paylasim)} paylaşım</span>
          </div>
        </div>
      ) : null}

      {t.video100 != null && (t.videoIzlenme > 0) ? (
        <div style={{ marginBottom: 14 }}>
          <div style={{ fontSize: 9.5, letterSpacing: "0.18em", color: "rgba(201,162,75,.75)", marginBottom: 8 }}>VİDEO İZLENME (TAMAMLAMA)</div>
          <div style={{ display: "flex", gap: 2, height: 26 }}>
            {[["25%", t.video25], ["50%", t.video50], ["75%", t.video75], ["100%", t.video100]].map(([l, v]) => (
              <div key={l} style={{ flex: 1, textAlign: "center" }}>
                <div style={{ height: Math.max(4, Math.min(26, (v || 0) / (t.video25 || 1) * 26)), background: gold, opacity: 0.6, marginBottom: 3 }} />
                <div style={{ fontSize: 9, color: dim }}>{l}</div>
              </div>
            ))}
          </div>
        </div>
      ) : null}

      {rapor.satisFarki != null && (
        <div style={{ marginBottom: 14, background: "rgba(201,162,75,.04)", border: `1px solid ${border}`, padding: "10px 14px" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 14, flexWrap: "wrap" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <div style={{ textAlign: "center" }}>
                <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 20, color: THEME.textLight }}>{rapor.satisOncesi}</div>
                <div style={{ fontSize: 9, color: dim }}>öncesi</div>
              </div>
              <span style={{ color: gold }}>→</span>
              <div style={{ textAlign: "center" }}>
                <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 20, color: gold }}>{rapor.satisSonrasi}</div>
                <div style={{ fontSize: 9, color: dim }}>şu an</div>
              </div>
            </div>
            {t.ciro != null && stat("CİRO", para(t.ciro))}
            {t.roas != null && stat("ROAS", Number(t.roas).toFixed(2) + "x")}
          </div>
        </div>
      )}

      {(t.kaliteSirasi || t.etkilesimSirasi || t.donusumSirasi) && (
        <div style={{ marginBottom: 4 }}>
          <div style={{ fontSize: 9.5, letterSpacing: "0.18em", color: "rgba(201,162,75,.75)", marginBottom: 8 }}>META KALİTE SIRALAMASI</div>
          <div style={{ display: "flex", gap: 18, fontSize: 12, fontWeight: 500, flexWrap: "wrap" }}>
            {t.kaliteSirasi && <span style={{ color: rankRenk(t.kaliteSirasi) }}>Kreatif: {t.kaliteSirasi}</span>}
            {t.etkilesimSirasi && <span style={{ color: rankRenk(t.etkilesimSirasi) }}>Etkileşim: {t.etkilesimSirasi}</span>}
            {t.donusumSirasi && <span style={{ color: rankRenk(t.donusumSirasi) }}>Dönüşüm: {t.donusumSirasi}</span>}
          </div>
        </div>
      )}

      {gunluk.length > 1 && (
        <div style={{ marginTop: 14 }}>
          <div style={{ fontSize: 9.5, letterSpacing: "0.18em", color: "rgba(201,162,75,.75)", marginBottom: 8 }}>GÜNLÜK HARCAMA TRENDİ</div>
          <div style={{ display: "flex", alignItems: "flex-end", gap: 3, height: 32 }}>
            {gunluk.slice(-14).map((g, i, arr) => {
              const maxH = Math.max(...arr.map((x) => Number(x.harcama) || 0), 1);
              const h = Math.max(2, ((Number(g.harcama) || 0) / maxH) * 32);
              return <div key={i} style={{ flex: 1, height: h, background: gold, opacity: i === arr.length - 1 ? 1 : 0.45 }} />;
            })}
          </div>
        </div>
      )}

      <div style={{ fontSize: 9.5, color: "rgba(245,240,228,.38)", marginTop: 12, lineHeight: 1.6 }}>
        Bu rakamlar doğrudan Meta'dan alınır, olduğu gibi gösterilir.
      </div>
    </div>
  );
}

