function KendiKampanyam({ books, token }) {
  const [liste, setListe] = useState(null);
  const [kurallar, setKurallar] = useState(null);
  const [acik, setAcik] = useState(false);
  const [bookId, setBookId] = useState(books[0]?.id || "");
  const [butce, setButce] = useState("1000");
  const [gun, setGun] = useState("14");
  const [kitle, setKitle] = useState("genel");
  const [amac, setAmac] = useState("satis");
  const [calisiyor, setCalisiyor] = useState(false);
  const [mesaj, setMesaj] = useState("");
  const [tahmin, setTahmin] = useState(null);
  // EKLENDİ (9 Ağu 2026, "yazar panelinde Feed/Story ayrı görsel yükleme
  // eksik" bulgusu — "örümcek ağı" ilkesi): önceden yazar kendi kampanyasını
  // açarken hiç görsel seçmiyordu, kitabın admin tarafından girilen kapak
  // görseli sessizce kullanılıyordu. Artık yazar, kitap seçtikten sonra
  // isterse kendi Feed (kare) ve Story (dikey) görselini yükleyebiliyor —
  // /author/kitap/:id/reklam-gorseli ucuna, admin panelindeki gorsel-yukle
  // ile aynı format-oranı kontrolü ve mantıkla.
  const [gorselFeed, setGorselFeed] = useState(null); // { dataUrl, dosyaAdi, genislik, yukseklik }
  const [gorselFeedYuklendi, setGorselFeedYuklendi] = useState(false);
  const [gorselFeedUyari, setGorselFeedUyari] = useState(null);
  const [gorselFeedYukleniyor, setGorselFeedYukleniyor] = useState(false);
  const [gorselStory, setGorselStory] = useState(null);
  const [gorselStoryYuklendi, setGorselStoryYuklendi] = useState(false);
  const [gorselStoryUyari, setGorselStoryUyari] = useState(null);
  const [gorselStoryYukleniyor, setGorselStoryYukleniyor] = useState(false);
  // EKLENDİ (9 Ağu 2026, "eksiksiz denetim" — form, backend'in kabul ettiği
  // alanların küçük bir kısmını kullanıyordu): artık yazar kendi reklam
  // metnini/başlığını/açıklamasını yazabiliyor, bölge/ilgi alanı/eylem
  // çağrısı/yönlendirme adresini seçebiliyor. Hepsi opsiyonel — boş
  // bırakılırsa backend zaten makul varsayılanlar kullanıyor.
  const [gelismisAcik, setGelismisAcik] = useState(false);
  const [reklamMetni, setReklamMetni] = useState("");
  const [baslik, setBaslik] = useState("");
  const [aciklama, setAciklama] = useState("");
  const [bolge, setBolge] = useState("turkiye");
  const [ilgi, setIlgi] = useState("genel");
  const [cta, setCta] = useState("LEARN_MORE");
  const [hedefAdres, setHedefAdres] = useState("mst_kitap");
  // Görsel durumu — kitap seçildiğinde, hiç görseli olup olmadığı önceden
  // bildiriliyor (önceden yazar bunu ancak admin reddettiğinde öğreniyordu).
  const [gorselDurumu, setGorselDurumu] = useState(null); // { feedVar, storyVar }
  // Kampanya oluşturmadan ÖNCE, Meta'nın gerçek önizlemesi.
  const [onizlemeler, setOnizlemeler] = useState(null);
  const [onizlemeYukleniyor, setOnizlemeYukleniyor] = useState(false);
  // DÜZELTİLDİ (9 Ağu 2026, gerçek bug — "yeni denetim"): önceden "kitleyi
  // genişlet"/"metni yenile" uygulandığında kokpitteki rakamlar hemen
  // güncellenmiyordu (sadece liste yenileniyordu, kokpitin kendi state'i
  // değil). Bu sayaç, hangi kampanyanın kokpitinin yeniden çekilmesi
  // gerektiğini işaretler — KampanyaKokpit'in useEffect'ine bağlanır.
  const [kokpitYenile, setKokpitYenile] = useState({});

  const api = async (yol, ayar = {}) => {
    const r = await fetch(`${BACKEND_URL}${yol}`, {
      ...ayar,
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}`, ...(ayar.headers || {}) },
    });
    return r.json();
  };

  const yukle = async () => {
    try {
      const d = await api("/api/author/reklam/kampanyalarim");
      setListe(d.kampanyalar || []);
      if (d.kurallar) setKurallar(d.kurallar);
    } catch { setListe([]); }
  };
  useEffect(() => { yukle(); }, []);

  // Kitap seçimi değişince görsel yükleme durumu sıfırlanır — her kitabın
  // kendi görseli var, önceki kitabın "yüklendi" işareti yanıltıcı olur.
  useEffect(() => {
    setGorselFeed(null); setGorselFeedYuklendi(false); setGorselFeedUyari(null);
    setGorselStory(null); setGorselStoryYuklendi(false); setGorselStoryUyari(null);
    setOnizlemeler(null); setGorselDurumu(null);
  }, [bookId]);

  // Kitap seçilir seçilmez, kitabın ZATEN bir görseli var mı kontrol edilir
  // — önceden yazar bunu ancak admin reddettiğinde öğreniyordu.
  useEffect(() => {
    if (!acik || !bookId) return;
    api(`/api/author/kitap/${bookId}/gorsel-durumu`)
      .then((d) => { if (d.ok) setGorselDurumu(d); })
      .catch(() => {});
  }, [bookId, acik]);

  const gorselSecOlustur = (format) => (e) => {
    const f = e.target.files?.[0];
    if (!f) return;
    const setYuklendiFn = format === "feed" ? setGorselFeedYuklendi : setGorselStoryYuklendi;
    const setUyariFn = format === "feed" ? setGorselFeedUyari : setGorselStoryUyari;
    const setOnizlemeFn = format === "feed" ? setGorselFeed : setGorselStory;
    setYuklendiFn(false); setUyariFn(null); setMesaj("");
    const reader = new FileReader();
    reader.onload = () => {
      const img = new Image();
      img.onload = () => setOnizlemeFn({ dataUrl: reader.result, dosyaAdi: f.name, genislik: img.naturalWidth, yukseklik: img.naturalHeight });
      img.src = reader.result;
    };
    reader.readAsDataURL(f);
  };
  const gorselSecFeed = gorselSecOlustur("feed");
  const gorselSecStory = gorselSecOlustur("story");

  const gorseliYukleOlustur = (format) => async () => {
    const gorsel = format === "feed" ? gorselFeed : gorselStory;
    if (!gorsel || !bookId) return;
    const setYukleniyorFn = format === "feed" ? setGorselFeedYukleniyor : setGorselStoryYukleniyor;
    const setYuklendiFn = format === "feed" ? setGorselFeedYuklendi : setGorselStoryYuklendi;
    const setUyariFn = format === "feed" ? setGorselFeedUyari : setGorselStoryUyari;
    setYukleniyorFn(true); setMesaj("");
    try {
      const d = await api(`/api/author/kitap/${bookId}/reklam-gorseli`, {
        method: "POST", body: JSON.stringify({
          dataUrl: gorsel.dataUrl, format, genislik: gorsel.genislik, yukseklik: gorsel.yukseklik,
        }) });
      if (!d.ok) { setMesaj(d.error || "Görsel yüklenemedi."); return; }
      setYuklendiFn(true);
      setUyariFn(d.oranUyarisi || null);
      setMesaj(d.mesaj);
      // DÜZELTİLDİ (9 Ağu 2026, gerçek bug — "yeni denetim"): önceden
      // gorselDurumu, görsel yüklendikten sonra HİÇ güncellenmiyordu — hem
      // "bu kitabın görseli yok" uyarısı hem de önizleme butonunun gizli
      // kalması devam ediyordu. Artık ilgili format için anında güncelleniyor.
      setGorselDurumu((onceki) => ({ ...(onceki || {}), [format === "feed" ? "feedVar" : "storyVar"]: true }));
    } catch { setMesaj("Sunucuya ulaşılamadı."); }
    finally { setYukleniyorFn(false); }
  };
  const gorseliYukleFeed = gorseliYukleOlustur("feed");
  const gorseliYukleStory = gorseliYukleOlustur("story");

  // Bütçe ya da süre değişince tahmini tazele — yazar yazarken sürekli
  // istek gitmesin diye yarım saniye beklenir
  useEffect(() => {
    if (!acik || !Number(butce)) { setTahmin(null); return; }
    const zamanlayici = setTimeout(async () => {
      try {
        const d = await api(`/api/author/reklam/tahmin?butce=${Number(butce)}&gun=${Number(gun) || 14}`);
        setTahmin(d);
      } catch { setTahmin(null); }
    }, 500);
    return () => clearTimeout(zamanlayici);
  }, [butce, gun, acik]);

  const gonder = async () => {
    if (calisiyor) return;
    setCalisiyor(true); setMesaj("");
    try {
      const d = await api("/api/author/reklam/kampanya", {
        method: "POST",
        body: JSON.stringify({
          bookId: Number(bookId), butce: Number(butce), gun: Number(gun), kitle, amac,
          // EKLENDİ (9 Ağu 2026, "eksiksiz denetim"): önceden bu alanlar hiç
          // gönderilmiyordu, backend her zaman varsayılana düşüyordu. Boş
          // bırakılırsa (kullanıcı doldurmadıysa) yine backend'in kendi
          // makul varsayılanı devreye girer — hiçbir şey zorunlu değil.
          reklamMetni: reklamMetni.trim() || undefined, baslik: baslik.trim() || undefined,
          aciklama: aciklama.trim() || undefined, bolge, ilgi, cta, hedefAdres,
        }),
      });
      setMesaj(d.ok ? d.mesaj : (d.error || "Gönderilemedi."));
      if (d.ok) { setAcik(false); yukle(); }
    } catch { setMesaj("Sunucuya ulaşılamadı."); }
    finally { setCalisiyor(false); }
  };

  // EKLENDİ (9 Ağu 2026, "eksiksiz denetim" — "MST yapsın" seçeneği backend'de
  // hazırdı ama formda hiç yoktu): yazar kendi kurmak istemiyorsa, uzmana
  // teklif olarak iletir — bakiyeden hiçbir şey düşülmez.
  const mstYapsinGonder = async () => {
    if (calisiyor || !bookId) return;
    setCalisiyor(true); setMesaj("");
    try {
      const d = await api("/api/author/reklam/kampanya", {
        method: "POST",
        body: JSON.stringify({ bookId: Number(bookId), butce: Number(butce) || undefined, gun: Number(gun) || undefined, mstYapsin: true }),
      });
      setMesaj(d.ok ? d.mesaj : (d.error || "Gönderilemedi."));
      if (d.ok) setAcik(false);
    } catch { setMesaj("Sunucuya ulaşılamadı."); }
    finally { setCalisiyor(false); }
  };

  // EKLENDİ (9 Ağu 2026, "eksiksiz denetim" — yazar tarafında gerçek Meta
  // önizlemesi hiç yoktu): kampanya oluşturmadan ÖNCE, Meta'nın kendi
  // render motorundan gerçek önizleme alır.
  const onizlemeGetir = async () => {
    if (!bookId || !gorselDurumu?.feedVar) return;
    setOnizlemeYukleniyor(true); setMesaj(""); setOnizlemeler(null);
    try {
      const d = await api(`/api/author/kitap/${bookId}/onizleme`, {
        method: "POST", body: JSON.stringify({ reklamMetni: reklamMetni.trim(), baslik: baslik.trim(), aciklama: aciklama.trim(), hedefAdres }),
      });
      if (!d.ok) { setMesaj(d.error || "Önizleme alınamadı."); return; }
      setOnizlemeler(d.onizlemeler);
    } catch { setMesaj("Sunucuya ulaşılamadı."); }
    finally { setOnizlemeYukleniyor(false); }
  };

  const iptal = async (id) => {
    const d = await api(`/api/author/reklam/kampanya/${id}/iptal`, { method: "POST", body: "{}" });
    setMesaj(d.ok ? d.mesaj : (d.error || "İptal edilemedi."));
    yukle();
  };

  const inputStyle = {
    padding: "12px 14px", border: "1px solid rgba(201,162,75,.28)", borderRadius: 0, fontSize: 15,
    boxSizing: "border-box", background: "rgba(255,255,255,.015)", color: THEME.textLight,
    fontFamily: "'Jost', sans-serif", width: "100%",
  };
  const etiket = { fontSize: 10.5, letterSpacing: "0.28em", color: "rgba(201,162,75,.82)", marginBottom: 7 };

  const gunluk = Number(butce) && Number(gun) ? Math.round(Number(butce) / Number(gun)) : 0;

  return (
    <div style={{ marginBottom: 34 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 16 }}>
        <span style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "clamp(18px, 5.2vw, 25px)", color: "#F0D68A", fontWeight: 600 }}>Kendi Kampanyam</span>
        <span style={{ flex: 1, height: 1, background: "linear-gradient(90deg,rgba(201,162,75,.45),transparent)" }} />
      </div>

      {liste && liste.length === 0 && <ReklamSimulasyonu books={books} />}

      <div style={{ background: "rgba(201,162,75,.04)", border: "1px solid rgba(201,162,75,.28)", padding: "18px 20px", marginBottom: 20 }}>
        <div style={{ fontSize: 14.5, color: THEME.textLight, lineHeight: 1.75, fontWeight: 300 }}>
          Kitabınızı Instagram ve Facebook'ta doğrudan tanıtın. Bütçeniz <b style={{ fontWeight: 500 }}>ayrılır,
          hemen harcanmaz</b> — kampanya bitiminde harcanmayan tutar bakiyenize iade edilir.
          Reklamınızın kaç kişiye ulaştığını, kaç tıklama aldığını ve satışınıza etkisini buradan izlersiniz.
        </div>
      </div>

      {!acik && (
        <Dugme tur="asil" onClick={() => setAcik(true)}>KİTABIMI REKLAMA AÇ</Dugme>
      )}

      {acik && (
        <div style={{ display: "grid", gap: 14, marginBottom: 24 }}>
          <div>
            <div style={etiket}>HANGİ KİTAP</div>
            <select value={bookId} onChange={(e) => setBookId(e.target.value)} style={inputStyle}>
              {books.map((b) => <option key={b.id} value={b.id}>{b.title}</option>)}
            </select>
          </div>

          {/* EKLENDİ (9 Ağu 2026): Feed (kare) ve Story (dikey) için ayrı
              görsel — Meta bunları farklı yerleşimlerde farklı gösterir,
              tek görsel otomatik kırpılırsa logo/başlık kesilebilir. */}
          <div>
            <div style={etiket}>REKLAM GÖRSELİ</div>
            <div style={{ fontSize: 12.5, color: "rgba(245,240,228,.58)", marginBottom: 10, lineHeight: 1.6, fontWeight: 300 }}>
              İsterseniz kendi görselinizi yükleyin — yüklemezseniz kitabınızın kapağı kullanılır.
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              {[
                { format: "feed", baslikMetin: "Feed (kare)", gorsel: gorselFeed, yuklendi: gorselFeedYuklendi, uyari: gorselFeedUyari, yukleniyor: gorselFeedYukleniyor, secFn: gorselSecFeed, yukleFn: gorseliYukleFeed },
                { format: "story", baslikMetin: "Story / Reels (dikey)", gorsel: gorselStory, yuklendi: gorselStoryYuklendi, uyari: gorselStoryUyari, yukleniyor: gorselStoryYukleniyor, secFn: gorselSecStory, yukleFn: gorseliYukleStory },
              ].map((g) => (
                <div key={g.format} style={{ border: "1px solid rgba(201,162,75,.28)", padding: "10px 12px", background: g.yuklendi ? "rgba(159,199,168,.06)" : "rgba(255,255,255,.015)" }}>
                  <div style={{ fontSize: 11, color: "rgba(245,240,228,.72)", marginBottom: 6 }}>{g.baslikMetin} {g.yuklendi && <span style={{ color: "#9FC7A8" }}>✓</span>}</div>
                  <input type="file" accept="image/png,image/jpeg,image/gif,image/webp" onChange={g.secFn}
                    style={{ display: "block", width: "100%", fontSize: 11, color: "rgba(245,240,228,.72)", marginBottom: g.gorsel ? 8 : 0 }} />
                  {g.gorsel && (
                    <div>
                      <img src={g.gorsel.dataUrl} alt="" style={{ width: g.format === "story" ? 40 : 56, height: 56, objectFit: "cover", border: "1px solid rgba(201,162,75,.28)" }} />
                      {g.uyari && <div style={{ fontSize: 10, color: "#E0B060", marginTop: 5, lineHeight: 1.5 }}>{g.uyari}</div>}
                      {!g.yuklendi && (
                        <button onClick={g.yukleFn} disabled={g.yukleniyor} style={{
                          display: "block", marginTop: 6, background: "none", color: "#F0D68A",
                          border: "1px solid rgba(201,162,75,.4)", padding: "6px 10px", fontSize: 10.5,
                          cursor: "pointer", fontFamily: "'Jost', sans-serif",
                        }}>{g.yukleniyor ? "Yükleniyor…" : "Kaydet"}</button>
                      )}
                    </div>
                  )}
                </div>
              ))}
            </div>
            {/* EKLENDİ (9 Ağu 2026, "eksiksiz denetim" — görsel eksikliği için
                erken uyarı): önceden yazar, kitabının hiç görseli olmadığını
                admin reddedene kadar öğrenmiyordu. */}
            {gorselDurumu && !gorselDurumu.feedVar && !gorselFeedYuklendi && (
              <div style={{ marginTop: 8, fontSize: 11.5, color: "#E0B060", lineHeight: 1.6, background: "rgba(224,176,96,.08)", padding: "8px 10px", border: "1px solid rgba(224,176,96,.3)" }}>
                Bu kitabın hiç görseli yok — yukarıdan Feed görseli yüklemezseniz kampanyanız onaya takılabilir.
              </div>
            )}
          </div>

          {/* EKLENDİ (9 Ağu 2026, "eksiksiz denetim" — form, backend'in kabul
              ettiği alanların küçük bir kısmını kullanıyordu): opsiyonel
              gelişmiş ayarlar — doldurmazsanız makul varsayılanlar kullanılır. */}
          <div>
            <button onClick={() => setGelismisAcik(!gelismisAcik)} style={{
              background: "none", border: "none", color: "rgba(201,162,75,.82)", fontSize: 11,
              letterSpacing: "0.2em", cursor: "pointer", padding: 0, fontFamily: "'Jost', sans-serif",
            }}>{gelismisAcik ? "− GELİŞMİŞ AYARLARI GİZLE" : "+ GELİŞMİŞ AYARLAR (metin, hedefleme, yönlendirme)"}</button>
          </div>
          {gelismisAcik && (
            <div style={{ display: "grid", gap: 12, padding: "14px", border: "1px solid rgba(201,162,75,.20)" }}>
              <div>
                <div style={etiket}>REKLAM METNİ (opsiyonel)</div>
                <textarea value={reklamMetni} onChange={(e) => setReklamMetni(e.target.value)} rows={2}
                  placeholder="Boş bırakırsanız kitap adınız kullanılır"
                  style={{ ...inputStyle, resize: "vertical" }} />
              </div>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
                <div>
                  <div style={etiket}>BAŞLIK (opsiyonel)</div>
                  <input value={baslik} onChange={(e) => setBaslik(e.target.value)} placeholder="Kitap adınız" style={inputStyle} />
                </div>
                <div>
                  <div style={etiket}>AÇIKLAMA (opsiyonel)</div>
                  <input value={aciklama} onChange={(e) => setAciklama(e.target.value)} placeholder="Kitabı incelemek için dokunun" style={inputStyle} />
                </div>
              </div>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
                <div>
                  <div style={etiket}>BÖLGE</div>
                  <select value={bolge} onChange={(e) => setBolge(e.target.value)} style={inputStyle}>
                    <option value="turkiye">Türkiye geneli</option>
                    <option value="buyuksehir">Büyükşehirler</option>
                    <option value="istanbul">Sadece İstanbul</option>
                    <option value="ege">Ege ve Akdeniz</option>
                  </select>
                </div>
                <div>
                  <div style={etiket}>İLGİ ALANI</div>
                  <select value={ilgi} onChange={(e) => setIlgi(e.target.value)} style={inputStyle}>
                    <option value="genel">Genel kitap okurları</option>
                    <option value="roman">Roman ve edebiyat</option>
                    <option value="kisisel">Kişisel gelişim</option>
                    <option value="tarih">Tarih ve biyografi</option>
                    <option value="cocuk">Ebeveynler ve çocuk kitapları</option>
                    <option value="siir">Şiir ve deneme</option>
                    <option value="polisiye">Polisiye ve gerilim</option>
                  </select>
                </div>
              </div>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
                <div>
                  <div style={etiket}>EYLEM ÇAĞRISI</div>
                  <select value={cta} onChange={(e) => setCta(e.target.value)} style={inputStyle}>
                    <option value="LEARN_MORE">Daha fazla bilgi</option>
                    <option value="SHOP_NOW">Hemen satın al</option>
                    <option value="ORDER_NOW">Sipariş ver</option>
                    <option value="GET_OFFER">Fırsatı gör</option>
                    <option value="SIGN_UP">Kaydol</option>
                  </select>
                </div>
                <div>
                  <div style={etiket}>YÖNLENDİRME</div>
                  <select value={hedefAdres} onChange={(e) => setHedefAdres(e.target.value)} style={inputStyle}>
                    <option value="mst_kitap">Kitabımın sayfasına</option>
                    <option value="mst_magaza">Kitap mağazasına</option>
                  </select>
                </div>
              </div>
            </div>
          )}

          <div>
            <div style={etiket}>AMAÇ</div>
            <select value={amac} onChange={(e) => setAmac(e.target.value)} style={inputStyle}>
              <option value="satis">Satış — kitabımı satın alsınlar</option>
              <option value="bilinirlik">Bilinirlik — kitabımı tanısınlar</option>
            </select>
          </div>
          <div>
            <div style={etiket}>KİMLERE GÖSTERİLSİN</div>
            <select value={kitle} onChange={(e) => setKitle(e.target.value)} style={inputStyle}>
              {kurallar && Object.entries(kurallar.kitleler).map(([k, v]) => (
                <option key={k} value={k}>{v.ad}</option>
              ))}
            </select>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
            <div>
              <div style={etiket}>BÜTÇE (₺)</div>
              <input value={butce} onChange={(e) => setButce(e.target.value.replace(/[^0-9]/g, ""))}
                style={{ ...inputStyle, fontFamily: "'Cormorant Garamond', serif", fontSize: 20 }} />
            </div>
            <div>
              <div style={etiket}>SÜRE (GÜN)</div>
              <input value={gun} onChange={(e) => setGun(e.target.value.replace(/[^0-9]/g, ""))}
                style={{ ...inputStyle, fontFamily: "'Cormorant Garamond', serif", fontSize: 20 }} />
            </div>
          </div>

          {/* Bütçe tahmini — MST'nin gerçek geçmiş performansından hesaplanır */}
          <div style={{ background: "linear-gradient(160deg, rgba(201,162,75,.07), rgba(10,20,40,.45))",
            border: "1px solid rgba(201,162,75,.30)", padding: "18px 20px" }}>
            <div style={{ fontSize: 10.5, letterSpacing: "0.28em", color: "rgba(201,162,75,.82)", marginBottom: 14 }}>
              BU BÜTÇEYLE BEKLENEN
            </div>

            {tahmin && tahmin.tahminVar ? (
              <>
                <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(105px,1fr))", gap: 16 }}>
                  {[
                    { e: "ULAŞILAN KİŞİ", a: tahmin.erisim.alt, u: tahmin.erisim.ust },
                    { e: "GÖSTERİM", a: tahmin.gosterim.alt, u: tahmin.gosterim.ust },
                    ...(tahmin.tiklama ? [{ e: "TIKLAMA", a: tahmin.tiklama.alt, u: tahmin.tiklama.ust }] : []),
                  ].map((x) => (
                    <div key={x.e}>
                      <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 21, fontWeight: 600, lineHeight: 1.2,
                        background: THEME.altinMetin, WebkitBackgroundClip: "text", backgroundClip: "text", WebkitTextFillColor: "transparent" }}>
                        {x.a.toLocaleString("tr-TR")}–{x.u.toLocaleString("tr-TR")}
                      </div>
                      <div style={{ fontSize: 9.5, letterSpacing: "0.2em", color: "rgba(201,162,75,.75)", marginTop: 4 }}>{x.e}</div>
                    </div>
                  ))}
                </div>
                <div style={{ fontSize: 13, color: "rgba(245,240,228,.72)", marginTop: 14, lineHeight: 1.7, fontWeight: 300 }}>
                  Günlük yaklaşık <b style={{ color: "#F0D68A", fontWeight: 500 }}>{tahmin.gunluk} ₺</b> harcanır.
                  {tahmin.tiklamaMaliyeti ? ` Tıklama başına ortalama ${tahmin.tiklamaMaliyeti} ₺.` : ""}
                </div>
                <div style={{ fontSize: 12, color: "rgba(245,240,228,.52)", marginTop: 10, lineHeight: 1.65, fontWeight: 300 }}>
                  {tahmin.uyari}
                </div>
              </>
            ) : (
              <div style={{ fontSize: 13.5, color: "rgba(245,240,228,.72)", lineHeight: 1.7, fontWeight: 300 }}>
                Günlük yaklaşık <b style={{ color: "#F0D68A", fontWeight: 500 }}>{gunluk} ₺</b> harcanır.
                {tahmin?.mesaj ? " " + tahmin.mesaj : ""} En az {kurallar?.butceMin || 1000} ₺ öneriyoruz —
                daha düşük bütçeler yeterli veriye ulaşamadan tükeniyor. Reklam satış garantisi değildir.
              </div>
            )}
          </div>

          {/* EKLENDİ (9 Ağu 2026, "eksiksiz denetim" — yazar tarafında gerçek
              önizleme hiç yoktu): kampanya oluşturmadan ÖNCE Meta'nın kendi
              render motorundan gerçek önizleme. */}
          {gorselDurumu?.feedVar && (
            <div>
              <button onClick={onizlemeGetir} disabled={onizlemeYukleniyor} style={{
                background: "none", color: "rgba(245,240,228,.72)", border: "1px solid rgba(201,162,75,.28)",
                padding: "10px 16px", fontSize: 12.5, cursor: "pointer", fontFamily: "'Jost', sans-serif",
              }}>{onizlemeYukleniyor ? "Meta'dan önizleme isteniyor…" : "Yayınlamadan önce gerçek önizlemeyi gör"}</button>
              {onizlemeler && (
                <div style={{ display: "grid", gridTemplateColumns: onizlemeler.story ? "1fr 1fr" : "1fr", gap: 10, marginTop: 10 }}>
                  {onizlemeler.feed && (
                    <div>
                      <div style={{ fontSize: 10, color: "rgba(245,240,228,.52)", marginBottom: 4 }}>AKIŞTA BÖYLE GÖRÜNECEK</div>
                      <div style={{ border: "1px solid rgba(201,162,75,.28)", maxHeight: 380, overflowY: "auto" }}
                        dangerouslySetInnerHTML={{ __html: onizlemeler.feed }} />
                    </div>
                  )}
                  {onizlemeler.story && (
                    <div>
                      <div style={{ fontSize: 10, color: "rgba(245,240,228,.52)", marginBottom: 4 }}>HİKAYEDE BÖYLE GÖRÜNECEK</div>
                      <div style={{ border: "1px solid rgba(201,162,75,.28)", maxHeight: 380, overflowY: "auto" }}
                        dangerouslySetInnerHTML={{ __html: onizlemeler.story }} />
                    </div>
                  )}
                </div>
              )}
            </div>
          )}

          <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
            <Dugme tur="asil" onClick={gonder} disabled={calisiyor || !bookId}>{calisiyor ? "GÖNDERİLİYOR..." : "KAMPANYAYI BAŞLAT"}</Dugme>
            <button onClick={mstYapsinGonder} disabled={calisiyor || !bookId} style={{
              background: "none", color: "rgba(245,240,228,.62)", border: "1px solid rgba(201,162,75,.28)",
              padding: "13px 18px", fontSize: 13, cursor: "pointer", fontFamily: "'Jost', sans-serif",
            }}>Kurmak istemiyorum, MST yapsın</button>
            <button onClick={() => setAcik(false)} style={{
              background: "none", color: "rgba(245,240,228,.62)", border: "1px solid rgba(201,162,75,.28)",
              padding: "13px 20px", fontSize: 14, cursor: "pointer", fontFamily: "'Jost', sans-serif",
            }}>Vazgeç</button>
          </div>
        </div>
      )}

      {mesaj && <div style={{ fontSize: 14, color: "#F0D68A", marginBottom: 18, lineHeight: 1.7 }}>{mesaj}</div>}

      {liste && liste.length > 0 && (
        <div style={{ display: "grid", gap: 2, background: "rgba(201,162,75,.16)", border: "1px solid rgba(201,162,75,.24)" }}>
          {liste.map((k) => {
            const d = KAMPANYA_DURUM[k.durum] || KAMPANYA_DURUM.onay_bekliyor;
            return (
              <div key={k.id} style={{ background: "rgba(12,23,48,.55)", padding: "22px 24px" }}>
                <div style={{ display: "flex", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
                  <div>
                    <div style={{ fontSize: 15, color: THEME.textLight, fontWeight: 500 }}>{k.kitap}</div>
                    <div style={{ fontSize: 13, color: "rgba(245,240,228,.62)", marginTop: 4, fontWeight: 300 }}>
                      {k.hedefKitle} · {k.gun} gün · {k.butce} ₺
                    </div>
                  </div>
                  <div style={{ fontSize: 10.5, letterSpacing: "0.16em", color: d.renk, border: `1px solid ${d.renk}`, padding: "4px 10px", height: "fit-content" }}>
                    {d.ad.toLocaleUpperCase("tr-TR")}
                  </div>
                </div>
                {/* DÜZELTİLDİ (9 Ağu 2026, gerçek bug — "yeni denetim"): "onaylandı"
                    durumu iki farklı gerçeği kapsıyordu — normal yayına hazırlanma VE
                    Meta kurulumunun başarısız olup takılı kalması (red_sebebi alanında
                    gerçek hata saklı ama önceden sadece "reddedildi" durumunda
                    gösteriliyordu, yazar hiç öğrenemiyordu). Artık ikisi ayrılıyor. */}
                {d.not && !(k.durum === "onaylandi" && k.redSebebi) && (
                  <div style={{ fontSize: 13, color: "rgba(245,240,228,.58)", marginTop: 8, fontWeight: 300 }}>{d.not}</div>
                )}
                {k.redSebebi && k.durum === "reddedildi" && (
                  <div style={{ fontSize: 13, color: "#E09080", marginTop: 8, fontWeight: 300 }}>Sebep: {k.redSebebi}</div>
                )}
                {k.redSebebi && k.durum === "onaylandi" && (
                  <div style={{ fontSize: 13, color: "#E0B060", marginTop: 8, fontWeight: 300, lineHeight: 1.6 }}>
                    Onaylandı ama yayına giremedi: {k.redSebebi} — MST ekibiyle iletişime geçin.
                  </div>
                )}

                {k.durum === "yayinda" ? (
                  <KampanyaKokpit kampanyaId={k.id} token={token} yenilemeTetigi={kokpitYenile[k.id] || 0} />
                ) : (k.harcanan > 0 || k.erisim > 0) && (
                  <div style={{ marginTop: 16, borderTop: "1px solid rgba(201,162,75,.20)", paddingTop: 14 }}>
                    <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(90px,1fr))", gap: 14 }}>
                      {[
                        { e: "ULAŞILAN KİŞİ", v: k.erisim.toLocaleString("tr-TR") },
                        { e: "TIKLAMA", v: k.tiklama.toLocaleString("tr-TR") },
                        { e: "HARCANAN", v: k.harcanan + " ₺" },
                        { e: "KALAN", v: k.kalan + " ₺" },
                      ].map((x) => (
                        <div key={x.e}>
                          <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 22, fontWeight: 600,
                            background: THEME.altinMetin, WebkitBackgroundClip: "text", backgroundClip: "text", WebkitTextFillColor: "transparent" }}>{x.v}</div>
                          <div style={{ fontSize: 9.5, letterSpacing: "0.2em", color: "rgba(201,162,75,.75)", marginTop: 3 }}>{x.e}</div>
                        </div>
                      ))}
                    </div>
                    {k.tiklamaMaliyeti != null && (
                      <div style={{ fontSize: 13, color: "rgba(245,240,228,.62)", marginTop: 12, fontWeight: 300 }}>
                        Tıklama başına {k.tiklamaMaliyeti} ₺
                      </div>
                    )}
                    {k.satisFarki != null && (
                      <div style={{ fontSize: 14, color: k.satisFarki > 0 ? "#9FC7A8" : "rgba(245,240,228,.62)", marginTop: 8, fontWeight: 300 }}>
                        Kampanya başladığından beri satış: {k.satisOncesi} → {k.satisSonrasi}
                        {k.satisFarki > 0 ? ` (+${k.satisFarki})` : ""}
                      </div>
                    )}
                  </div>
                )}

                {k.durum === "yayinda" && <KampanyaOnerileri kampanyaId={k.id} token={token} onUygulandi={() => { yukle(); setKokpitYenile((onceki) => ({ ...onceki, [k.id]: (onceki[k.id] || 0) + 1 })); }} />}

                {["onay_bekliyor", "onaylandi"].includes(k.durum) && (
                  <button onClick={() => iptal(k.id)} style={{
                    marginTop: 14, background: "none", color: "rgba(245,240,228,.62)",
                    border: "1px solid rgba(201,162,75,.28)", padding: "9px 16px", fontSize: 13,
                    cursor: "pointer", fontFamily: "'Jost', sans-serif",
                  }}>İptal et ve bütçemi geri al</button>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

const TEKLIF_GORUNUM = {
  basvuru:      { ad: "Başvurunuz alındı",   renk: "#C9A24B", aciklama: "Ekibimiz teklifinizi hazırlıyor." },
  teklif_hazir: { ad: "Teklifiniz hazır",     renk: "#F0D68A", aciklama: "İnceleyip onaylayabilirsiniz." },
  onaylandi:    { ad: "Onayladınız",          renk: "#9FC7A8", aciklama: "Başlangıç için sizinle iletişime geçilecek." },
  yurutuluyor:  { ad: "Yürütülüyor",          renk: "#9FC7A8", aciklama: "Çalışma devam ediyor." },
  tamamlandi:   { ad: "Tamamlandı",           renk: "rgba(245,240,228,.62)", aciklama: "" },
  reddedildi:   { ad: "Reddettiniz",          renk: "rgba(245,240,228,.48)", aciklama: "" },
  iptal:        { ad: "İptal edildi",         renk: "rgba(245,240,228,.48)", aciklama: "" },
};

function AdSection({ books, token, onRefresh }) {
  const [teklifler, setTeklifler] = useState(null);
  const [mesaj, setMesaj] = useState("");

  const api = async (yol, ayar = {}) => {
    const r = await fetch(`${BACKEND_URL}${yol}`, {
      ...ayar,
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}`, ...(ayar.headers || {}) },
    });
    return r.json();
  };

  const yukle = async () => {
    try { const d = await api("/api/author/reklam-tekliflerim"); setTeklifler(d.teklifler || []); }
    catch { setTeklifler([]); }
  };
  useEffect(() => { yukle(); }, []);

  const karar = async (id, k) => {
    const d = await api(`/api/author/reklam-teklif/${id}/karar`, { method: "POST", body: JSON.stringify({ karar: k }) });
    setMesaj(d.ok ? d.mesaj : (d.error || "İşlem yapılamadı."));
    yukle();
  };

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 16 }}>
        <span style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "clamp(18px, 5.2vw, 25px)", color: "#F0D68A", fontWeight: 600 }}>Reklam &amp; Tanıtım</span>
        <span style={{ flex: 1, height: 1, background: "linear-gradient(90deg,rgba(201,162,75,.45),transparent)" }} />
      </div>

      <KendiKampanyam books={books} token={token} />

      <ReklamEgitimi />

      {mesaj && <div style={{ fontSize: 14, color: "#F0D68A", marginBottom: 20, lineHeight: 1.7 }}>{mesaj}</div>}

      {/* Başvuru ve teklif geçmişi */}
      {teklifler && teklifler.length > 0 && (
        <>
          <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 16, marginTop: 34 }}>
            <span style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "clamp(18px, 5.2vw, 25px)", color: "#F0D68A", fontWeight: 600 }}>Başvurularınız</span>
            <span style={{ flex: 1, height: 1, background: "linear-gradient(90deg,rgba(201,162,75,.45),transparent)" }} />
          </div>
          <div style={{ display: "grid", gap: 2, background: "rgba(201,162,75,.16)", border: "1px solid rgba(201,162,75,.24)" }}>
            {teklifler.map((t) => {
              const g = TEKLIF_GORUNUM[t.durum] || TEKLIF_GORUNUM.basvuru;
              const kalemler = Array.isArray(t.kalemler) ? t.kalemler : [];
              return (
                <div key={t.id} style={{ background: "rgba(12,23,48,.55)", padding: "22px 24px" }}>
                  <div style={{ display: "flex", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
                    <div style={{ minWidth: 0, flex: 1 }}>
                      {t.kitap && <div style={{ fontSize: 15, color: THEME.textLight, fontWeight: 500 }}>{t.kitap}</div>}
                      <div style={{ fontSize: 14, color: "rgba(245,240,228,.72)", marginTop: 5, lineHeight: 1.7, fontWeight: 300 }}>{t.hedef}</div>
                    </div>
                    <div style={{ fontSize: 10.5, letterSpacing: "0.16em", color: g.renk, border: `1px solid ${g.renk}`, padding: "4px 10px", height: "fit-content", whiteSpace: "nowrap" }}>
                      {g.ad.toLocaleUpperCase("tr-TR")}
                    </div>
                  </div>
                  {g.aciklama && <div style={{ fontSize: 13, color: "rgba(245,240,228,.58)", marginTop: 8, fontWeight: 300 }}>{g.aciklama}</div>}

                  {kalemler.length > 0 && (
                    <div style={{ marginTop: 16, borderTop: "1px solid rgba(201,162,75,.20)", paddingTop: 14 }}>
                      <div style={{ fontSize: 10.5, letterSpacing: "0.28em", color: "rgba(201,162,75,.82)", marginBottom: 10 }}>TEKLİF</div>
                      {kalemler.map((k, i) => (
                        <div key={i} style={{ display: "flex", justifyContent: "space-between", gap: 12, fontSize: 14, marginBottom: 8 }}>
                          <div style={{ minWidth: 0 }}>
                            <div style={{ color: THEME.textLight }}>{k.ad}</div>
                            {k.aciklama && <div style={{ fontSize: 12.5, color: "rgba(245,240,228,.52)", fontWeight: 300 }}>{k.aciklama}</div>}
                          </div>
                          <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 18, color: "#F0D68A", whiteSpace: "nowrap" }}>
                            {Number(k.tutar).toLocaleString("tr-TR")} ₺
                          </div>
                        </div>
                      ))}
                      <div style={{ display: "flex", justifyContent: "space-between", borderTop: "1px solid rgba(201,162,75,.20)", paddingTop: 10, marginTop: 10 }}>
                        <span style={{ fontSize: 14, color: THEME.textLight }}>Toplam</span>
                        <span style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 26, fontWeight: 600,
                          background: THEME.altinMetin, WebkitBackgroundClip: "text", backgroundClip: "text", WebkitTextFillColor: "transparent" }}>
                          {Number(t.toplam).toLocaleString("tr-TR")} ₺
                        </span>
                      </div>
                      {t.teklif_notu && <div style={{ fontSize: 13.5, color: "rgba(245,240,228,.62)", marginTop: 12, lineHeight: 1.7, fontWeight: 300 }}>{t.teklif_notu}</div>}
                      {t.gecerlilik && <div style={{ fontSize: 12, color: "rgba(245,240,228,.48)", marginTop: 8 }}>Geçerlilik: {new Date(t.gecerlilik).toLocaleDateString("tr-TR")}</div>}

                      {t.durum === "teklif_hazir" && (
                        <div style={{ display: "flex", gap: 10, marginTop: 14 }}>
                          <Dugme tur="asil" onClick={() => karar(t.id, "onayla")}>ONAYLIYORUM</Dugme>
                          <button onClick={() => karar(t.id, "reddet")} style={{
                            background: "none", color: "rgba(245,240,228,.62)", border: "1px solid rgba(201,162,75,.28)",
                            padding: "11px 18px", fontSize: 13.5, cursor: "pointer", fontFamily: "'Jost', sans-serif",
                          }}>Şimdilik hayır</button>
                        </div>
                      )}
                    </div>
                  )}

                  {t.rapor_metni && (
                    <div style={{ marginTop: 16, background: "rgba(201,162,75,.04)", border: "1px solid rgba(201,162,75,.24)", padding: "14px 16px" }}>
                      <div style={{ fontSize: 10.5, letterSpacing: "0.28em", color: "rgba(201,162,75,.82)", marginBottom: 8 }}>SONUÇ RAPORU</div>
                      <div style={{ fontSize: 14, color: THEME.textLight, lineHeight: 1.75, fontWeight: 300, whiteSpace: "pre-wrap" }}>{t.rapor_metni}</div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </>
      )}
    </div>
  );
}

function ExtrasSection({ books, requests, onSubmit }) {
  const [bookId, setBookId] = useState(books[0]?.id || "");
  const [language, setLanguage] = useState(LANGUAGES[0]);
  const selectedBook = books.find((b) => b.id === bookId);
  const quotaUsed = selectedBook ? selectedBook.translationsUsed >= selectedBook.translationQuota : false;
  const submit = (e) => { e.preventDefault(); if (!selectedBook || quotaUsed) return; onSubmit({ bookId: selectedBook.id, bookTitle: selectedBook.title, language }); };
  const inputStyle = { padding: "9px 11px", border: `1px solid ${THEME.border}`, borderRadius: 0, fontSize: 16, boxSizing: "border-box", background: THEME.yuzeyDik, color: THEME.textLight };
  return (
    <div>
      <div style={{ background: `linear-gradient(135deg, ${THEME.headerGradA} 0%, ${THEME.headerGradB} 100%)`, border: `1px solid ${THEME.vipBorder}`, borderRadius: 0, padding: "16px 18px", marginBottom: 18, color: THEME.textLight }}>
        <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 15, color: THEME.vip }}>✦ VIP Ek Hizmetler</div>
        <div style={{ fontSize: 14, color: THEME.textMuted, marginTop: 4, lineHeight: 1.6 }}>Kitaplarınız otomatik olarak Amazon üzerinden dünyaya açılır. Her kitap için 1 dile çeviri hakkınız bulunur.</div>
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 16, marginTop: 34 }}><span style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "clamp(18px, 5.2vw, 25px)", color: "#F0D68A", fontWeight: 600 }}>Kitap çeviri hakları</span><span style={{ flex: 1, height: 1, background: "linear-gradient(90deg,rgba(201,162,75,.45),transparent)" }} /></div>
      <div style={{ marginBottom: 18 }}>{books.map((b) => (<div key={b.id} style={{ display: "flex", justifyContent: "space-between", fontSize: 14.5, padding: "6px 0", borderBottom: `1px solid ${THEME.divider}`, color: THEME.textLight }}><span>{b.title}</span><span style={{ color: b.translationsUsed >= b.translationQuota ? THEME.danger : THEME.success }}>{b.translationsUsed}/{b.translationQuota} kullanıldı</span></div>))}</div>
      <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 16, marginTop: 34 }}><span style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "clamp(18px, 5.2vw, 25px)", color: "#F0D68A", fontWeight: 600 }}>Çeviri talebi oluştur</span><span style={{ flex: 1, height: 1, background: "linear-gradient(90deg,rgba(201,162,75,.45),transparent)" }} /></div>
      <form onSubmit={submit} style={{ background: THEME.yuzey, border: `1px solid ${THEME.vipBorder}`, borderRadius: 0, padding: 14, display: "flex", flexDirection: "column", gap: 10, marginBottom: 18 }}>
        <select value={bookId} onChange={(e) => setBookId(e.target.value)} style={inputStyle}>{books.map((b) => <option key={b.id} value={b.id}>{b.title}</option>)}</select>
        <select value={language} onChange={(e) => setLanguage(e.target.value)} style={inputStyle}>{LANGUAGES.map((l) => <option key={l} value={l}>{l}</option>)}</select>
        {quotaUsed && <div style={{ fontSize: 14, color: THEME.danger }}>Bu kitap için çeviri hakkınızı kullandınız. Ek hak için yayınevi ile iletişime geçin.</div>}
        <button type="submit" disabled={quotaUsed} style={{ background: quotaUsed ? THEME.disabledBg : THEME.vip, color: quotaUsed ? THEME.disabledFg : "#140A22", border: "none", borderRadius: 0, padding: "10px 0", fontSize: 14.5, cursor: quotaUsed ? "not-allowed" : "pointer", fontWeight: 600 }}>Çeviri Talebini Gönder</button>
      </form>
      <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 16, marginTop: 34 }}><span style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "clamp(18px, 5.2vw, 25px)", color: "#F0D68A", fontWeight: 600 }}>Taleplerim</span><span style={{ flex: 1, height: 1, background: "linear-gradient(90deg,rgba(201,162,75,.45),transparent)" }} /></div>
      {requests.length === 0 && <div style={{ fontSize: 14.5, color: THEME.textMuted }}>Henüz çeviri talebi oluşturmadınız.</div>}
      {requests.map((r) => (<div key={r.id} style={{ background: THEME.yuzey, border: `1px solid ${THEME.border}`, borderRadius: 0, padding: "12px 14px", marginBottom: 8 }}><div style={{ display: "flex", justifyContent: "space-between" }}><span style={{ fontSize: 15, color: THEME.textLight }}>{r.bookTitle} → {r.language}</span><span style={{ fontSize: 14, color: r.status === "devam" ? THEME.warn : THEME.success }}>{r.status === "devam" ? "Devam ediyor" : "Tamamlandı"}</span></div></div>))}
    </div>
  );
}

// ---- Mağaza (Store) ----
function ServiceCard({ service, books, wallet, onOrder, expanded, onToggle, ordersForService }) {
  const [bookId, setBookId] = useState(books[0]?.id || "");
  const [pages, setPages] = useState(200);
  const [tierKey, setTierKey] = useState(service.tiers?.[0]?.key);
  const [fairKey, setFairKey] = useState(FAIRS[0].key);
  const [note, setNote] = useState("");
  const [error, setError] = useState("");
  const inputStyle = { width: "100%", padding: "9px 11px", border: `1px solid ${THEME.border}`, borderRadius: 0, fontSize: 16, background: THEME.yuzeyDik, color: THEME.textLight, marginBottom: 8, boxSizing: "border-box" };

  let price = null;
  if (service.pricing === "fixed") price = service.price;
  if (service.pricing === "tiers") price = service.tiers.find((t) => t.key === tierKey)?.price;
  if (service.pricing === "per-page") price = Math.round(Number(pages) * WORDS_PER_PAGE * SELL_PRICE_PER_WORD);
  if (service.pricing === "fairs") { const f = FAIRS.find((x) => x.key === fairKey); price = f ? Math.round((f.katilim + f.stand) * (1 + EVENT_SERVICE_MARGIN)) : null; }

  const handleAction = () => {
    const book = books.find((b) => b.id === bookId);
    if (service.pricing === "info") { onOrder({ serviceKey: service.key, title: service.title, bookTitle: book?.title, detail: note || undefined, price: null, status: "İnceleniyor" }); setNote(""); return; }
    if (price > wallet.balance) { setError("Yetersiz bakiye — önce ödeme bildirimi oluşturup yayınevi onayını bekleyin."); return; }
    setError("");
    let detail = service.title;
    if (service.pricing === "tiers") detail = service.tiers.find((t) => t.key === tierKey)?.label;
    if (service.pricing === "fairs") { const f = FAIRS.find((x) => x.key === fairKey); detail = f?.name; }
    if (service.pricing === "per-page") detail = `${pages} sayfa → ${Math.round(pages * WORDS_PER_PAGE).toLocaleString("tr-TR")} kelime`;
    onOrder({ serviceKey: service.key, title: service.title, bookTitle: book?.title, detail, price, status: "Onay bekliyor" });
  };

  return (
    <div style={{ background: THEME.yuzey, border: `1px solid ${THEME.border}`, borderRadius: 0, marginBottom: 12, overflow: "hidden" }}>
      <button onClick={onToggle} style={{ width: "100%", display: "flex", alignItems: "center", gap: 12, padding: "14px 16px", background: "none", border: "none", cursor: "pointer", textAlign: "left" }}>
        <div style={{ fontSize: 24 }}>{service.icon}</div>
        <div style={{ flex: 1 }}>
          <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 15, color: THEME.textLight }}>{service.title}</div>
          <div style={{ fontSize: 15, color: THEME.textMuted, marginTop: 2 }}>{service.desc}</div>
        </div>
        <div style={{ fontSize: 16, color: THEME.cyan }}>{expanded ? "–" : "+"}</div>
      </button>
      {expanded && (
        <div style={{ padding: "0 16px 16px" }}>
          {service.pricing === "fixed" && <div style={{ fontSize: 15, color: THEME.textLight, marginBottom: 10 }}>Fiyat: <strong style={{ color: THEME.cyan }}>{tl(service.price)}</strong> ({service.period})</div>}
          {service.pricing !== "fixed" && service.pricing !== "info" && books.length > 0 && (
            <select value={bookId} onChange={(e) => setBookId(e.target.value)} style={inputStyle}>{books.map((b) => <option key={b.id} value={b.id}>{b.title}</option>)}</select>
          )}
          {service.pricing === "per-page" && (
            <label style={{ fontSize: 15, color: THEME.textMuted, display: "block", marginBottom: 8 }}>Kitabın sayfa sayısı
              <input type="number" min={10} value={pages} onChange={(e) => setPages(e.target.value)} style={{ display: "block", marginTop: 4, ...inputStyle }} />
            </label>
          )}
          {service.pricing === "tiers" && (
            <select value={tierKey} onChange={(e) => setTierKey(e.target.value)} style={inputStyle}>{service.tiers.map((t) => <option key={t.key} value={t.key}>{t.label} — {tl(t.price)}</option>)}</select>
          )}
          {service.pricing === "fairs" && (
            <select value={fairKey} onChange={(e) => setFairKey(e.target.value)} style={inputStyle}>{FAIRS.map((f) => <option key={f.key} value={f.key}>{f.name} — {formatDate(f.date)}</option>)}</select>
          )}
          {service.pricing === "info" && (
            <>
              <div style={{ fontSize: 14, color: THEME.warn, background: THEME.warnBg, borderRadius: 0, padding: "8px 10px", marginBottom: 8 }}>{service.infoNote}</div>
              <textarea value={note} onChange={(e) => setNote(e.target.value)} placeholder="Senaryo fikri / kısa not (opsiyonel)" rows={2} style={{ ...inputStyle, resize: "vertical", fontFamily: "inherit" }} />
            </>
          )}
          {price !== null && service.pricing !== "info" && <div style={{ fontSize: 15, color: THEME.textLight, marginBottom: 8 }}>Toplam: <strong style={{ color: THEME.cyan }}>{tl(price)}</strong></div>}
          {error && <div style={{ color: THEME.danger, fontSize: 14, marginBottom: 8 }}>{error}</div>}
          <Dugme tur="asil" onClick={handleAction}>{service.pricing === "info" ? "Başvuru Gönder" : "Satın Al"}</Dugme>

          {ordersForService.length > 0 && (
            <div style={{ marginTop: 14 }}>
              <div style={{ fontSize: 15, letterSpacing: "0.05em", color: THEME.textMuted, marginBottom: 6 }}>SİPARİŞLERİM</div>
              {ordersForService.map((o) => (
                <div key={o.id} style={{ display: "flex", justifyContent: "space-between", fontSize: 14, padding: "6px 0", borderBottom: `1px solid ${THEME.divider}`, color: THEME.textLight }}>
                  <span>{o.detail || o.bookTitle || o.title}</span>
                  <span style={{ color: o.status === "Tamamlandı" ? THEME.success : THEME.warn }}>{o.status}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function StoreSection({ plan, books, wallet, notices, orders, onOrder, onSubmitNotice, token }) {
  const [openKey, setOpenKey] = useState(null);
  const available = SERVICES.filter((s) => s.plans.includes(plan));
  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 16, marginTop: 34 }}><span style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "clamp(18px, 5.2vw, 25px)", color: "#F0D68A", fontWeight: 600 }}>Yazar mağazası · kariyerinizi büyütecek hizmetler</span><span style={{ flex: 1, height: 1, background: "linear-gradient(90deg,rgba(201,162,75,.45),transparent)" }} /></div>
      <PaymentNotice wallet={wallet} notices={notices} onSubmit={onSubmitNotice} label="HİZMET BAKİYESİ" token={token} />
      {available.map((s) => (
        <ServiceCard key={s.key} service={s} books={books} wallet={wallet} onOrder={onOrder} expanded={openKey === s.key} onToggle={() => setOpenKey(openKey === s.key ? null : s.key)} ordersForService={orders.filter((o) => o.serviceKey === s.key)} />
      ))}
    </div>
  );
}

function EarningsSection({ account }) {
  // Yeni telif modeli: backend book.telif (kâr marjı üzerinden, kilitli/çekilebilir).
  // Gerçek veri gelmeden önce (telif yoksa) eski basit hesaba düş.
  const hasReal = account.books.some((b) => b.telif && b.telif.toplamAdet != null);
  const earningsByBook = account.books.map((b) => {
    if (b.telif && b.telif.toplamAdet != null) {
      return { title: b.title, earned: b.telif.toplamTelif, cekilebilir: b.telif.cekilebilir, kilitli: b.telif.kilitli };
    }
    const e = Math.round(b.totalSold * b.salePrice * account.royaltyRate);
    return { title: b.title, earned: e, cekilebilir: 0, kilitli: e };
  });
  const totalEarned = earningsByBook.reduce((s, b) => s + b.earned, 0);
  const totalCekilebilir = earningsByBook.reduce((s, b) => s + (b.cekilebilir || 0), 0);
  const totalKilitli = earningsByBook.reduce((s, b) => s + (b.kilitli || 0), 0);
  const totalPaid = (account.payouts || []).reduce((s, p) => s + (Number(p?.amount) || 0), 0);
  const pending = Math.max(0, totalCekilebilir - totalPaid);
  const mstOran = account.paketKurali ? Math.round(account.paketKurali.telifMst * 100) : Math.round(account.royaltyRate * 100);
  const digerOran = account.paketKurali ? Math.round(account.paketKurali.telifDiger * 100) : Math.round(account.royaltyRate * 100);
  return (
    <div>
      {/* Telif levhası — sitedeki .rtop deseni: dört hücre, aralarında altın saç teli */}
      <div style={{
        display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(160px, 1fr))", gap: 1,
        background: "rgba(201,162,75,.22)", border: "1px solid rgba(201,162,75,.30)", marginBottom: 56,
      }}>
        {[
          { deger: `%${mstOran}`, etiket: "TELİF ORANI", alt: `MST sitesi · diğer sitelerde %${digerOran}` },
          { deger: tl(pending), etiket: "ÇEKİLEBİLİR", alt: "Şu an talep edilebilir" },
          { deger: tl(totalKilitli), etiket: "KİLİTLİ TELİF", alt: "Stok tükenince açılır" },
          { deger: formatDate(account.nextPayoutDate), etiket: "SONRAKİ ÖDEME", alt: "Planlanan tarih", kucuk: true },
        ].map((k) => (
          <div key={k.etiket} style={{ background: "rgba(12,23,48,.62)", padding: "clamp(22px, 5vw, 34px) clamp(14px, 3vw, 26px)", textAlign: "center" }}>
            <div style={{
              fontFamily: "'Cormorant Garamond', serif", fontSize: k.kucuk ? "clamp(19px, 4vw, 26px)" : "clamp(30px, 6vw, 44px)", fontWeight: 600, lineHeight: 1,
              background: THEME.altinMetin, WebkitBackgroundClip: "text", backgroundClip: "text", WebkitTextFillColor: "transparent",
            }}>{k.deger}</div>
            <div style={{ fontSize: 10.5, letterSpacing: "0.28em", color: "rgba(201,162,75,.82)", fontWeight: 600, margin: "11px 0 9px" }}>{k.etiket}</div>
            <div style={{ fontSize: 13.5, color: "rgba(245,240,228,.70)", fontWeight: 300, lineHeight: 1.6 }}>{k.alt}</div>
          </div>
        ))}
      </div>

      <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 16 }}>
        <span style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "clamp(18px, 5.2vw, 25px)", color: "#F0D68A", fontWeight: 600 }}>Kitap Başına Telif (yaşam boyu)</span>
        <span style={{ flex: 1, height: 1, background: "linear-gradient(90deg,rgba(201,162,75,.45),transparent)" }} />
      </div>
      <div style={{ background: THEME.yuzey, border: `1px solid ${THEME.border}`, borderRadius: 0, padding: "4px 14px", marginBottom: 18 }}>
        {earningsByBook.map((b, i) => (
          <div key={i} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", fontSize: 15, padding: "10px 0", borderBottom: i < earningsByBook.length - 1 ? `1px solid ${THEME.divider}` : "none", color: THEME.textLight }}>
            <span>{b.title}</span>
            <span style={{ display: "flex", gap: 12, alignItems: "center" }}>
              {hasReal && b.kilitli > 0 && <span style={{ fontSize: 14, color: THEME.warn, fontFamily: "'Cormorant Garamond', serif" }}>🔒 {tl(b.kilitli)}</span>}
              <span style={{ fontFamily: "'Cormorant Garamond', serif", color: THEME.cyan }}>{tl(b.earned)}</span>
            </span>
          </div>
        ))}
        <div style={{ display: "flex", justifyContent: "space-between", fontSize: 15, padding: "10px 0", fontWeight: 600, color: THEME.textLight }}><span>Toplam</span><span style={{ fontFamily: "'Cormorant Garamond', serif", color: THEME.cyan }}>{tl(totalEarned)}</span></div>
      </div>

      <div style={{ fontSize: 14, letterSpacing: "0.05em", color: THEME.textMuted, marginBottom: 4 }}>ÖDEME GEÇMİŞİ</div>
      <div style={{ fontSize: 15, color: THEME.success, marginBottom: 10 }}>✓ Her ödeme tam ve açıktır — gizli kesinti veya komisyon yoktur.</div>
      {!(account.payouts || []).length ? <div style={{ fontSize: 14.5, color: THEME.textMuted }}>Henüz ödeme yapılmadı.</div> : (account.payouts || []).map((p) => (
        <div key={p.id} style={{ display: "flex", justifyContent: "space-between", fontSize: 15, padding: "8px 0", borderBottom: `1px solid ${THEME.divider}`, color: THEME.textLight }}>
          <span>{formatDate(p.date)}</span><span style={{ fontFamily: "'Cormorant Garamond', serif", color: THEME.success }}>{tl(p.amount)}</span>
        </div>
      ))}
      <div style={{ marginTop: 14, fontSize: 14.5, color: THEME.textMuted, lineHeight: 1.6 }}>
        Telif, <b>kâr marjı</b> üzerinden hesaplanır (etiket − baskı maliyeti − pazaryeri komisyonu). MST sitesi satışlarında %{mstOran}, diğer sitelerde %{digerOran}.
        Telif kazanılır ancak o kitabın baskı stoğu tükenene kadar <b style={{ color: THEME.warn }}>kilitli</b> kalır; stok bitince çekilebilir.
      </div>

      {/* HAK GÜVENCESİ ROZETİ (Hamle 3: Radikal Şeffaflık) */}
      <div style={{ background: "linear-gradient(135deg, rgba(201,162,75,.06), rgba(201,162,75,.06))", border: `1px solid ${THEME.success}`, borderRadius: 0, padding: 16, marginTop: 20, display: "flex", gap: 14, alignItems: "flex-start" }}>
        <div style={{ fontSize: 32, flexShrink: 0 }}>🛡️</div>
        <div>
          <div style={{ fontSize: 14, fontWeight: 700, color: THEME.success, fontFamily: "'Cormorant Garamond',serif", marginBottom: 4 }}>Hak Güvencesi</div>
          <div style={{ fontSize: 14, color: THEME.textLight, lineHeight: 1.55 }}>
            Kitabının tüm hakları <b>%100 sana aittir.</b> MST, eserini yayınlar ve dağıtır; hiçbir zaman haklarını devralmaz, formatını değiştirmeye zorlamaz. İstediğin an eserini başka yerde de değerlendirebilirsin. Şeffaf ve açık — gizli madde yok.
          </div>
        </div>
      </div>

      {/* MST vs DİĞERLERİ TELİF KARŞILAŞTIRMASI */}
      <div style={{ marginTop: 20 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 16 }}>
        <span style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "clamp(18px, 5.2vw, 25px)", color: "#F0D68A", fontWeight: 600 }}>Telif Oranı Karşılaştırması</span>
        <span style={{ flex: 1, height: 1, background: "linear-gradient(90deg,rgba(201,162,75,.45),transparent)" }} />
      </div>
        <div style={{ background: THEME.yuzey, border: `1px solid ${THEME.border}`, borderRadius: 0, overflow: "hidden" }}>
          {[
            { yer: "MST Yayıncılık (senin oranın)", oran: `%${mstOran}`, vurgu: true, not: "kâr marjı üzerinden, şeffaf" },
            { yer: "Geleneksel yayınevleri", oran: "%8–15", vurgu: false, not: "genelde etiket üzerinden düşük" },
            { yer: "Çoğu dijital platform", oran: "%30–50", vurgu: false, not: "ama haklar devredilir" },
          ].map((r, i) => (
            <div key={i} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "12px 14px", borderBottom: i < 2 ? `1px solid ${THEME.divider}` : "none", background: r.vurgu ? "rgba(201,162,75,.08)" : "transparent" }}>
              <div>
                <div style={{ fontSize: 14.5, fontWeight: r.vurgu ? 700 : 500, color: r.vurgu ? THEME.success : THEME.textLight }}>{r.yer}</div>
                <div style={{ fontSize: 15, color: THEME.textMuted, marginTop: 2 }}>{r.not}</div>
              </div>
              <div style={{ fontSize: 16, fontWeight: 700, color: r.vurgu ? THEME.gold : THEME.textMuted, fontFamily: "'Cormorant Garamond', serif" }}>{r.oran}</div>
            </div>
          ))}
        </div>
        <div style={{ fontSize: 15, color: THEME.textMuted, marginTop: 8, lineHeight: 1.5 }}>
          MST'de yüksek telif + hakların sende kalması bir arada. Karşılaştırma oranları sektör ortalamalarıdır.
        </div>
      </div>
    </div>
  );
}

function NewBookForm({ onSubmit, submissions }) {
  const [open, setOpen] = useState(false);
  const [title, setTitle] = useState("");
  const [pages, setPages] = useState(150);
  const [note, setNote] = useState("");
  const [file, setFile] = useState(null);
  const handleFile = (e) => { const f = e.target.files[0]; if (!f) return; const reader = new FileReader(); reader.onload = () => setFile({ name: f.name, dataUrl: reader.result, isImage: f.type.startsWith("image/") }); reader.readAsDataURL(f); };
  const submit = (e) => { e.preventDefault(); if (!title.trim()) return; onSubmit({ title: title.trim(), pages: Number(pages), note, file }); setTitle(""); setNote(""); setFile(null); setOpen(false); };
  const inputStyle = { padding: "9px 11px", border: `1px solid ${THEME.border}`, borderRadius: 0, fontSize: 16, boxSizing: "border-box", background: THEME.yuzeyDik, color: THEME.textLight };
  return (
    <div style={{ marginBottom: 18 }}>
      {!open ? (
        <Dugme tur="asil" onClick={() => setOpen(true)}>+ Yeni Kitap Teslim Et</Dugme>
      ) : (
        <form onSubmit={submit} style={{ background: THEME.yuzey, border: `1px solid ${THEME.border}`, borderRadius: 0, padding: 14, display: "flex", flexDirection: "column", gap: 10 }}>
          <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 15, color: THEME.textLight }}>Yeni Eser Teslimi</div>
          <input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Kitabın başlığı" style={inputStyle} />
          <label style={{ fontSize: 15, color: THEME.textMuted }}>Sayfa sayısı<input type="number" min={1} value={pages} onChange={(e) => setPages(e.target.value)} style={{ display: "block", width: "100%", marginTop: 4, ...inputStyle }} /></label>
          <label style={{ fontSize: 15, color: THEME.textMuted }}>Eser dosyası (Word/PDF)
            <input type="file" accept=".doc,.docx,.pdf,application/msword,application/pdf" onChange={handleFile} style={{ display: "block", width: "100%", marginTop: 4, fontSize: 16, color: THEME.textLight }} />
          </label>
          {file && <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 14, color: THEME.success }}>📄 {file.name} yüklendi</div>}
          <textarea value={note} onChange={(e) => setNote(e.target.value)} placeholder="Yayınevine not (opsiyonel)" rows={2} style={{ ...inputStyle, resize: "vertical", fontFamily: "inherit" }} />
          <div style={{ fontSize: 14.5, color: THEME.textMuted, background: THEME.headerBg, borderRadius: 0, padding: "8px 10px", lineHeight: 1.5, border: `1px solid ${THEME.border}` }}>Dosyanız yüklendiğinde <strong style={{ color: THEME.cyan }}>dosyakontrol@mstyayincilik.com</strong> adresine otomatik bildirim gönderilir; yayınevi başvurunuzu inceleyip kabul ettiğinde kitabınız otomatik olarak yayın sürecine girer.</div>
          <div style={{ display: "flex", gap: 8 }}>
            <Dugme type="submit" tur="asil">Gönder</Dugme>
            <button type="button" onClick={() => setOpen(false)} style={{ background: "none", border: `1px solid ${THEME.border}`, color: THEME.textMuted, borderRadius: 0, padding: "9px 16px", fontSize: 14.5, cursor: "pointer" }}>Vazgeç</button>
          </div>
        </form>
      )}
      {submissions.length > 0 && (
        <div style={{ marginTop: 12 }}>
          {submissions.map((s) => (
            <div key={s.id} style={{ display: "flex", justifyContent: "space-between", fontSize: 14.5, background: THEME.yuzey, border: `1px solid ${THEME.border}`, borderRadius: 0, padding: "10px 14px", marginBottom: 6, color: THEME.textLight }}>
              <span>{s.title} <span style={{ color: THEME.textMuted }}>· {s.pages} sayfa{s.file ? " · 📄" : ""}</span></span>
              <span style={{ color: s.status === "İnceleniyor" ? THEME.warn : THEME.success }}>{s.status}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

